INITIAL_ASSETS.push(...ICU_BUILDING_EXITS, ...EASTERN_EXPANSION_EXITS, ...DENTAL_BUILDING_EXITS);

// Enrich College of Medicine (C) & Expansion (C2 - BLOCK-40) with official architectural block mapping
INITIAL_ASSETS.forEach(a => {
  if (a.building === 'توسعة كلية الطب') {
    a.buildingCode = 'C2';
    a.block = 'BLOCK-40';
    a.buildingOfficialAr = 'المبنى الغربي لكلية الطب (توسعة كلية الطب - بلك 40)';
    a.buildingOfficialEn = 'West Medicine College (BLOCK-40)';
    if (a.locationDetails && !a.locationDetails.includes('40')) {
      a.locationDetails = `بلك (40) - ${a.locationDetails}`;
    }
  } else if (a.building === 'كلية الطب') {
    a.buildingCode = 'C';
    a.buildingOfficialAr = 'المبنى الشرقي لكلية الطب (كلية الطب)';
    a.buildingOfficialEn = 'East Medicine College';
    if (!a.block) {
      const loc = `${a.name || ''} ${a.locationDetails || ''}`;
      if (loc.includes('(8-9)') || loc.includes('بلك (8)') || loc.includes('بلك 8')) a.block = 'BLOCK-08';
      else if (loc.includes('بلك (7)') || loc.includes('بلك 7')) a.block = 'BLOCK-07';
      else if (loc.includes('بلك (4)') && loc.includes('بلك (1)')) a.block = 'BLOCK-04 / BLOCK-01';
      else if (loc.includes('بلك (4)') || loc.includes('بلك 4')) a.block = 'BLOCK-04';
      else if (loc.includes('(1-2)') || loc.includes('بلك (1)') || loc.includes('بلك 1')) a.block = 'BLOCK-01';
      else if (loc.includes('(22)') || loc.includes('بلك 22')) a.block = 'BLOCK-22';
      else if (loc.includes('(23)') || loc.includes('بلك 23')) a.block = 'BLOCK-23';
      else a.block = 'كلية الطب (C)';
    }
  }
});

