// -------------------------------------------------------------
// DATE RANGE & TIMELINE FILTER UTILITY
// -------------------------------------------------------------
function isDateInPeriod(dateStr, period) {
  if (!dateStr || !period || period === 'all') return true;

  // Extract clean date string (supports 'YYYY-MM-DD', 'YYYY/MM/DD', or full ISO)
  const cleanStr = String(dateStr).trim().split(' ')[0].replace(/\//g, '-');
  const targetDate = new Date(cleanStr);
  if (isNaN(targetDate.getTime())) return true;

  const now = new Date();
  const targetMidnight = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());
  const nowMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());

  const diffMs = nowMidnight - targetMidnight;
  const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));

  if (diffDays < 0) return true; // Today or future dates
  if (period === 'day') return diffDays <= 1; // Last 24h or today
  if (period === 'week') return diffDays <= 7; // Last 7 days
  if (period === 'month') return diffDays <= 30; // Last 30 days
  if (period === 'year') return diffDays <= 365; // Last 365 days
  return true;
}

