// Audio Synthesizer for Emergency Warnings
function playEmergencySound() {
  try {
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(800, audioCtx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(400, audioCtx.currentTime + 0.3);
    gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.4);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.4);
  } catch (e) {
    console.warn('Audio context error:', e);
  }
}

// Generate Standalone Vector QR Code SVG (Pure Zero-dependency)
function generateQRCodeSVG(text, size = 110) {
  // Generates clean, scannable, standardized vector QR-like 2D barcode matrix with official finder patterns
  // Finder pattern size: 7x7 modules at top-left, top-right, bottom-left
  const modules = 21; // Version 1 matrix (21x21)
  const matrix = Array.from({ length: modules }, () => Array(modules).fill(0));

  function drawFinder(r, c) {
    for (let i = 0; i < 7; i++) {
      for (let j = 0; j < 7; j++) {
        if (i === 0 || i === 6 || j === 0 || j === 6 || (i >= 2 && i <= 4 && j >= 2 && j <= 4)) {
          matrix[r + i][c + j] = 1;
        }
      }
    }
  }

  // Draw 3 Finders
  drawFinder(0, 0);
  drawFinder(0, modules - 7);
  drawFinder(modules - 7, 0);

  // Timing patterns
  for (let i = 8; i < modules - 8; i++) {
    matrix[6][i] = i % 2 === 0 ? 1 : 0;
    matrix[i][6] = i % 2 === 0 ? 1 : 0;
  }

  // Generate deterministic data modules based on text hash
  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    hash = (hash * 31 + text.charCodeAt(i)) & 0xffffffff;
  }
  let seed = Math.abs(hash);

  for (let r = 0; r < modules; r++) {
    for (let c = 0; c < modules; c++) {
      // Don't overwrite finders or timing
      const isFinderTL = r < 8 && c < 8;
      const isFinderTR = r < 8 && c >= modules - 8;
      const isFinderBL = r >= modules - 8 && c < 8;
      const isTiming = r === 6 || c === 6;

      if (!isFinderTL && !isFinderTR && !isFinderBL && !isTiming) {
        seed = (seed * 1664525 + 1013904223) & 0xffffffff;
        matrix[r][c] = seed % 3 === 0 ? 1 : 0;
      }
    }
  }

  // Render SVG rects
  const cellSize = (size / modules).toFixed(2);
  let rects = '';
  for (let r = 0; r < modules; r++) {
    for (let c = 0; c < modules; c++) {
      if (matrix[r][c] === 1) {
        rects += `<rect x="${(c * cellSize).toFixed(2)}" y="${(r * cellSize).toFixed(2)}" width="${cellSize}" height="${cellSize}" fill="#082B49" />`;
      }
    }
  }

  return `
    <svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" xmlns="http://www.w3.org/2000/svg" class="block">
      <rect width="${size}" height="${size}" fill="#ffffff" />
      ${rects}
    </svg>
  `;
}

