// Export Assets to CSV
function exportAssetsCSV() {
  const filtered = getFilteredAssets();
  if (filtered.length === 0) {
    alert('لا توجد نتائج لتصديرها.');
    return;
  }

  // UTF-8 BOM for Arabic support in Excel
  let csv = '\uFEFF';
  csv += 'كود الأصل,اسم الأصل,التصنيف,النوع,المستشفى,المبنى,الدور,الموقع الدقيق,الحالة الفنية,تاريخ أول فحص,تاريخ آخر فحص,المفتش,ملاحظات\n';

  filtered.forEach(a => {
    const row = [
      `"${a.id}"`,
      `"${a.name}"`,
      `"${a.category}"`,
      `"${a.type}"`,
      `"${a.hospital}"`,
      `"${a.building}"`,
      `"${a.floor}"`,
      `"${a.locationDetails}"`,
      `"${a.status}"`,
      `"${a.firstInspectionDate || ''}"`,
      `"${a.lastInspectionDate || ''}"`,
      `"${a.inspector || ''}"`,
      `"${(a.notes || '').replace(/"/g, '""')}"`
    ];
    csv += row.join(',') + '\n';
  });

  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `KSUMC_Assets_Inventory_${new Date().toISOString().split('T')[0]}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  showToast('تم تصدير ملف بيانات الأصول (CSV / Excel) بنجاح.', 'success');
}

// -------------------------------------------------------------
// ADMIN SUB-TABS SWITCHER & MODULES
// -------------------------------------------------------------
function switchAdminSubTab(subTabId) {
  state.activeAdminSubTab = subTabId;

  document.querySelectorAll('.admin-subtab-btn').forEach(btn => {
    const target = btn.getAttribute('data-subtab');
    if (target === subTabId) {
      btn.classList.add('bg-primary', 'text-white', 'shadow-sm');
      btn.classList.remove('bg-surface-container-low', 'text-on-surface-variant', 'hover:bg-surface-container');
    } else {
      btn.classList.remove('bg-primary', 'text-white', 'shadow-sm');
      btn.classList.add('bg-surface-container-low', 'text-on-surface-variant', 'hover:bg-surface-container');
    }
  });

  document.querySelectorAll('.admin-subtab-pane').forEach(pane => {
    if (pane.id === 'pane-' + subTabId) {
      pane.classList.remove('hidden');
    } else {
      pane.classList.add('hidden');
    }
  });

  if (subTabId === 'admin-buildings') renderAdminBuildings();
  if (subTabId === 'admin-checklists') renderAdminChecklist();
  if (subTabId === 'admin-schedules') renderAdminSchedule();
  if (subTabId === 'admin-users') renderAdminUsers();
  if (subTabId === 'admin-metrics') renderAdminMetrics();
  if (subTabId === 'admin-qr-cards') renderPortalQRCards();
}

// -------------------------------------------------------------
// PORTAL DIRECT QR CODES & ACCESS CARDS
// -------------------------------------------------------------
function renderPortalQRCards() {
  const portals = ['field', 'quality', 'executive', 'admin'];
  const colors = {
    field: '#065f46',
    quality: '#92400e',
    executive: '#004B87',
    admin: '#581c87'
  };

  const isHosted = window.location.hostname.includes('web.app') || window.location.hostname.includes('firebaseapp.com');
  const baseOrigin = isHosted 
    ? (window.location.origin + window.location.pathname).replace(/\/+$/, '') 
    : 'https://rsd-go-demo.web.app';

  portals.forEach(portalKey => {
    const targetUrl = `${baseOrigin}/?portal=${portalKey}`;
    
    // Update displayed URL
    const urlEl = document.getElementById(`qr-url-${portalKey}`);
    if (urlEl) {
      urlEl.textContent = targetUrl;
    }

    // Render QR Code using standalone QRCode library
    const container = document.getElementById(`qr-container-${portalKey}`);
    if (container) {
      container.innerHTML = '';
      if (typeof QRCode !== 'undefined') {
        try {
          new QRCode(container, {
            text: targetUrl,
            width: 140,
            height: 140,
            colorDark: colors[portalKey] || '#004B87',
            colorLight: '#ffffff',
            correctLevel: QRCode.CorrectLevel.M
          });
        } catch (e) {
          console.warn(`[QR] Error generating QR for ${portalKey}:`, e);
          container.innerHTML = `<div class="text-xs text-error font-mono p-2">تعذر توليد الرمز: ${e.message}</div>`;
        }
      } else {
        container.innerHTML = `<div class="text-xs text-on-surface-variant p-2 font-mono">${targetUrl}</div>`;
      }
    }
  });
}

function copyPortalLink(portalKey) {
  const urlEl = document.getElementById(`qr-url-${portalKey}`);
  const url = urlEl ? urlEl.textContent.trim() : `https://rsd-go-demo.web.app/?portal=${portalKey}`;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(() => {
      showToast('تم نسخ الرابط المباشر إلى الحافظة بنجاح ✓', 'success');
    }).catch(() => {
      fallbackCopyPortalLink(url);
    });
  } else {
    fallbackCopyPortalLink(url);
  }
}

function fallbackCopyPortalLink(text) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    showToast('تم نسخ الرابط المباشر إلى الحافظة بنجاح ✓', 'success');
  } catch (e) {
    showToast('تعذر النسخ التلقائي: يرجى نسخ الرابط يدوياً', 'warning');
  }
}

