/// Official Building Blocks Map (from KSUMC Engineering & Architectural Master Plan)
const OFFICIAL_BUILDING_BLOCKS_MAP = {
  'C': ['BLOCK-01', 'BLOCK-02', 'BLOCK-04', 'BLOCK-05', 'BLOCK-07', 'BLOCK-08', 'BLOCK-22', 'BLOCK-23'],
  'كلية الطب': ['BLOCK-01', 'BLOCK-02', 'BLOCK-04', 'BLOCK-05', 'BLOCK-07', 'BLOCK-08', 'BLOCK-22', 'BLOCK-23'],
  'C2': ['BLOCK-40'],
  'توسعة كلية الطب': ['BLOCK-40']
};

function resolveCanonicalBuildingCode(rawBuilding) {
  if (!rawBuilding) return '';
  const b = String(rawBuilding).trim();
  if (!b) return '';

  const upper = b.toUpperCase();
  if (['A', 'B', 'C', 'C2', 'D', 'E', 'F', 'G', 'H', 'O', 'I'].includes(upper)) {
    return upper;
  }

  // 4. توسعة كلية الطب (West Medicine College - Code C2 - BLOCK-40 ONLY)
  // MUST be evaluated BEFORE 'كلية الطب' because 'توسعة كلية الطب' contains the substring 'كلية الطب'
  if (
    b.includes('توسعة كلية الطب') ||
    b.includes('توسعه كليه الطب') ||
    b.includes('توسعة الكلية') ||
    b.includes('توسعه الكليه') ||
    b.includes('المبنى الغربي لكلية الطب') ||
    b.toLowerCase().includes('west medicine college') ||
    b.includes('BLOCK-40') ||
    b.includes('بلك 40') ||
    b.includes('بلك (40)')
  ) {
    return 'C2';
  }

  // 3. كلية الطب (East Medicine College - Code C - Blocks 1, 2, 4, 5, 7, 8, 22, 23)
  if (
    (b.includes('كلية الطب') || b.includes('كليه الطب') || b.includes('المبنى الشرقي لكلية الطب') || b.toLowerCase().includes('east medicine college')) &&
    !b.includes('توسعة') &&
    !b.includes('توسعه') &&
    !b.includes('الغربي')
  ) {
    return 'C';
  }

  // 2. التوسعة الشرقية / المستشفى الشرقي (Eastern Expansion - Code B - BLOCK-35)
  if (b.includes('التوسعة الشرق') || b.includes('التوسعه الشرق') || b.includes('المستشفى الشرقي') || b.toLowerCase().includes('east hospital') || b.toLowerCase().includes('eastern expansion')) {
    return 'B';
  }

  // 8. مبنى الاسنان (Dental Hospital - Code G)
  if (b.includes('الاسنان') || b.includes('الأسنان') || b.toLowerCase().includes('dental')) {
    return 'G';
  }

  // 1. المستشفى / المستشفى الغربي (Main / West Hospital - Code A)
  if (
    (b === 'المستشفى' || b.includes('المستشفى الرئيسي') || b.includes('المستشفى الغربي') || b.includes('البرج الرئيسي') || b.toLowerCase().includes('west hospital') || b.toLowerCase().includes('hospital main')) &&
    !b.includes('الاسنان') &&
    !b.includes('الأسنان') &&
    !b.includes('الأورام') &&
    !b.includes('الشرقي')
  ) {
    return 'A';
  }

  // 5. المبنى الإداري (Administration - Code D - BLOCK-36)
  if (b.includes('المبنى الإداري') || b.includes('المبنى الاداري') || b.includes('مبنى الإدارة') || b.includes('مبنى الادارة') || b.toLowerCase().includes('administrative') || b.toLowerCase().includes('administration')) {
    return 'D';
  }

  // 6. مبنى العيادات (Outpatient Clinics - Code E - BLOCK-28 / BLOCK-33)
  if (b.includes('العيادات') || b.toLowerCase().includes('clinic')) {
    return 'E';
  }

  // 7. مواقف متعددة الأدوار (Multi-story Parking - Code F)
  if (b.includes('متعددة الأدوار') || b.includes('متعددة الادوار')) {
    return 'F';
  }

  // 9. العناية المركزة (ICU - Code H - BLOCK-34)
  if (b.includes('العناية المركزة') || b.includes('العنايه المركزه') || b.toUpperCase().includes('ICU')) {
    return 'H';
  }

  // 10. المستودعات الخارجية / المولدات والمستودعات (Warehouses & Generators - Code O - BLOCK-00 / BLOCK-47)
  if (b.includes('المستودعات') || b.includes('المولدات') || b.toLowerCase().includes('warehouse') || b.toLowerCase().includes('generator')) {
    return 'O';
  }

  // 11. مواقف 25 (Parking 25 - Code I)
  if (b.includes('25')) {
    return 'I';
  }

  // 12. أخرى / موقع آخر
  if (b.includes('أخرى') || b.includes('اخرى') || b.toLowerCase().includes('other')) {
    return 'OTHER';
  }

  return '';
}

// Smart matching for buildings across historical naming variations (Strictly isolates C vs C2)
function matchBuilding(assetBuilding, targetBuilding) {
  if (!assetBuilding || !targetBuilding) return false;
  if (targetBuilding === 'all' || assetBuilding === 'all') return true;
  if (assetBuilding === targetBuilding) return true;
  
  const b1 = String(assetBuilding).trim();
  const b2 = String(targetBuilding).trim();
  if (b1 === b2) return true;

  const code1 = resolveCanonicalBuildingCode(b1);
  const code2 = resolveCanonicalBuildingCode(b2);

  // If either string maps to a known canonical building code, ONLY match if both map to the EXACT same code!
  // This guarantees 'كلية الطب' (C) NEVER matches 'توسعة كلية الطب' (C2) via substring inclusion.
  if (code1 || code2) {
    return Boolean(code1 && code2 && code1 === code2);
  }

  return b1 === b2;
}

// Smart matching for floors across variations (e.g. 'الدور الأرضي (G)' vs 'الدور الأرضي' vs 'G')
function matchFloor(assetFloor, targetFloor) {
  if (!assetFloor || !targetFloor) return false;
  if (targetFloor === 'all' || assetFloor === 'all') return true;
  if (assetFloor === targetFloor) return true;

  const f1 = String(assetFloor).trim();
  const f2 = String(targetFloor).trim();
  if (f1 === f2) return true;

  const extractCode = (str) => {
    const paren = str.match(/\(([^)]+)\)/);
    if (paren) {
      let p = paren[1].trim().toUpperCase();
      if (p.startsWith('ICU-')) p = p.replace('ICU-', '');
      if (p === 'ROOF') return 'R';
      return p;
    }
    const upper = str.toUpperCase();
    if (upper.includes('السطح') || upper.includes('ROOF') || upper === 'R') return 'R';
    if (str.includes('الأرضي') || str.includes('الارضي') || str.includes('G00')) return 'G';
    if (str.includes('القبو الثالث') || str.includes('B3') || str.includes('B03')) return 'B3';
    if (str.includes('القبو الثاني') || str.includes('B2') || str.includes('B02')) return 'B2';
    if (str.includes('القبو الأول') || str.includes('القبو الاول') || str.includes('B1') || str.includes('B01')) return 'B1';
    if (str.includes('القبو') || str.includes('B')) return 'B';
    if (str.includes('العاشر') || str.includes('10')) return '10';
    if (str.includes('التاسع') || str.includes('9')) return '9';
    if (str.includes('الثامن') || str.includes('8')) return '8';
    if (str.includes('السابع') || str.includes('7')) return '7';
    if (str.includes('السادس') || str.includes('6')) return '6';
    if (str.includes('الخامس') || str.includes('5')) return '5';
    if (str.includes('الرابع') || str.includes('4')) return '4';
    if (str.includes('الثالث') || str.includes('3')) return '3';
    if (str.includes('الثاني') || str.includes('2')) return '2';
    if (str.includes('الأول') || str.includes('الاول') || str.includes('1')) return '1';
    return str;
  };

  const c1 = extractCode(f1);
  const c2 = extractCode(f2);
  if (c1 && c2 && c1 === c2) return true;
  if ((c1 === 'B' && c2 === 'B1') || (c1 === 'B1' && c2 === 'B')) return true;

  return f1.includes(f2) || f2.includes(f1);
}

function getAllFm200Assets() {
  const fromState = (state.assets || []).filter(a => (a.category && (a.category.includes('FM') || a.category.includes('غاز'))) || (a.id && a.id.startsWith('FM')));
  if (fromState.length > 0) return fromState;
  return (typeof KSU_FM200_ASSETS !== 'undefined' && Array.isArray(KSU_FM200_ASSETS)) ? KSU_FM200_ASSETS : [];
}

function getAllFhcAssets() {
  const fromState = (state.assets || []).filter(a =>
    (a.category && (a.category.includes('صناديق') || a.category.includes('خراطيم'))) ||
    (a.type && (a.type.includes('صندوق') || a.type.includes('خرطوم'))) ||
    (a.id && (a.id.startsWith('FHC-') || a.id.startsWith('FH-') || a.id.startsWith('PL0') || a.id.startsWith('PL')))
  );
  if (fromState.length > 0) return fromState;
  return (typeof KSU_FHC_ASSETS !== 'undefined' && Array.isArray(KSU_FHC_ASSETS)) ? KSU_FHC_ASSETS : [];
}

function getAllPlantRoomAssets() {
  const fromState = (state.assets || []).filter(a =>
    (a.category && (a.category.includes('صناعية') || a.category.includes('الغرف الصناعية'))) ||
    (a.id && a.id.startsWith('IND-'))
  );
  if (fromState.length > 0) return fromState;
  return (typeof KSU_PLANT_ROOM_ASSETS !== 'undefined' && Array.isArray(KSU_PLANT_ROOM_ASSETS)) ? KSU_PLANT_ROOM_ASSETS : [];
}

function populateRoundFloorOptions(selectedBuilding, desiredFloor = null) {
  const floorSelect = document.getElementById('inp-round-floor');
  if (!floorSelect) return;
  const formType = (state.currentRoundDraft && state.currentRoundDraft.formType) || document.getElementById('inp-round-form-type')?.value || 'fex';

  if (formType === 'fm200') {
    const fmAssets = getAllFm200Assets();
    const bldFmAssets = selectedBuilding === 'all'
      ? fmAssets
      : fmAssets.filter(a => matchBuilding(a.building || a.buildingTab, selectedBuilding));

    let baseFloors = [];
    if (selectedBuilding === 'all') {
      baseFloors = ['القبو الثاني (B2)', 'القبو الأول (B1)', 'الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)'];
    } else {
      baseFloors = BUILDING_FLOOR_MAP[selectedBuilding] || ['القبو الثاني (B2)', 'القبو الأول (B1)', 'الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)'];
    }

    // Ensure any floor present in bldFmAssets is included
    bldFmAssets.forEach(a => {
      if (a.floor && !baseFloors.some(f => matchFloor(f, a.floor))) {
        baseFloors.push(a.floor);
      }
    });

    const optionsHtml = [
      `<option value="all">جميع الأدوار (${bldFmAssets.length} نظام FM-200)</option>`,
      ...baseFloors.map(f => {
        const cnt = bldFmAssets.filter(a => matchFloor(a.floor, f)).length;
        return `<option value="${f}">${f}${cnt > 0 ? ` — [${cnt} نظام FM-200]` : ' — (لا يوجد نظام)'}</option>`;
      })
    ];
    floorSelect.innerHTML = optionsHtml.join('');

    const targetFloor = desiredFloor || state.currentRoundDraft?.floor || 'الدور الأرضي (G)';
    const targetCount = targetFloor === 'all' ? bldFmAssets.length : bldFmAssets.filter(a => matchFloor(a.floor, targetFloor)).length;

    if (targetFloor === 'all') {
      floorSelect.value = 'all';
    } else if (baseFloors.includes(targetFloor) && targetCount > 0) {
      floorSelect.value = targetFloor;
    } else {
      // Automatically pick the first floor in this building that actually has FM-200 systems
      const firstFloorWithFm = baseFloors.find(f => bldFmAssets.some(a => matchFloor(a.floor, f)));
      floorSelect.value = firstFloorWithFm || 'all';
    }
    if (state.currentRoundDraft) {
      state.currentRoundDraft.floor = floorSelect.value;
    }
    return;
  }

  if (formType === 'fhc') {
    const fhcAssets = getAllFhcAssets();
    const bldFhcAssets = selectedBuilding === 'all'
      ? fhcAssets
      : fhcAssets.filter(a => matchBuilding(a.building || a.buildingTab, selectedBuilding));

    let baseFloors = [];
    if (selectedBuilding === 'all') {
      baseFloors = ['القبو الثاني (B2)', 'القبو الأول (B1)', 'الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)', 'الدور الرابع (4)', 'السطح (Roof)'];
    } else {
      baseFloors = [...(BUILDING_FLOOR_MAP[selectedBuilding] || ['القبو الثاني (B2)', 'القبو الأول (B1)', 'الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)', 'الدور الرابع (4)', 'السطح (Roof)'])];
    }

    // Ensure any floor present in bldFhcAssets is included
    bldFhcAssets.forEach(a => {
      if (a.floor && !baseFloors.some(f => matchFloor(f, a.floor))) {
        baseFloors.push(a.floor);
      }
    });

    const optionsHtml = [
      `<option value="all">جميع الأدوار (${bldFhcAssets.length} صندوق حريق)</option>`,
      ...baseFloors.map(f => {
        const cnt = bldFhcAssets.filter(a => matchFloor(a.floor, f)).length;
        return `<option value="${f}">${f}${cnt > 0 ? ` — [${cnt} صندوق حريق]` : ' — (لا يوجد)'}</option>`;
      })
    ];
    floorSelect.innerHTML = optionsHtml.join('');

    const targetFloor = desiredFloor || state.currentRoundDraft?.floor || 'all';
    const targetCount = targetFloor === 'all' ? bldFhcAssets.length : bldFhcAssets.filter(a => matchFloor(a.floor, targetFloor)).length;

    if (targetFloor === 'all') {
      floorSelect.value = 'all';
    } else if (baseFloors.includes(targetFloor) && targetCount > 0) {
      floorSelect.value = targetFloor;
    } else {
      const firstFloorWithFhc = baseFloors.find(f => bldFhcAssets.some(a => matchFloor(a.floor, f)));
      floorSelect.value = firstFloorWithFhc || 'all';
    }
    if (state.currentRoundDraft) {
      state.currentRoundDraft.floor = floorSelect.value;
    }
    return;
  }

  if (formType === 'ind_room') {
    const indAssets = getAllPlantRoomAssets();
    const bldIndAssets = selectedBuilding === 'all'
      ? indAssets
      : indAssets.filter(a => matchBuilding(a.building || a.buildingTab, selectedBuilding));

    let baseFloors = [];
    if (selectedBuilding === 'all') {
      baseFloors = ['القبو الثاني (B2)', 'القبو الأول (B1)', 'الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)', 'السطح (Roof)'];
    } else {
      baseFloors = [...(BUILDING_FLOOR_MAP[selectedBuilding] || ['القبو الثاني (B2)', 'القبو الأول (B1)', 'الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)', 'السطح (Roof)'])];
    }

    // Ensure any floor present in bldIndAssets is included
    bldIndAssets.forEach(a => {
      if (a.floor && !baseFloors.some(f => matchFloor(f, a.floor))) {
        baseFloors.push(a.floor);
      }
    });

    const optionsHtml = [
      `<option value="all">جميع الأدوار (${bldIndAssets.length} غرفة صناعية)</option>`,
      ...baseFloors.map(f => {
        const cnt = bldIndAssets.filter(a => matchFloor(a.floor, f)).length;
        return `<option value="${f}">${f}${cnt > 0 ? ` — [${cnt} غرفة صناعية]` : ' — (لا يوجد)'}</option>`;
      })
    ];
    floorSelect.innerHTML = optionsHtml.join('');

    const targetFloor = desiredFloor || state.currentRoundDraft?.floor || 'all';
    const targetCount = targetFloor === 'all' ? bldIndAssets.length : bldIndAssets.filter(a => matchFloor(a.floor, targetFloor)).length;

    if (targetFloor === 'all') {
      floorSelect.value = 'all';
    } else if (baseFloors.includes(targetFloor) && targetCount > 0) {
      floorSelect.value = targetFloor;
    } else {
      const firstFloorWithRoom = baseFloors.find(f => bldIndAssets.some(a => matchFloor(a.floor, f)));
      floorSelect.value = firstFloorWithRoom || 'all';
    }
    if (state.currentRoundDraft) {
      state.currentRoundDraft.floor = floorSelect.value;
    }
    return;
  }

  const floors = BUILDING_FLOOR_MAP[selectedBuilding] || ['الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)'];
  floorSelect.innerHTML = floors.map(f => `<option value="${f}">${f}</option>`).join('');
  const targetFloor = desiredFloor || state.currentRoundDraft?.floor || 'الدور الأرضي (G)';
  if (floors.includes(targetFloor)) {
    floorSelect.value = targetFloor;
  } else {
    floorSelect.value = floors[0];
  }
  if (state.currentRoundDraft) {
    state.currentRoundDraft.floor = floorSelect.value;
  }
}

function populateDynamicDropdowns() {
  const formType = (state.currentRoundDraft && state.currentRoundDraft.formType) || document.getElementById('inp-round-form-type')?.value || 'fex';
  const buildingSelect = document.getElementById('inp-round-building');
  if (buildingSelect) {
    const bldAliasLabels = {
      'المستشفى': 'المستشفى (المستشفى الغربي - KKUH)',
      'التوسعة الشرقية': 'التوسعة الشرقية (المستشفى الشرقي - بلك 35)',
      'كلية الطب': 'كلية الطب (المبنى الشرقي)',
      'توسعة كلية الطب': 'توسعة كلية الطب (المبنى الغربي - بلك 40)',
      'المبنى الإداري': 'المبنى الإداري (بلك 36)',
      'مبنى العيادات': 'مبنى العيادات (العيادات الخارجية - بلك 28، 33)',
      'مواقف متعددة الأدوار': 'مواقف متعددة الأدوار',
      'مبنى الاسنان': 'مبنى الاسنان (مستشفى طب الأسنان)',
      'العناية المركزة': 'العناية المركزة (بلك 34)',
      'مواقف 25': 'مواقف 25',
      'المستودعات الخارجية': 'المستودعات الخارجية (المولدات والمستودعات - بلك 00، 47)',
      'أخرى': 'موقع / مبنى آخر (حدد في القسم والملاحظات)',
      'أخرى (موقع / مبنى آخر)': 'موقع / مبنى آخر (حدد في القسم والملاحظات)'
    };
    const bldList = (state.buildings && state.buildings.length >= 10) ? state.buildings : INITIAL_BUILDINGS;
    if (formType === 'fm200') {
      const fmAssets = getAllFm200Assets();
      buildingSelect.innerHTML = `<option value="all">🏢 جميع مباني المدينة الطبية (${fmAssets.length} نظام FM-200)</option>` +
        bldList.map(b => {
          const cnt = fmAssets.filter(a => matchBuilding(a.building || a.buildingTab, b.name)).length;
          const displayName = bldAliasLabels[b.name] || b.name;
          return `<option value="${b.name}">[${b.code}] ${displayName}${cnt > 0 ? ` — (${cnt} نظام FM-200)` : ' — (0)'}</option>`;
        }).join('');
    } else if (formType === 'ind_room') {
      const indAssets = getAllPlantRoomAssets();
      buildingSelect.innerHTML = `<option value="all">⚙️ جميع مباني المدينة الطبية (${indAssets.length} غرفة صناعية)</option>` +
        bldList.map(b => {
          const cnt = indAssets.filter(a => matchBuilding(a.building || a.buildingTab, b.name)).length;
          const displayName = bldAliasLabels[b.name] || b.name;
          return `<option value="${b.name}">[${b.code}] ${displayName}${cnt > 0 ? ` — (${cnt} غرفة صناعية)` : ' — (0)'}</option>`;
        }).join('');
    } else {
      buildingSelect.innerHTML = bldList.map(b => {
        const displayName = bldAliasLabels[b.name] || b.name;
        return `<option value="${b.name}">[${b.code}] ${displayName}</option>`;
      }).join('');
    }
    const desiredBuilding = state.currentRoundDraft?.building || (bldList && bldList.length > 0 ? bldList[0].name : 'المستشفى');
    if (desiredBuilding === 'all' && (formType === 'fm200' || formType === 'ind_room')) {
      buildingSelect.value = 'all';
    } else if (bldList.some(b => b.name === desiredBuilding)) {
      buildingSelect.value = desiredBuilding;
    }
  }

  const selectedBuilding = buildingSelect ? buildingSelect.value : (state.currentRoundDraft?.building || (state.buildings && state.buildings.length > 0 ? state.buildings[0].name : 'المستشفى'));
  populateRoundFloorOptions(selectedBuilding, state.currentRoundDraft?.floor);

  const badgeText = document.getElementById('round-location-verification-text');
  if (badgeText) {
    badgeText.textContent = selectedBuilding === 'all'
      ? 'تم التحقق من سجل أصول المدينة الطبية الشامل (جميع المباني)'
      : `تم التحقق من التواجد بالموقع (${selectedBuilding})`;
  }

  const inspectorSelect = document.getElementById('inp-round-inspector');
  if (inspectorSelect) {
    const activeInspectors = (state.users && state.users.length) ? state.users.filter(u => u.status === 'نشط') : [];
    const activeUser = state.currentUser || (window.KSUAuth && typeof window.KSUAuth.getUser === 'function' ? window.KSUAuth.getUser() : null);
    const targetInspectorName = (activeUser && activeUser.name) ? activeUser.name : (inspectorSelect.value || (activeInspectors[0] ? activeInspectors[0].name : ''));

    let optionsHtml = activeInspectors.map(u => `<option value="${u.name}">${u.name} (${u.role})</option>`).join('');
    if (activeUser && activeUser.name && !activeInspectors.some(u => u.name === activeUser.name)) {
      optionsHtml = `<option value="${activeUser.name}">${activeUser.name} (${activeUser.role || 'مفتش سلامة'})</option>` + optionsHtml;
    }
    inspectorSelect.innerHTML = optionsHtml;
    if (targetInspectorName) {
      inspectorSelect.value = targetInspectorName;
    }
  }

  const assetHospFilter = document.getElementById('filter-asset-hospital');
  if (assetHospFilter) {
    const currentVal = assetHospFilter.value || 'all';
    assetHospFilter.innerHTML = `<option value="all">جميع المباني والأقسام المعتمدة</option>` +
      (state.buildings || []).map(b => `<option value="${b.code}">${b.code} - ${b.name}</option>`).join('');
    if (currentVal && Array.from(assetHospFilter.options).some(o => o.value === currentVal)) {
      assetHospFilter.value = currentVal;
    }
  }

  // Populate Shift Incidents building dropdown
  const incBldSelect = document.getElementById('inp-shift-inc-building');
  if (incBldSelect) {
    const currentVal = incBldSelect.value;
    incBldSelect.innerHTML = (state.buildings || []).map(b => `<option value="${b.name}">[${b.code}] ${b.name}</option>`).join('');
    if (currentVal) incBldSelect.value = currentVal;
    onShiftIncidentBuildingChange(incBldSelect.value || (state.buildings[0] ? state.buildings[0].name : 'المستشفى'));
  }

  // Populate Coverage Matrix building filter
  const covBldFilter = document.getElementById('coverage-bld-filter');
  if (covBldFilter) {
    const prev = covBldFilter.value || 'all';
    covBldFilter.innerHTML = `<option value="all">كافة المباني الـ 11 المعتمدة</option>` +
      (state.buildings || []).map(b => `<option value="${b.name}">[${b.code}] ${b.name}</option>`).join('');
    covBldFilter.value = prev;
  }

  renderFloorAssetsReconciliation();
}

function onShiftIncidentBuildingChange(bldName) {
  const floorSelect = document.getElementById('inp-shift-inc-floor');
  if (!floorSelect) return;
  const floors = BUILDING_FLOOR_MAP[bldName] || ['الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)'];
  const prevFloor = floorSelect.value;
  floorSelect.innerHTML = floors.map(f => `<option value="${f}">${f}</option>`).join('');
  if (floors.includes(prevFloor)) {
    floorSelect.value = prevFloor;
  } else {
    floorSelect.value = floors[0];
  }
}

function onRoundBuildingChange(buildingName) {
  if (!state.currentRoundDraft) state.currentRoundDraft = {};
  state.currentRoundDraft.building = buildingName;

  const bldSelect = document.getElementById('inp-round-building');
  if (bldSelect && bldSelect.value !== buildingName) {
    bldSelect.value = buildingName;
  }

  const badgeText = document.getElementById('round-location-verification-text');
  if (badgeText) {
    badgeText.textContent = buildingName === 'all'
      ? 'تم التحقق من سجل أصول المدينة الطبية الشامل (جميع المباني)'
      : `تم التحقق من التواجد بالموقع (${buildingName})`;
  }

  populateRoundFloorOptions(buildingName, null);

  state.currentRoundDraft.floorAssetsStatus = null;
  renderFloorAssetsReconciliation();
}

function onRoundFloorChange(floorName) {
  if (!state.currentRoundDraft) state.currentRoundDraft = {};
  state.currentRoundDraft.floor = floorName;
  const floorSelect = document.getElementById('inp-round-floor');
  if (floorSelect && floorSelect.value !== floorName) {
    floorSelect.value = floorName;
  }
  state.currentRoundDraft.floorAssetsStatus = null;
  renderFloorAssetsReconciliation();
}

function onFm200RoundSearch(queryStr) {
  if (!state.currentRoundDraft) state.currentRoundDraft = {};
  state.currentRoundDraft.fm200SearchQuery = queryStr || '';
  renderFloorAssetsReconciliation();
}

function renderFloorAssetsReconciliation() {
  const container = document.getElementById('round-floor-assets-reconciliation-widget');
  if (!container) return;

  const currentBuilding = document.getElementById('inp-round-building')?.value || state.currentRoundDraft?.building || 'المستشفى';
  const currentFloor = document.getElementById('inp-round-floor')?.value || state.currentRoundDraft?.floor || 'الدور الأرضي (G)';
  const formType = (state.currentRoundDraft && state.currentRoundDraft.formType) || document.getElementById('inp-round-form-type')?.value || 'fex';
  const fm200Search = (state.currentRoundDraft?.fm200SearchQuery || '').trim().toLowerCase();

  // 5 inspection forms currently have registered assets in the system:
  // Fire Extinguishers (fex), FM-200 (fm200), Emergency Exits (ext), Fire Hose Cabinets (fhc), Plant Rooms (ind_room)
  const assetSupportedForms = ['fex', 'fm200', 'ext', 'fhc', 'ind_room'];
  if (!assetSupportedForms.includes(formType)) {
    container.classList.add('hidden');
    container.innerHTML = '';
    if (state.currentRoundDraft) {
      state.currentRoundDraft.floorAssetsStatus = {};
      state.currentRoundDraft.assetStats = {
        registered: 0,
        compliant: 0,
        needsMaintenance: 0,
        missing: 0,
        coverage: 100
      };
    }
    return;
  }
  container.classList.remove('hidden');

  // Filter assets on this building & floor using flexible smart matchers
  let floorAssets = [];
  if (formType === 'fm200') {
    const allFm200 = getAllFm200Assets();
    floorAssets = allFm200.filter(a =>
      matchBuilding(a.building || a.buildingTab, currentBuilding) &&
      matchFloor(a.floor, currentFloor)
    );
    if (fm200Search) {
      floorAssets = floorAssets.filter(a =>
        (a.id && a.id.toLowerCase().includes(fm200Search)) ||
        (a.controlNo && a.controlNo.toLowerCase().includes(fm200Search)) ||
        (a.block && a.block.toLowerCase().includes(fm200Search)) ||
        (a.room && String(a.room).toLowerCase().includes(fm200Search)) ||
        (a.locationCode && a.locationCode.toLowerCase().includes(fm200Search)) ||
        (a.manufacturer && a.manufacturer.toLowerCase().includes(fm200Search)) ||
        (a.model && a.model.toLowerCase().includes(fm200Search)) ||
        (a.buildingTab && a.buildingTab.toLowerCase().includes(fm200Search)) ||
        (a.locationDetails && a.locationDetails.toLowerCase().includes(fm200Search))
      );
    }
  } else if (formType === 'ind_room') {
    const allPlantRooms = getAllPlantRoomAssets();
    floorAssets = allPlantRooms.filter(a =>
      matchBuilding(a.building || a.buildingTab, currentBuilding) &&
      matchFloor(a.floor, currentFloor)
    );
  } else {
    floorAssets = (state.assets || []).filter(a => matchBuilding(a.building, currentBuilding) && matchFloor(a.floor, currentFloor));

    // Filter by category based strictly on active inspection form type
    if (formType === 'fex') {
      floorAssets = floorAssets.filter(a => a.category === 'طفايات الحريق' || (a.id && (a.id.startsWith('FE-') || a.id.startsWith('EXT-'))));
    } else if (formType === 'ext') {
      floorAssets = floorAssets.filter(a => a.category === 'مخارج الطوارئ' || (a.id && a.id.startsWith('EX-')));
    } else if (formType === 'fhc') {
      floorAssets = floorAssets.filter(a =>
        (a.category && (a.category.includes('صناديق') || a.category.includes('خراطيم'))) ||
        (a.type && (a.type.includes('صندوق') || a.type.includes('خرطوم'))) ||
        (a.id && (a.id.startsWith('FHC-') || a.id.startsWith('FH-') || a.id.startsWith('PL0') || a.id.startsWith('PL')))
      );
    } else {
      floorAssets = [];
    }
  }

  // Initialize draft statuses if not set
  if (!state.currentRoundDraft.floorAssetsStatus) {
    state.currentRoundDraft.floorAssetsStatus = {};
    floorAssets.forEach((a, idx) => {
      if (currentBuilding.includes('العيادات') && currentFloor.includes('G') && floorAssets.length === 12 && formType === 'fex') {
        state.currentRoundDraft.floorAssetsStatus[a.id] = (idx < 4) ? 'compliant' : 'pending';
      } else {
        state.currentRoundDraft.floorAssetsStatus[a.id] = 'pending';
      }
    });
  } else {
    floorAssets.forEach(a => {
      if (!state.currentRoundDraft.floorAssetsStatus[a.id]) {
        state.currentRoundDraft.floorAssetsStatus[a.id] = 'pending';
      }
    });
  }

  const totalRegistered = floorAssets.length;
  const compliantCount = floorAssets.filter(a => state.currentRoundDraft.floorAssetsStatus[a.id] === 'compliant').length;
  const observationCount = floorAssets.filter(a => state.currentRoundDraft.floorAssetsStatus[a.id] === 'observation').length;
  const missingCount = floorAssets.filter(a => state.currentRoundDraft.floorAssetsStatus[a.id] === 'missing').length;
  const coveragePct = totalRegistered > 0 ? Math.round((compliantCount / totalRegistered) * 100) : 0;
  const remainingCount = Math.max(0, totalRegistered - compliantCount);

  // Update current draft stats
  state.currentRoundDraft.assetStats = {
    registered: totalRegistered,
    compliant: compliantCount,
    needsMaintenance: observationCount,
    missing: missingCount,
    coverage: coveragePct
  };

  const titleText = formType === 'fex' 
    ? 'سجل ومطابقة طفايات الحريق اليدوية والمتحركة بالدور'
    : (formType === 'ext' 
        ? 'سجل ومطابقة مخارج وأبواب الطوارئ بالدور' 
        : (formType === 'fhc'
            ? 'سجل ومطابقة صناديق وخراطيم الحريق (FHC) بالدور'
            : (formType === 'fm200'
                ? 'سجل أصول ومطابقة أنظمة الإطفاء بالغاز النظيف (FM-200) بالمدينة الطبية (61 نظام معتمد)'
                : (formType === 'ind_room'
                    ? 'سجل أصول ومطابقة الغرف الصناعية ومحطات الخدمات بالمدينة الطبية (40 غرفة معتمدة)'
                    : (formType === 'elevators'
                        ? 'سجل ومطابقة مصاعد المبنى ومخارج الطوارئ بالدور'
                        : 'سجل ومطابقة أصول السلامة والوقاية بالدور (شامل)')))));

  const headerIcon = formType === 'ext' 
    ? 'sensor_door' 
    : (formType === 'fhc' 
        ? 'fire_hydrant' 
        : (formType === 'fm200' 
            ? 'air' 
            : (formType === 'ind_room'
                ? 'precision_manufacturing'
                : (formType === 'elevators' 
                    ? 'elevator' 
                    : (formType === 'fex' ? 'fire_extinguisher' : 'fact_check')))));

  // Build FM-200 Quick Building & Floor Filter Bar if formType === 'fm200'
  let fm200FilterPanelHtml = '';
  if (formType === 'fm200') {
    const allFm = getAllFm200Assets();
    const fmBuildings = [
      { key: 'all', label: 'جميع المباني', code: 'الكل', count: allFm.length },
      { key: 'المستشفى', label: 'المستشفى الغربي', code: 'A', count: allFm.filter(a => matchBuilding(a.building, 'المستشفى')).length },
      { key: 'التوسعة الشرقية', label: 'المستشفى الشرقي (بلك 35)', code: 'B', count: allFm.filter(a => matchBuilding(a.building, 'التوسعة الشرقية')).length },
      { key: 'العناية المركزة', label: 'العناية المركزة (بلك 34)', code: 'H', count: allFm.filter(a => matchBuilding(a.building, 'العناية المركزة')).length },
      { key: 'كلية الطب', label: 'كلية الطب (بلك 4، 8)', code: 'C', count: allFm.filter(a => matchBuilding(a.building, 'كلية الطب')).length },
      { key: 'المستودعات الخارجية', label: 'المولدات والمستودعات', code: 'O', count: allFm.filter(a => matchBuilding(a.building, 'المستودعات الخارجية')).length },
      { key: 'المبنى الإداري', label: 'المبنى الإداري (بلك 36)', code: 'D', count: allFm.filter(a => matchBuilding(a.building, 'المبنى الإداري')).length },
      { key: 'مبنى العيادات', label: 'العيادات الخارجية', code: 'E', count: allFm.filter(a => matchBuilding(a.building, 'مبنى العيادات')).length }
    ];

    const bldFmAssets = currentBuilding === 'all'
      ? allFm
      : allFm.filter(a => matchBuilding(a.building || a.buildingTab, currentBuilding));

    const floorOrder = ['القبو الثاني (B2)', 'القبو الأول (B1)', 'الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)'];
    const activeFloorsInBld = floorOrder
      .map(fl => ({ floor: fl, count: bldFmAssets.filter(a => matchFloor(a.floor, fl)).length }))
      .filter(item => item.count > 0);

    fm200FilterPanelHtml = `
      <div class="rounded-xl bg-primary/5 border border-primary/20 p-3 flex flex-col gap-2.5">
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
          <div class="flex items-center gap-1.5 text-xs font-extrabold text-primary">
            <span class="material-symbols-outlined text-base text-secondary">filter_alt</span>
            <span>فلترة سجل أصول أنظمة FM-200 حسب المبنى والدور:</span>
          </div>
          <div class="relative w-full sm:w-64">
            <input type="text" value="${(state.currentRoundDraft?.fm200SearchQuery || '').replace(/"/g, '&quot;')}" oninput="onFm200RoundSearch(this.value)" placeholder="بحث برقم التحكم (FA-0004)، البلوك، الغرفة..." class="w-full pl-3 pr-8 py-1.5 rounded-lg bg-white border border-outline-variant/60 text-[11px] font-bold text-primary outline-none focus:ring-2 focus:ring-primary" />
            <span class="material-symbols-outlined text-sm text-on-surface-variant absolute right-2.5 top-2">search</span>
          </div>
        </div>

        <!-- Building Filter Pills -->
        <div class="flex flex-col gap-1">
          <span class="text-[10px] font-bold text-on-surface-variant">1. اختر المبنى (${allFm.length} نظام موزع على 7 مباني):</span>
          <div class="flex items-center gap-1.5 flex-wrap">
            ${fmBuildings.map(b => {
              const isSelected = (currentBuilding === 'all' && b.key === 'all') || (b.key !== 'all' && matchBuilding(currentBuilding, b.key));
              return `
                <button type="button" onclick="onRoundBuildingChange('${b.key}')" class="px-2.5 py-1 rounded-lg text-[11px] font-bold transition-all flex items-center gap-1 ${
                  isSelected
                    ? 'bg-primary text-white shadow-xs ring-2 ring-primary/30'
                    : 'bg-white hover:bg-surface-container text-on-surface border border-outline-variant/50'
                }">
                  <span class="px-1 rounded text-[9px] font-mono ${isSelected ? 'bg-white/20 text-white' : 'bg-primary/10 text-primary'}">${b.code}</span>
                  <span>${b.label}</span>
                  <span class="px-1.5 py-0.2 rounded-full text-[10px] font-extrabold ${isSelected ? 'bg-amber-400 text-amber-950' : 'bg-surface-container text-primary'}">${b.count}</span>
                </button>
              `;
            }).join('')}
          </div>
        </div>

        <!-- Floor Filter Pills -->
        <div class="flex flex-col gap-1 pt-1 border-t border-outline-variant/30">
          <span class="text-[10px] font-bold text-on-surface-variant">2. اختر الدور في (${currentBuilding === 'all' ? 'جميع المباني' : currentBuilding}):</span>
          <div class="flex items-center gap-1.5 flex-wrap">
            <button type="button" onclick="onRoundFloorChange('all')" class="px-2.5 py-1 rounded-lg text-[11px] font-bold transition-all flex items-center gap-1 ${
              currentFloor === 'all'
                ? 'bg-secondary text-white shadow-xs'
                : 'bg-white hover:bg-surface-container text-on-surface border border-outline-variant/50'
            }">
              <span>جميع الأدوار بالمبنى</span>
              <span class="px-1.5 py-0.2 rounded-full text-[10px] font-extrabold ${currentFloor === 'all' ? 'bg-white/20 text-white' : 'bg-surface-container text-secondary'}">${bldFmAssets.length}</span>
            </button>
            ${activeFloorsInBld.map(fl => {
              const isFlSelected = currentFloor !== 'all' && matchFloor(currentFloor, fl.floor);
              return `
                <button type="button" onclick="onRoundFloorChange('${fl.floor}')" class="px-2.5 py-1 rounded-lg text-[11px] font-bold transition-all flex items-center gap-1 ${
                  isFlSelected
                    ? 'bg-emerald-700 text-white shadow-xs'
                    : 'bg-white hover:bg-emerald-50 text-emerald-900 border border-emerald-300'
                }">
                  <span>${fl.floor}</span>
                  <span class="px-1.5 py-0.2 rounded-full text-[10px] font-extrabold ${isFlSelected ? 'bg-white/20 text-white' : 'bg-emerald-100 text-emerald-800'}">${fl.count}</span>
                </button>
              `;
            }).join('')}
          </div>
        </div>
      </div>
    `;
  }

  // Build Plant Rooms Quick Building & Floor Filter Bar if formType === 'ind_room'
  let indRoomFilterPanelHtml = '';
  if (formType === 'ind_room') {
    const allInd = getAllPlantRoomAssets();
    const indBuildings = [
      { key: 'all', label: 'جميع المباني', code: 'الكل', count: allInd.length },
      { key: 'المستشفى', label: 'المستشفى الرئيسي', code: 'A', count: allInd.filter(a => matchBuilding(a.building, 'المستشفى')).length },
      { key: 'كلية الطب', label: 'كلية الطب', code: 'C', count: allInd.filter(a => matchBuilding(a.building, 'كلية الطب')).length },
      { key: 'المبنى الإداري', label: 'المبنى الإداري', code: 'D', count: allInd.filter(a => matchBuilding(a.building, 'المبنى الإداري')).length },
      { key: 'توسعة كلية الطب', label: 'توسعة الكلية', code: 'C2', count: allInd.filter(a => matchBuilding(a.building, 'توسعة كلية الطب')).length },
      { key: 'مبنى العيادات', label: 'مبنى العيادات', code: 'E', count: allInd.filter(a => matchBuilding(a.building, 'مبنى العيادات')).length },
      { key: 'العناية المركزة', label: 'العناية المركزة', code: 'H', count: allInd.filter(a => matchBuilding(a.building, 'العناية المركزة')).length }
    ];

    const bldIndAssets = currentBuilding === 'all'
      ? allInd
      : allInd.filter(a => matchBuilding(a.building || a.buildingTab, currentBuilding));

    const floorOrder = ['القبو الثاني (B2)', 'القبو الأول (B1)', 'الدور الأرضي (G)', 'الدور الثالث (3)', 'السطح (Roof)'];
    const activeFloorsInBld = floorOrder
      .map(fl => ({ floor: fl, count: bldIndAssets.filter(a => matchFloor(a.floor, fl)).length }))
      .filter(item => item.count > 0);

    indRoomFilterPanelHtml = `
      <div class="rounded-xl bg-indigo-50/40 border border-indigo-200 p-3 flex flex-col gap-2.5">
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
          <div class="flex items-center gap-1.5 text-xs font-extrabold text-indigo-900">
            <span class="material-symbols-outlined text-base text-indigo-700">precision_manufacturing</span>
            <span>فلترة أصول الغرف الصناعية (Plant Rooms) حسب المبنى والدور:</span>
          </div>
          <div class="text-[11px] font-bold text-indigo-800">
            إجمالي الغرف المسجلة: <span class="font-extrabold font-mono">${allInd.length}</span> غرفة معتمدة
          </div>
        </div>

        <!-- Building Filter Pills -->
        <div class="flex flex-col gap-1">
          <span class="text-[10px] font-bold text-on-surface-variant">1. اختر المبنى (${allInd.length} غرفة موزعة على 6 مبانٍ معتمدة):</span>
          <div class="flex items-center gap-1.5 flex-wrap">
            ${indBuildings.map(b => {
              const isSelected = (currentBuilding === 'all' && b.key === 'all') || (b.key !== 'all' && matchBuilding(currentBuilding, b.key));
              return `
                <button type="button" onclick="onRoundBuildingChange('${b.key}')" class="px-2.5 py-1 rounded-lg text-[11px] font-bold transition-all flex items-center gap-1 ${
                  isSelected
                    ? 'bg-primary text-white shadow-xs ring-2 ring-primary/30'
                    : 'bg-white hover:bg-surface-container text-on-surface border border-outline-variant/50'
                }">
                  <span class="px-1 rounded text-[9px] font-mono ${isSelected ? 'bg-white/20 text-white' : 'bg-primary/10 text-primary'}">${b.code}</span>
                  <span>${b.label}</span>
                  <span class="px-1.5 py-0.2 rounded-full text-[10px] font-extrabold ${isSelected ? 'bg-amber-400 text-amber-950' : 'bg-surface-container text-primary'}">${b.count}</span>
                </button>
              `;
            }).join('')}
          </div>
        </div>

        <!-- Floor Filter Pills -->
        <div class="flex flex-col gap-1 pt-1 border-t border-indigo-100">
          <span class="text-[10px] font-bold text-on-surface-variant">2. اختر الدور في (${currentBuilding === 'all' ? 'جميع المباني' : currentBuilding}):</span>
          <div class="flex items-center gap-1.5 flex-wrap">
            <button type="button" onclick="onRoundFloorChange('all')" class="px-2.5 py-1 rounded-lg text-[11px] font-bold transition-all flex items-center gap-1 ${
              currentFloor === 'all'
                ? 'bg-secondary text-white shadow-xs'
                : 'bg-white hover:bg-surface-container text-on-surface border border-outline-variant/50'
            }">
              <span>جميع الأدوار بالمبنى</span>
              <span class="px-1.5 py-0.2 rounded-full text-[10px] font-extrabold ${currentFloor === 'all' ? 'bg-white/20 text-white' : 'bg-surface-container text-secondary'}">${bldIndAssets.length}</span>
            </button>
            ${activeFloorsInBld.map(fl => {
              const isFlSelected = currentFloor !== 'all' && matchFloor(currentFloor, fl.floor);
              return `
                <button type="button" onclick="onRoundFloorChange('${fl.floor}')" class="px-2.5 py-1 rounded-lg text-[11px] font-bold transition-all flex items-center gap-1 ${
                  isFlSelected
                    ? 'bg-indigo-700 text-white shadow-xs'
                    : 'bg-white hover:bg-indigo-50 text-indigo-900 border border-indigo-200'
                }">
                  <span>${fl.floor}</span>
                  <span class="px-1.5 py-0.2 rounded-full text-[10px] font-extrabold ${isFlSelected ? 'bg-white/20 text-white' : 'bg-indigo-100 text-indigo-800'}">${fl.count}</span>
                </button>
              `;
            }).join('')}
          </div>
        </div>
      </div>
    `;
  }

  container.innerHTML = `
    <!-- Top Header of the Reconciliation Card (Image 2) -->
    <div class="flex flex-col md:flex-row md:items-center justify-between gap-3 pb-3 border-b border-outline-variant/30">
      <div class="flex items-start gap-2.5">
        <div class="w-10 h-10 rounded-xl bg-amber-500/15 border border-amber-500/30 flex items-center justify-center text-amber-700 shrink-0">
          <span class="material-symbols-outlined text-2xl">${headerIcon}</span>
        </div>
        <div class="flex flex-col text-right">
          <h4 class="font-bold text-sm text-amber-950">${titleText}</h4>
          <span class="text-[11px] text-on-surface-variant">مقارنة عدد الأصول المسجلة مع ما تم فحصه في الجولة الحالية</span>
        </div>
      </div>
      <div class="flex items-center gap-2 self-end md:self-auto">
        <button type="button" onclick="openNewAssetModal()" class="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-amber-800 hover:bg-amber-900 text-white text-xs font-bold shadow-sm transition-all">
          <span class="material-symbols-outlined text-sm">add_circle</span>
          <span>رصد أصل جديد</span>
        </button>
        <button type="button" onclick="openQRScannerModal()" class="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-primary hover:bg-primary-container text-white text-xs font-bold shadow-sm transition-all">
          <span class="material-symbols-outlined text-sm">qr_code_scanner</span>
          <span>مسح QR بالكاميرا</span>
        </button>
      </div>
    </div>

    ${fm200FilterPanelHtml}
    ${indRoomFilterPanelHtml}

    <!-- 5 KPI Summary Boxes (Image 2) -->
    <div class="grid grid-cols-2 sm:grid-cols-5 gap-2 text-center">
      <div class="p-2.5 rounded-xl bg-surface-container border border-outline-variant/40 flex flex-col items-center justify-center">
        <span class="text-[10px] text-on-surface-variant font-bold">${currentFloor === 'all' ? 'المسجل بالمبنى' : 'المسجل بالدور'}</span>
        <span class="text-xl font-extrabold text-primary mt-0.5">${totalRegistered}</span>
      </div>
      <div class="p-2.5 rounded-xl bg-emerald-50/60 border border-emerald-300 flex flex-col items-center justify-center">
        <span class="text-[10px] text-emerald-800 font-bold">فحص وسليم ✓</span>
        <span class="text-xl font-extrabold text-emerald-700 mt-0.5">${compliantCount}</span>
      </div>
      <div class="p-2.5 rounded-xl bg-red-50/60 border border-red-300 flex flex-col items-center justify-center">
        <span class="text-[10px] text-red-800 font-bold">يوجد ملاحظات ✗</span>
        <span class="text-xl font-extrabold text-red-700 mt-0.5">${observationCount}</span>
      </div>
      <div class="p-2.5 rounded-xl bg-amber-50/60 border border-amber-300 flex flex-col items-center justify-center">
        <span class="text-[10px] text-amber-800 font-bold">مفقودة ⚠️</span>
        <span class="text-xl font-extrabold text-amber-700 mt-0.5">${missingCount}</span>
      </div>
      <div class="col-span-2 sm:col-span-1 p-2.5 rounded-xl bg-blue-50/60 border border-blue-300 flex flex-col items-center justify-center">
        <span class="text-[10px] text-blue-800 font-bold">نسبة التغطية</span>
        <span class="text-xl font-extrabold text-blue-700 mt-0.5">${coveragePct}%</span>
      </div>
    </div>

    <!-- Progress Bar (Image 2) -->
    <div class="w-full bg-surface-container rounded-full h-2.5 overflow-hidden">
      <div class="bg-emerald-600 h-2.5 rounded-full transition-all duration-500" style="width: ${coveragePct}%"></div>
    </div>

    <!-- Bulk Verification Action Row (Image 2) -->
    <div class="flex items-center justify-between text-xs py-1 border-b border-outline-variant/30">
      <span class="font-bold text-on-surface-variant">المتبقي للفحص: <span class="text-primary font-extrabold">${remainingCount}</span> ${formType === 'fm200' ? 'نظام FM-200' : 'أصل'}</span>
      <button type="button" onclick="verifyAllFloorAssets()" class="flex items-center gap-1.5 text-secondary hover:text-primary font-extrabold hover:underline py-1 px-2 rounded-lg hover:bg-secondary/10 transition-colors">
        <span class="material-symbols-outlined text-base text-emerald-600">done_all</span>
        <span>فحص وتأكيد جاهزية جميع ${formType === 'fm200' ? 'أنظمة FM-200 المعروضة' : 'أصول الدور'} دفعة واحدة</span>
      </button>
    </div>

    <!-- Floor Assets Cards List (Image 2) -->
    <div class="flex flex-col gap-2.5">
      <h5 class="text-xs font-bold text-primary flex items-center justify-between gap-1">
        <span>قائمة ${formType === 'fm200' ? 'أنظمة الإطفاء بالغاز النظيف (FM-200)' : 'الأصول'} في (${currentBuilding === 'all' ? 'جميع المباني' : currentBuilding} — ${currentFloor === 'all' ? 'جميع الأدوار' : currentFloor}):</span>
        <span class="text-[11px] font-extrabold text-secondary">${floorAssets.length} ${formType === 'fm200' ? 'نظام' : 'أصل'}</span>
      </h5>
      <div class="flex flex-col gap-2 max-h-[380px] overflow-y-auto pr-1">
        ${floorAssets.length === 0 ? `
          <div class="p-6 rounded-xl bg-surface-container-low border border-dashed border-outline-variant text-center flex flex-col items-center gap-2">
            <span class="material-symbols-outlined text-3xl text-primary/60">inventory_2</span>
            <p class="text-xs font-bold text-primary">لا توجد أصول مسجلة لهذا النموذج في (${currentBuilding === 'all' ? 'جميع المباني' : currentBuilding} — ${currentFloor === 'all' ? 'جميع الأدوار' : currentFloor}).</p>
            <p class="text-[11px] text-on-surface-variant">النماذج المزودة بأصول مسجلة حالياً: طفايات الحريق، نظام FM-200، مخارج الطوارئ، وصناديق الحريق.</p>
          </div>
        ` : floorAssets.map((asset) => {
          const status = state.currentRoundDraft.floorAssetsStatus[asset.id] || 'pending';
          const isCompliant = status === 'compliant';
          const isObservation = status === 'observation';
          const isExitAsset = asset.category === 'مخارج الطوارئ' || (asset.id && asset.id.startsWith('EX-'));
          const isFhcAsset = (asset.category && (asset.category.includes('صناديق') || asset.category.includes('خراطيم'))) || (asset.type && (asset.type.includes('صندوق') || asset.type.includes('خرطوم'))) || (asset.id && (asset.id.startsWith('FHC-') || asset.id.startsWith('FH-') || asset.id.startsWith('PL0') || asset.id.startsWith('PL')));
          const isFm200Asset = (asset.category && (asset.category.includes('FM') || asset.category.includes('غاز'))) || (asset.id && asset.id.startsWith('FM'));
          const isIndAsset = (asset.category && asset.category.includes('الغرف الصناعية')) || (asset.id && asset.id.startsWith('IND-'));
          const isExtAsset = asset.category === 'طفايات الحريق' || (asset.id && (asset.id.startsWith('FE-') || asset.id.startsWith('EXT-')));
          const assetIconName = isExitAsset ? 'sensor_door' : (isFhcAsset ? 'fire_hydrant' : (isFm200Asset ? 'air' : (isIndAsset ? 'precision_manufacturing' : (isExtAsset ? 'fire_extinguisher' : 'inventory_2'))));
          const assetBadgeColor = isExitAsset ? 'bg-emerald-50 text-emerald-800 border-emerald-200' : (isFhcAsset ? 'bg-red-50 text-red-800 border-red-200' : (isFm200Asset ? 'bg-sky-50 text-sky-900 border-sky-200' : (isIndAsset ? 'bg-indigo-50 text-indigo-900 border-indigo-200' : 'bg-amber-50 text-amber-800 border-amber-200')));
          
          return `
            <div class="rounded-xl border ${isCompliant ? 'border-emerald-500 bg-emerald-50/20' : (isObservation ? 'border-red-400 bg-red-50/20' : 'border-outline-variant/50 bg-surface-container-lowest')} p-3 flex flex-col sm:flex-row items-center justify-between gap-2 transition-all hover:shadow-sm">
              
              <!-- Left Action Buttons -->
              <div class="flex items-center gap-1 shrink-0 self-end sm:self-center">
                <button type="button" onclick="toggleFloorAssetStatus('${asset.id}', 'help')" class="w-7 h-7 rounded-lg bg-amber-50 hover:bg-amber-100 text-amber-700 border border-amber-300 flex items-center justify-center font-bold text-xs" title="تعليمات الفحص">
                  ؟
                </button>
                <button type="button" onclick="toggleFloorAssetStatus('${asset.id}', 'observation')" class="flex items-center gap-1 px-2.5 py-1 rounded-lg ${isObservation ? 'bg-red-600 text-white' : 'bg-red-50 hover:bg-red-100 text-red-700 border border-red-300'} text-xs font-bold transition-all">
                  <span class="material-symbols-outlined text-xs">error</span>
                  <span>ملاحظة</span>
                </button>
                <button type="button" onclick="toggleFloorAssetStatus('${asset.id}', 'compliant')" class="flex items-center gap-1 px-3 py-1 rounded-lg ${isCompliant ? 'bg-emerald-600 text-white' : 'bg-emerald-50 hover:bg-emerald-100 text-emerald-700 border border-emerald-300'} text-xs font-bold transition-all">
                  <span class="material-symbols-outlined text-xs">check_circle</span>
                  <span>سليم</span>
                </button>
              </div>

              <!-- Center Asset Info -->
              <div class="flex flex-col items-center text-center flex-1">
                <div class="flex items-center gap-1.5 flex-wrap justify-center mb-0.5">
                  <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold border ${assetBadgeColor}">
                    <span class="material-symbols-outlined text-xs">${assetIconName}</span>
                    <span>${asset.category || 'أصل سلامة'}</span>
                  </span>
                  ${asset.block ? `<span class="px-2 py-0.5 rounded-full bg-blue-50 text-blue-900 border border-blue-200 text-[10px] font-bold font-mono">${asset.block}</span>` : ''}
                  ${asset.manufacturer ? `<span class="px-2 py-0.5 rounded-full bg-amber-50 text-amber-900 border border-amber-200 text-[10px] font-bold">${asset.manufacturer}${asset.model ? ' - ' + asset.model : ''}</span>` : ''}
                  ${isCompliant 
                    ? `<span class="inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800 text-[10px] font-bold"><span class="material-symbols-outlined text-xs">check</span> فحصت وسليمة</span>`
                    : (isObservation 
                        ? `<span class="inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full bg-red-100 text-red-800 text-[10px] font-bold"><span class="material-symbols-outlined text-xs">warning</span> يوجد ملاحظة</span>`
                        : `<span class="inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full bg-surface-container text-on-surface-variant text-[10px] font-bold"><span class="material-symbols-outlined text-xs">hourglass_empty</span> لم تُفحص بعد</span>`
                      )
                  }
                </div>
                <span class="font-bold text-xs text-primary leading-tight">${asset.name}</span>
                <span class="text-[11px] text-on-surface-variant flex items-center justify-center flex-wrap gap-1 mt-0.5">
                  <span class="material-symbols-outlined text-xs text-secondary">location_on</span>
                  <span>${asset.buildingTab || asset.building || ''} — ${asset.floor || ''}</span>
                  <span>|</span>
                  <span class="font-semibold text-primary">${asset.room ? `الغرفة: ${asset.room}` : asset.locationDetails}</span>
                  ${asset.locationCode ? `<span class="font-mono text-[10px] px-1.5 py-0.2 rounded bg-surface-container text-on-surface-variant">(${asset.locationCode})</span>` : ''}
                </span>
              </div>

              <!-- Right Code & QR Thumbnail (Image 2) -->
              <div class="flex items-center gap-2 shrink-0 text-left self-start sm:self-center">
                <div class="flex flex-col text-left">
                  <span class="font-mono text-xs font-extrabold text-primary">${asset.controlNo || asset.id}</span>
                  ${asset.controlNo ? `<span class="font-mono text-[9px] text-on-surface-variant">${asset.id}</span>` : ''}
                </div>
                <div class="w-9 h-9 rounded-lg border border-outline-variant/60 bg-white p-0.5 flex items-center justify-center shadow-xs">
                  <svg class="w-full h-full text-primary" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M3 3h8v8H3V3zm2 2v4h4V5H5zm8-2h8v8h-8V3zm2 2v4h4V5h-4zM3 13h8v8H3v-8zm2 2v4h4v-4H5zm13-2h3v2h-3v-2zm-5 0h3v2h-3v-2zm2 2h3v3h-3v-3zm3 3h3v3h-3v-3zm-5 0h2v3h-2v-3zm2 2h3v1h-3v-1zm3-7h3v2h-3v-2zM6 6h2v2H6V6zm10 0h2v2h-2V6zm-10 10h2v2H6v-2z"/>
                  </svg>
                </div>
              </div>

            </div>
          `;
        }).join('')}
      </div>
    </div>
  `;
}

function verifyAllFloorAssets() {
  const currentBuilding = document.getElementById('inp-round-building')?.value || state.currentRoundDraft?.building || 'المستشفى';
  const currentFloor = document.getElementById('inp-round-floor')?.value || state.currentRoundDraft?.floor || 'الدور الأرضي (G)';
  const formType = (state.currentRoundDraft && state.currentRoundDraft.formType) || document.getElementById('inp-round-form-type')?.value || 'fex';

  let floorAssets = [];
  if (formType === 'fm200') {
    floorAssets = getAllFm200Assets().filter(a =>
      matchBuilding(a.building || a.buildingTab, currentBuilding) &&
      matchFloor(a.floor, currentFloor)
    );
  } else {
    floorAssets = (state.assets || []).filter(a => matchBuilding(a.building, currentBuilding) && matchFloor(a.floor, currentFloor));
    if (formType === 'fex') floorAssets = floorAssets.filter(a => a.category === 'طفايات الحريق' || (a.id && (a.id.startsWith('FE-') || a.id.startsWith('EXT-'))));
    else if (formType === 'ext') floorAssets = floorAssets.filter(a => a.category === 'مخارج الطوارئ' || (a.id && a.id.startsWith('EX-')));
    else if (formType === 'fhc') floorAssets = floorAssets.filter(a => (a.category && (a.category.includes('صناديق') || a.category.includes('خراطيم'))) || (a.type && (a.type.includes('صندوق') || a.type.includes('خرطوم'))) || (a.id && (a.id.startsWith('FHC-') || a.id.startsWith('FH-') || a.id.startsWith('PL0') || a.id.startsWith('PL'))));
  }

  if (!state.currentRoundDraft.floorAssetsStatus) {
    state.currentRoundDraft.floorAssetsStatus = {};
  }

  floorAssets.forEach(a => {
    state.currentRoundDraft.floorAssetsStatus[a.id] = 'compliant';
  });

  renderFloorAssetsReconciliation();
  const label = formType === 'ext' ? 'مخارج طوارئ' : (formType === 'fhc' ? 'صناديق حريق' : (formType === 'fm200' ? 'أنظمة الإطفاء بغاز FM-200' : 'أصول سلامة'));
  showToast(`تم فحص وتأكيد جاهزية جميع ${label} (${floorAssets.length}) بنجاح بنسبة 100%.`, 'success');
}

function toggleFloorAssetStatus(assetId, status) {
  const formType = (state.currentRoundDraft && state.currentRoundDraft.formType) || document.getElementById('inp-round-form-type')?.value || 'fex';
  if (status === 'help') {
    if (formType === 'ext') {
      showToast('تعليمات فحص مخرج الطوارئ: التأكد من سهولة فتح الباب باتجاه مسار الهروب، عمل الإضاءة التوجيهية (EXIT)، خلو الممر تماماً من أي عوائق، وسلامة دافش الباب الذاتي (Self-closing).', 'info');
    } else if (formType === 'fhc') {
      showToast('تعليمات فحص صندوق الحريق: التأكد من سلامة الصندوق والزجاج، خلو الممر من العوائق، سلامة محبس المياه والبكرة وفوهة القذف وعدم وجود أي تسريب مياه.', 'info');
    } else if (formType === 'fm200') {
      showToast('تعليمات فحص نظام FM-200: التحقق من ضغط الأسطوانات في النطاق الأخضر، سلامة لوحة التحكم وخلوها من أعطال (Fault/Trouble)، وجود مسمار الأمان على وحدة الإطلاق اليدوي، سلامة الفوهات، وإحكام إغلاق الغرفة.', 'info');
    } else {
      showToast('تعليمات فحص الطفاية: التأكد من مؤشر الضغط في النطاق الأخضر، سريان بطاقة الفحص الشهرية، سلامة مسمار الأمان والخرطوم، وسهولة الوصول إليها.', 'info');
    }
    return;
  }
  if (!state.currentRoundDraft.floorAssetsStatus) {
    state.currentRoundDraft.floorAssetsStatus = {};
  }
  const current = state.currentRoundDraft.floorAssetsStatus[assetId];
  if (current === status) {
    state.currentRoundDraft.floorAssetsStatus[assetId] = 'pending';
  } else {
    state.currentRoundDraft.floorAssetsStatus[assetId] = status;
  }
  renderFloorAssetsReconciliation();
}

