function openNewBuildingModal() {
  state.editingBuildingId = null;
  document.getElementById('modal-building-title').textContent = 'إضافة مبنى أو مرفق طبي جديد';
  document.getElementById('inp-bld-hospital').value = 'مستشفى الملك خالد الجامعي';
  document.getElementById('inp-bld-name').value = '';
  document.getElementById('inp-bld-code').value = '';
  document.getElementById('inp-bld-floors').value = '4';
  document.getElementById('inp-bld-supervisor').value = 'أ. عبدالرحمن محمد الاحمري';
  document.getElementById('inp-bld-target').value = '98';
  document.getElementById('inp-bld-status').value = 'نشط';

  const modal = document.getElementById('modal-admin-building');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }
}

function editBuilding(id) {
  const b = state.buildings.find(item => item.id === id);
  if (!b) return;

  state.editingBuildingId = id;
  document.getElementById('modal-building-title').textContent = 'تعديل بيانات المرفق: ' + b.name;
  document.getElementById('inp-bld-hospital').value = b.hospital;
  document.getElementById('inp-bld-name').value = b.name;
  document.getElementById('inp-bld-code').value = b.code;
  document.getElementById('inp-bld-floors').value = b.floors;
  document.getElementById('inp-bld-supervisor').value = b.supervisor;
  document.getElementById('inp-bld-target').value = b.targetScore;
  document.getElementById('inp-bld-status').value = b.status;

  const modal = document.getElementById('modal-admin-building');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }
}

function closeBuildingModal() {
  const modal = document.getElementById('modal-admin-building');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
}

function saveBuilding() {
  const hospital = document.getElementById('inp-bld-hospital').value;
  const name = document.getElementById('inp-bld-name').value.trim();
  const code = document.getElementById('inp-bld-code').value.trim();
  const floors = parseInt(document.getElementById('inp-bld-floors').value) || 1;
  const supervisor = document.getElementById('inp-bld-supervisor').value;
  const targetScore = parseInt(document.getElementById('inp-bld-target').value) || 95;
  const status = document.getElementById('inp-bld-status').value;

  if (!name || !code) {
    alert('يرجى كتابة اسم المبنى وكود التنفيذ.');
    return;
  }

  if (state.editingBuildingId) {
    const idx = state.buildings.findIndex(item => item.id === state.editingBuildingId);
    if (idx !== -1) {
      state.buildings[idx] = { ...state.buildings[idx], hospital, name, code, floors, supervisor, targetScore, status };
      showToast('تم تحديث بيانات المبنى بنجاح.', 'success');
    }
  } else {
    const newBld = {
      id: 'BLD-0' + (state.buildings.length + 1),
      hospital,
      name,
      code,
      floors,
      supervisor,
      targetScore,
      status
    };
    state.buildings.push(newBld);
    showToast('تمت إضافة المبنى الجديد بنجاح.', 'success');
  }

  saveBuildings();
  closeBuildingModal();
}

function deleteBuilding(id) {
  if (confirm('هل أنت متأكد من رغبتك في حذف هذا المبنى من النظام؟')) {
    state.buildings = state.buildings.filter(b => b.id !== id);
    if (window.KSUOracleSync && typeof window.KSUOracleSync.deleteBuilding === 'function') {
      window.KSUOracleSync.deleteBuilding(id);
    }
    saveBuildings();
    showToast('تم حذف المبنى بنجاح.', 'info');
  }
}

