function editChecklistItem(id) {
  const item = state.checklistTemplate.find(i => i.id == id);
  if (!item) return;

  state.editingChecklistId = id;
  document.getElementById('modal-checklist-title').textContent = 'تعديل بند الفحص: ' + item.code;
  document.getElementById('inp-chk-code').value = item.code;
  document.getElementById('inp-chk-category').value = item.category || 'عام';
  document.getElementById('inp-chk-title').value = item.title;
  document.getElementById('inp-chk-desc').value = item.desc;
  document.getElementById('inp-chk-severity').value = item.severity || 'متوسط';
  document.getElementById('inp-chk-status').value = item.status || 'active';

  const modal = document.getElementById('modal-admin-checklist');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }
}

function closeChecklistModal() {
  const modal = document.getElementById('modal-admin-checklist');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
}

function saveChecklistItem() {
  const code = document.getElementById('inp-chk-code').value.trim();
  const category = document.getElementById('inp-chk-category').value;
  const title = document.getElementById('inp-chk-title').value.trim();
  const desc = document.getElementById('inp-chk-desc').value.trim();
  const severity = document.getElementById('inp-chk-severity').value;
  const status = document.getElementById('inp-chk-status').value;

  if (!title || !code) {
    alert('يرجى إدخال عنوان البند وكود المعيار.');
    return;
  }

  if (state.editingChecklistId) {
    const idx = state.checklistTemplate.findIndex(i => i.id == state.editingChecklistId);
    if (idx !== -1) {
      state.checklistTemplate[idx] = { ...state.checklistTemplate[idx], code, category, title, desc, severity, status };
      showToast('تم تحديث بند الفحص بنجاح.', 'success');
    }
  } else {
    const newItem = {
      id: Date.now(),
      code,
      category,
      title,
      desc,
      severity,
      status
    };
    state.checklistTemplate.push(newItem);
    showToast('تمت إضافة بند الفحص الجديد بنجاح.', 'success');
  }

  saveChecklistTemplate();
  closeChecklistModal();
}

function toggleChecklistItem(id) {
  const item = state.checklistTemplate.find(i => i.id == id);
  if (item) {
    item.status = item.status === 'active' ? 'inactive' : 'active';
    saveChecklistTemplate();
    showToast('تم تغيير حالة البند إلى: ' + (item.status === 'active' ? 'مفعل' : 'معطل'), 'info');
  }
}

function deleteChecklistItem(id) {
  if (confirm('هل أنت متأكد من حذف هذا البند من نموذج التفتيش؟')) {
    state.checklistTemplate = state.checklistTemplate.filter(i => i.id != id);
    saveChecklistTemplate();
    showToast('تم حذف بند الفحص بنجاح.', 'info');
  }
}

