// HOT WORK PERMIT MODULE (Official Document 4 Replica)
// =============================================================
function renderPermitsList() {
  const containers = [
    document.getElementById('permits-list-container'),
    document.getElementById('field-permits-list-container')
  ].filter(Boolean);
  if (containers.length === 0) return;

  // Ensure state.permits is loaded from storage if empty
  if (!state.permits || state.permits.length === 0) {
    try {
      const stored = localStorage.getItem(STORAGE_KEY_PERMITS);
      if (stored) state.permits = JSON.parse(stored);
    } catch(e) {}
  }

  const permits = (state.permits || []).slice().sort((a, b) => {
    const tA = new Date(a.createdAt || a.updatedAt || a.date || 0).getTime() || 0;
    const tB = new Date(b.createdAt || b.updatedAt || b.date || 0).getTime() || 0;
    return tB - tA;
  });

  const htmlContent = (permits.length === 0) ? `
    <div class="p-8 text-center bg-surface-container-lowest rounded-2xl border border-outline-variant/30 text-on-surface-variant">
      <span class="material-symbols-outlined text-4xl text-on-surface-variant/40 mb-2">local_fire_department</span>
      <p class="font-bold text-sm">لا توجد تصاريح عمل ساخن مسجلة حالياً</p>
    </div>
  ` : permits.map(p => `
    <div class="p-space-md rounded-2xl bg-surface-container-lowest border border-outline-variant/30 shadow-sm flex flex-col md:flex-row items-start md:items-center justify-between gap-space-md transition-all hover:border-amber-400/50">
      <div class="flex items-start gap-space-md">
        <div class="w-12 h-12 rounded-xl bg-amber-100 text-amber-800 flex items-center justify-center shrink-0 shadow-xs">
          <span class="material-symbols-outlined text-headline-sm">local_fire_department</span>
        </div>
        <div class="flex flex-col">
          <div class="flex items-center gap-space-xs flex-wrap">
            <span class="font-title-md text-primary font-bold">${p.workType || 'أعمال ساخنة'}</span>
            <span class="px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800 text-[11px] font-bold">${p.status || 'ساري ومطابق'}</span>
            <span class="px-2 py-0.5 rounded bg-surface-container text-on-surface-variant text-[11px] font-mono font-bold">${p.id}</span>
            ${p.applicantSignature ? '<span class="px-2 py-0.5 rounded-full bg-blue-100 text-blue-800 text-[10px] font-bold flex items-center gap-0.5"><span class="material-symbols-outlined text-xs">draw</span> توقيع رقمي معتمد</span>' : ''}
          </div>
          <span class="font-body-sm text-on-surface mt-1">
            <strong class="text-primary">طالب التصريح / الفني:</strong> ${p.applicant || p.contractor || 'فني صيانة معتمد'} 
            | <strong class="text-primary">المقاول/الجهة:</strong> ${p.contractor || '-'}
            | <strong class="text-primary">الموقع:</strong> ${p.location || (p.zone ? `${p.zone} - ${p.floor} - ${p.room}` : 'المبنى الرئيسي')}
          </span>
          <span class="font-label-sm text-on-surface-variant mt-1">
            مراقب الحريق: ${p.fireWatch || 'مراقب السلامة المعتمد'} 
            | مصدر التصريح: <strong class="text-emerald-800">${p.inspector || p.supervisedBy || 'مفتش السلامة المناوب'}</strong> 
            | ساري حتى: <span class="font-mono text-amber-800 font-bold">${p.validUntil || (p.date + ' ' + (p.endTime || '16:00'))}</span>
          </span>
        </div>
      </div>
      <div class="flex items-center gap-2 self-end md:self-center shrink-0">
        <button onclick="printHotWorkPermit('${p.id}')" class="flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-amber-50 hover:bg-amber-100 text-amber-900 border border-amber-200 font-bold text-xs shadow-xs transition-colors">
          <span class="material-symbols-outlined text-sm text-amber-700">print</span>
          <span>طباعة التصريح (PDF)</span>
        </button>
        <button onclick="scanQRPermit('${p.id}')" class="flex items-center gap-1 px-3 py-2 rounded-xl bg-surface-container-high hover:bg-surface-container text-primary font-bold text-xs transition-colors">
          <span class="material-symbols-outlined text-sm">qr_code_2</span>
          <span>QR</span>
        </button>
        <button onclick="deletePermit('${p.id}')" title="حذف التصريح" class="w-8 h-8 rounded-lg text-error hover:bg-error/10 flex items-center justify-center transition-colors">
          <span class="material-symbols-outlined text-base">delete</span>
        </button>
      </div>
    </div>
  `).join('');

  containers.forEach(c => { c.innerHTML = htmlContent; });

  // Update permit KPIs in ALL views and Bento cards
  const activeCount = permits.filter(p => !p.status || p.status.includes('ساري') || p.status.includes('معتمد') || p.status.includes('مطابق')).length;
  const countLabel = activeCount + ' سارية';

  const fieldKpi = document.getElementById('field-kpi-permits-count');
  if (fieldKpi) fieldKpi.textContent = countLabel;

  const repKpi = document.getElementById('rep-kpi-permits-count');
  if (repKpi) repKpi.textContent = countLabel;

  const bentoBadge = document.getElementById('bento-permits-badge');
  if (bentoBadge) bentoBadge.textContent = countLabel;
}

function selectPermitWorkType(type) {
  const btns = {
    'قص': document.getElementById('btn-hw-opt-cut'),
    'لحام': document.getElementById('btn-hw-opt-weld'),
    'قص + لحام': document.getElementById('btn-hw-opt-cutweld'),
    'غير ذلك': document.getElementById('btn-hw-opt-other')
  };

  const activeClasses = ['border-amber-600', 'bg-amber-600', 'text-white', 'font-black', 'shadow-xs', 'ring-2', 'ring-amber-200'];
  const inactiveClasses = ['border-gray-200', 'bg-white', 'hover:bg-amber-50', 'text-gray-800', 'font-bold', 'shadow-2xs'];

  Object.keys(btns).forEach(key => {
    const btn = btns[key];
    if (!btn) return;
    if (key === type) {
      btn.classList.remove(...inactiveClasses);
      btn.classList.add(...activeClasses);
    } else {
      btn.classList.remove(...activeClasses);
      btn.classList.add(...inactiveClasses);
    }
  });

  const inp = document.getElementById('inp-permit-worktype');
  const hint = document.getElementById('hw-worktype-hint');
  if (!inp) return;

  if (type === 'غير ذلك') {
    inp.value = '';
    inp.placeholder = 'يرجى كتابة نوع ووصف العمل الساخن بالتفصيل (مثل: تجليخ أسطح، تسخين حراري، عزل مضخات...)...';
    inp.focus();
    if (hint) hint.innerHTML = '<span class="text-amber-800 font-bold">يرجى كتابة نوع ووصف العمل المطلوب بدقة في الحقل أعلاه.</span>';
  } else {
    inp.value = type;
    inp.placeholder = `أعمال ${type} (يمكنك إضافة تفاصيل إضافية مثل: خط الأنابيب، التكييف...)`;
    if (hint) hint.innerHTML = `النوع المحدد: <strong class="text-amber-800">${type}</strong>. يمكنك كتابة تفاصيل إضافية في الحقل أعلاه إن رغبت.`;
  }
}
window.selectPermitWorkType = selectPermitWorkType;

function openNewPermitModal() {
  const modal = document.getElementById('newPermitModal');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    const currentUserObj = (window.KSUAuth && typeof window.KSUAuth.getUser === 'function' ? window.KSUAuth.getUser() : null) || state.currentUser;
    const currentUserName = (currentUserObj && currentUserObj.name) ? currentUserObj.name : 'مفتش السلامة المناوب';

    const supervisorInp = document.getElementById('inp-permit-supervisor');
    if (supervisorInp && (!supervisorInp.value || supervisorInp.value === 'إدارة السلامة بالمدينة الطبية')) {
      supervisorInp.value = currentUserName;
    }
    const certInp = document.getElementById('inp-permit-cert-no');
    if (certInp && !certInp.value) {
      certInp.value = 'HWP-2026-' + String((state.permits ? state.permits.length : 0) + 101);
    }
    const dateInp = document.getElementById('inp-permit-date');
    if (dateInp && !dateInp.value) {
      dateInp.value = new Date().toISOString().substring(0, 10);
    }
    const startInp = document.getElementById('inp-permit-start-time');
    if (startInp && !startInp.value) {
      const now = new Date();
      startInp.value = String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');
    }
    const endInp = document.getElementById('inp-permit-end-time');
    if (endInp && !endInp.value) {
      const later = new Date();
      later.setHours(later.getHours() + 8);
      endInp.value = String(later.getHours()).padStart(2, '0') + ':' + String(later.getMinutes()).padStart(2, '0');
    }

    // Set default Work Type
    const workTypeInp = document.getElementById('inp-permit-worktype');
    const curVal = (workTypeInp ? workTypeInp.value : '').trim();
    if (!curVal || curVal === 'قص + لحام' || curVal === 'أعمال ساخنة') {
      selectPermitWorkType('قص + لحام');
    } else if (curVal === 'قص') {
      selectPermitWorkType('قص');
    } else if (curVal === 'لحام') {
      selectPermitWorkType('لحام');
    } else {
      selectPermitWorkType('غير ذلك');
      if (workTypeInp) workTypeInp.value = curVal;
    }

    if (workTypeInp && !workTypeInp._hasInputListener) {
      workTypeInp._hasInputListener = true;
      workTypeInp.addEventListener('input', function() {
        const val = this.value.trim();
        const btns = {
          'قص': document.getElementById('btn-hw-opt-cut'),
          'لحام': document.getElementById('btn-hw-opt-weld'),
          'قص + لحام': document.getElementById('btn-hw-opt-cutweld'),
          'غير ذلك': document.getElementById('btn-hw-opt-other')
        };
        const activeClasses = ['border-amber-600', 'bg-amber-600', 'text-white', 'font-black', 'shadow-xs', 'ring-2', 'ring-amber-200'];
        const inactiveClasses = ['border-gray-200', 'bg-white', 'hover:bg-amber-50', 'text-gray-800', 'font-bold', 'shadow-2xs'];
        let matched = (val === 'قص' || val === 'لحام' || val === 'قص + لحام') ? val : 'غير ذلك';
        Object.keys(btns).forEach(key => {
          const btn = btns[key];
          if (!btn) return;
          if (key === matched) {
            btn.classList.remove(...inactiveClasses);
            btn.classList.add(...activeClasses);
          } else {
            btn.classList.remove(...activeClasses);
            btn.classList.add(...inactiveClasses);
          }
        });
      });
    }

    initModalSignaturePads(['canvas-hw-applicant', 'canvas-hw-safety']);
  }
}

function closeNewPermitModal() {
  const modal = document.getElementById('newPermitModal');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
}

function saveNewPermit() {
  const contractor = document.getElementById('inp-permit-contractor')?.value || '';
  const applicant = document.getElementById('inp-permit-applicant')?.value || document.getElementById('inp-permit-technician')?.value || '';
  const technician = document.getElementById('inp-permit-technician')?.value || applicant;
  const tel = document.getElementById('inp-permit-tel')?.value || '';
  const jobId = document.getElementById('inp-permit-job-id')?.value || '';
  const date = document.getElementById('inp-permit-date')?.value || new Date().toISOString().substring(0, 10);
  const certNo = document.getElementById('inp-permit-cert-no')?.value;
  const currentUserObj = (window.KSUAuth && typeof window.KSUAuth.getUser === 'function' ? window.KSUAuth.getUser() : null) || state.currentUser;
  const currentUserName = (currentUserObj && currentUserObj.name) ? currentUserObj.name : 'مفتش السلامة المناوب';
  const supervisor = document.getElementById('inp-permit-supervisor')?.value || currentUserName;
  const startTime = document.getElementById('inp-permit-start-time')?.value || '08:00';
  const endTime = document.getElementById('inp-permit-end-time')?.value || '16:00';
  const workType = document.getElementById('inp-permit-worktype')?.value?.trim() || 'قص + لحام';
  const zone = document.getElementById('inp-permit-zone')?.value || 'Zone A';
  const floor = document.getElementById('inp-permit-floor')?.value || 'الدور الأرضي';
  const room = document.getElementById('inp-permit-room')?.value || '';
  const location = document.getElementById('inp-permit-location')?.value || `${zone} - ${floor} ${room ? '- ' + room : ''}`;
  const fireWatch = document.getElementById('inp-permit-firewatch')?.value || 'مراقب سلامة معتمد';
  const fireEquipment = document.getElementById('inp-permit-fire-equip')?.value || '';

  const checklist = {
    chk1: document.getElementById('chk-hw-1')?.value || 'yes',
    chk2: document.getElementById('chk-hw-2')?.value || 'yes',
    chk3: document.getElementById('chk-hw-3')?.value || 'yes',
    chk4: document.getElementById('chk-hw-4')?.value || 'yes',
    chk5: document.getElementById('chk-hw-5')?.value || 'yes',
    chk6: document.getElementById('chk-hw-6')?.value || 'yes',
    chk7: document.getElementById('chk-hw-7')?.value || 'yes',
    chk8: document.getElementById('chk-hw-8')?.value || 'yes'
  };

  const applicantSignature = getSignatureData('canvas-hw-applicant');
  const safetySignature = getSignatureData('canvas-hw-safety');
  const currentShiftLabel = (currentUserObj && currentUserObj.shift) || (typeof getShiftLabel === 'function' ? getShiftLabel(getCurrentActiveShiftKey()) : 'الوردية 1 (صباحي)');

  const newPermit = {
    id: certNo || ('HWP-2026-' + String((state.permits ? state.permits.length : 0) + 100).padStart(3, '0') + '-' + Date.now().toString().slice(-3)),
    applicant: applicant || 'فني صيانة معتمد',
    technician: technician,
    contractor: contractor || 'مقاول صيانة معتمد',
    tel: tel,
    jobId: jobId,
    date: date,
    supervisedBy: supervisor,
    inspector: currentUserName,
    issuerRole: (currentUserObj && currentUserObj.role) || 'مفتش / مشرف سلامة',
    shift: currentShiftLabel,
    startTime: startTime,
    endTime: endTime,
    workType: workType,
    zone: zone,
    floor: floor,
    room: room,
    location: location,
    fireWatch: fireWatch,
    fireEquipment: fireEquipment,
    validUntil: `${date} ${endTime}`,
    checklist: checklist,
    applicantSignature: applicantSignature,
    safetySignature: safetySignature,
    status: 'ساري ومعتمد',
    qualityStatus: 'pending_quality',
    routedTo: 'Q1',
    routedToTitle: 'قسم الجودة وتقييم الأداء (Q1)',
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    updatedAtMs: Date.now(),
    qrToken: 'KSU-HWP-' + ((state.permits ? state.permits.length : 0) + 100) + '-APPROVED'
  };

  if (!state.permits) state.permits = [];
  state.permits.unshift(newPermit);
  savePermits(newPermit);
  if (window.KSUOracleSync && typeof window.KSUOracleSync.savePermit === 'function') {
    window.KSUOracleSync.savePermit(newPermit);
  }
  if (window.ksuFirebaseSync && typeof window.ksuFirebaseSync.syncPermit === 'function') {
    window.ksuFirebaseSync.syncPermit(newPermit);
  }
  closeNewPermitModal();
  renderPermitsList();
  showToast('تم إصدار تصريح العمل الساخن بنجاح ومزامنته مع النظام السحابي ✓', 'success');
}

function deletePermit(id) {
  if (!confirm('هل أنت متأكد من حذف تصريح العمل الساخن؟')) return;
  state.permits = state.permits.filter(p => p.id !== id);
  if (window.KSUOracleSync && typeof window.KSUOracleSync.deletePermit === 'function') {
    window.KSUOracleSync.deletePermit(id);
  }
  if (window.ksuFirebaseSync && window.ksuFirebaseSync.db) {
    const key = window.ksuFirebaseSync.sanitizeFirebaseKey(id);
    window.ksuFirebaseSync.db.ref('permits/' + key).remove().catch(() => {});
  }
  savePermits();
  showToast('تم حذف التصريح بنجاح.', 'info');
}

function scanQRPermit(permitId) {
  const p = state.permits.find(item => item.id === permitId);
  if (!p) return;
  alert(`[التحقق من رمز QR الذكي]\n\nرقم التصريح: ${p.id}\nطالب التصريح: ${p.applicant || p.contractor}\nنوع العمل: ${p.workType}\nالموقع: ${p.location}\nمراقب الحريق: ${p.fireWatch}\nالصلاحية: حتى ${p.validUntil}\nالحالة: ساري ومعتمد رسمياً من الإدارة العامة للسلامة.`);
}

// =============================================================
// CAPA REGISTRY MODULE (Corrective and Preventive Actions)
// =============================================================
function loadCAPA() {
  try {
    const raw = (window.KSUBridge && typeof window.KSUBridge.readList === 'function')
      ? window.KSUBridge.readList('ksumc_capa_registry')
      : JSON.parse(localStorage.getItem('ksumc_capa_registry') || '[]');
    state.capa = Array.isArray(raw) ? raw : [];
  } catch(e) {
    state.capa = [];
  }
}

function renderFieldCAPARegistry() {
  const container = document.getElementById('field-capa-list-container') || document.getElementById('capa-list-container');
  if (!container) return;

  if (!state.capa || state.capa.length === 0) {
    container.innerHTML = `
      <div class="p-8 text-center text-on-surface-variant bg-surface-container-low rounded-2xl border border-outline-variant/30">
        <span class="material-symbols-outlined text-4xl text-emerald-600 mb-2">task_alt</span>
        <p class="font-bold text-sm text-gray-800">لا توجد إجراءات تصحيحية مسجلة حالياً</p>
        <p class="text-xs text-gray-500 mt-1">كافة الملاحظات والمخالفات الميدانية تمت معالجتها أو لم تسجل بعد.</p>
      </div>
    `;
    updateFieldCAPAKPIs();
    return;
  }

  const filter = state.capaFilter || 'all';
  const q = (document.getElementById('inp-search-capa')?.value || '').trim().toLowerCase();

  let list = state.capa;
  if (filter === 'open') list = list.filter(c => c.status === 'open');
  else if (filter === 'in_progress') list = list.filter(c => c.status === 'in_progress');
  else if (filter === 'resolved') list = list.filter(c => c.status === 'resolved');
  else if (filter === 'high') list = list.filter(c => c.severity === 'high');

  if (q) {
    list = list.filter(c =>
      (c.code && c.code.toLowerCase().includes(q)) ||
      (c.title && c.title.toLowerCase().includes(q)) ||
      (c.building && c.building.toLowerCase().includes(q)) ||
      (c.floor && c.floor.toLowerCase().includes(q)) ||
      (c.description && c.description.toLowerCase().includes(q))
    );
  }

  updateFieldCAPAKPIs();

  if (list.length === 0) {
    container.innerHTML = `
      <div class="p-6 text-center text-gray-500 bg-white rounded-xl border border-gray-200">
        <p class="text-xs font-bold">لا توجد نتائج تطابق معيار التصفية المحدد.</p>
      </div>
    `;
    return;
  }

  container.innerHTML = list.map(c => {
    let statusBadge = '';
    let statusActionBtn = '';
    if (c.status === 'resolved') {
      statusBadge = '<span class="px-2.5 py-0.5 rounded-full bg-emerald-100 text-emerald-800 text-[11px] font-black border border-emerald-300">مكتمل ومغلق ✓</span>';
    } else if (c.status === 'in_progress') {
      statusBadge = '<span class="px-2.5 py-0.5 rounded-full bg-sky-100 text-sky-800 text-[11px] font-black border border-sky-300">جاري المعالجة</span>';
      statusActionBtn = `
        <button type="button" onclick="updateCAPAStatus('${c.id}', 'resolved')" class="px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs flex items-center gap-1 shadow-xs transition-colors">
          <span class="material-symbols-outlined text-xs">check_circle</span>
          <span>إغلاق الإجراء ✓</span>
        </button>
      `;
    } else {
      statusBadge = '<span class="px-2.5 py-0.5 rounded-full bg-amber-100 text-amber-800 text-[11px] font-black border border-amber-300">قيد المعالجة (مفتوح)</span>';
      statusActionBtn = `
        <button type="button" onclick="updateCAPAStatus('${c.id}', 'in_progress')" class="px-2.5 py-1.5 rounded-lg bg-sky-600 hover:bg-sky-700 text-white font-bold text-xs flex items-center gap-1 shadow-xs transition-colors">
          <span class="material-symbols-outlined text-xs">play_arrow</span>
          <span>بدء التنفيذ</span>
        </button>
        <button type="button" onclick="updateCAPAStatus('${c.id}', 'resolved')" class="px-2.5 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs flex items-center gap-1 shadow-xs transition-colors">
          <span class="material-symbols-outlined text-xs">check_circle</span>
          <span>إغلاق ✓</span>
        </button>
      `;
    }

    const sevBadge = c.severity === 'high'
      ? '<span class="px-2 py-0.5 rounded bg-red-100 text-red-800 font-bold text-[10px]">حرج (High)</span>'
      : '<span class="px-2 py-0.5 rounded bg-amber-100 text-amber-800 font-bold text-[10px]">متوسط (Medium)</span>';

    return `
      <div class="p-4 rounded-2xl bg-white border border-gray-200 shadow-xs hover:border-amber-400 transition-all flex flex-col gap-3">
        <div class="flex items-start justify-between gap-2 flex-wrap">
          <div class="flex items-center gap-2 flex-wrap">
            <span class="px-2.5 py-1 rounded-lg bg-[#004B87]/10 text-[#004B87] font-mono font-black text-xs">${c.code || c.id}</span>
            <span class="font-bold text-sm text-gray-900">${c.title || 'إجراء تصحيحي'}</span>
            ${sevBadge}
            ${statusBadge}
          </div>
          <span class="text-[11px] text-gray-500 font-mono">${(c.createdAt || '').slice(0, 10)}</span>
        </div>

        <p class="text-xs text-gray-700 bg-gray-50 p-2.5 rounded-xl border border-gray-100">${c.description || 'لا يوجد وصف إضافي'}</p>

        <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-[11px] text-gray-600 pt-1">
          <div><strong class="text-gray-900">الموقع:</strong> ${c.building} - ${c.floor}</div>
          <div><strong class="text-gray-900">المبلغ:</strong> ${c.reportedBy || 'مفتش السلامة'}</div>
          <div><strong class="text-gray-900">المسند إليه:</strong> ${c.assignedTo || 'صيانة السلامة'}</div>
          <div><strong class="text-gray-900">الموعد المستهدف:</strong> <span class="text-red-700 font-bold font-mono">${c.targetDate || 'خلال 72 ساعة'}</span></div>
        </div>

        <div class="flex items-center justify-between pt-2 border-t border-gray-100 flex-wrap gap-2">
          <span class="text-[10px] text-gray-400">المصدر: ${c.roundTitle ? `الجولة: ${c.roundTitle}` : 'رصد ميداني مباشر'}</span>
          <div class="flex items-center gap-1.5">
            ${statusActionBtn}
            <button type="button" onclick="deleteFieldCAPA('${c.id}')" class="w-8 h-8 rounded-lg text-gray-400 hover:text-red-600 hover:bg-red-50 flex items-center justify-center transition-colors" title="حذف">
              <span class="material-symbols-outlined text-sm">delete</span>
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function updateFieldCAPAKPIs() {
  const all = state.capa || [];
  const elTotal = document.getElementById('kpi-capa-total');
  const elOpen = document.getElementById('kpi-capa-open');
  const elResolved = document.getElementById('kpi-capa-resolved');
  const elHigh = document.getElementById('kpi-capa-high');
  const bentoCount = document.getElementById('bento-capa-count');

  const openCount = all.filter(c => c.status === 'open' || c.status === 'in_progress').length;
  if (elTotal) elTotal.textContent = all.length;
  if (elOpen) elOpen.textContent = openCount;
  if (elResolved) elResolved.textContent = all.filter(c => c.status === 'resolved').length;
  if (elHigh) elHigh.textContent = all.filter(c => c.severity === 'high' && c.status !== 'resolved').length;
  if (bentoCount) bentoCount.textContent = openCount;
}

function setFieldCAPAFilter(filter) {
  state.capaFilter = filter;
  document.querySelectorAll('.capa-filter-btn').forEach(b => {
    b.className = 'capa-filter-btn px-3 py-1.5 rounded-lg bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold text-xs transition-all';
  });
  const activeBtn = document.getElementById(`btn-capa-filter-${filter}`);
  if (activeBtn) {
    activeBtn.className = 'capa-filter-btn px-3 py-1.5 rounded-lg bg-[#004B87] text-white font-bold text-xs shadow-xs transition-all';
  }
  renderFieldCAPARegistry();
}

function filterFieldCAPA() {
  renderFieldCAPARegistry();
}

function updateCAPAStatus(capaId, newStatus) {
  if (!state.capa) return;
  const item = state.capa.find(c => c.id === capaId);
  if (!item) return;

  item.status = newStatus;
  item.updatedAt = new Date().toISOString();
  if (newStatus === 'resolved') {
    item.closedAt = new Date().toISOString();
  }
  saveCAPA(item);
  showToast(`تم تحديث حالة الإجراء التصحيحي إلى (${newStatus === 'resolved' ? 'مكتمل ومغلق ✓' : 'جاري المعالجة'})`, 'success');
}

function deleteFieldCAPA(capaId) {
  if (!confirm('هل أنت متأكد من حذف هذا الإجراء التصحيحي؟')) return;
  state.capa = (state.capa || []).filter(c => c.id !== capaId);
  saveCAPA();
  if (window.KSUOracleSync && typeof window.KSUOracleSync.deleteCAPA === 'function') {
    window.KSUOracleSync.deleteCAPA(capaId);
  }
  showToast('تم حذف الإجراء التصحيحي بنجاح.', 'info');
}

function convertObservationToCAPA(roundId, itemId) {
  const round = (state.rounds || []).find(r => r.id === roundId);
  if (!round) {
    showToast('لم يتم العثور على تقرير الجولة.', 'error');
    return;
  }
  const item = (round.items || []).find(i => String(i.id) === String(itemId) || String(i.code) === String(itemId));
  if (!item) {
    showToast('لم يتم العثور على البند المطلوب.', 'error');
    return;
  }

  // Check if already created
  const exists = (state.capa || []).some(c => c.roundId === roundId && (c.itemCode === item.code || c.title === item.title));
  if (exists) {
    showToast('هذه الملاحظة مسجلة مسبقاً في سجل الإجراءات التصحيحية (CAPA).', 'info');
    return;
  }

  const nowIso = new Date().toISOString();
  const capaTicket = {
    id: 'capa-' + Date.now(),
    code: 'CAPA-' + Date.now().toString().slice(-6),
    source: 'round',
    roundId: round.id,
    roundTitle: round.formTitle,
    hospital: round.hospital,
    building: round.building,
    floor: round.floor,
    category: item.category || 'سلامة عامة',
    itemCode: item.code || '',
    title: item.title || item.desc || 'ملاحظة تفتيشية مرصودة',
    description: item.note || item.desc || 'تم رصد ملاحظة أثناء الجولة التفتيشية',
    severity: item.result === 'violation' ? 'high' : 'medium',
    status: 'open',
    assignedTo: 'قسم صيانة وسائل السلامة',
    reportedBy: round.inspector,
    reportedByBadge: round.badge,
    createdAt: nowIso,
    targetDate: new Date(Date.now() + 3*24*60*60*1000).toISOString().split('T')[0],
    resolutionNotes: '',
    closedAt: null
  };

  if (!state.capa) state.capa = [];
  state.capa.unshift(capaTicket);
  saveCAPA(capaTicket);
  showToast(`تم تحويل الملاحظة (${capaTicket.code}) إلى سجل الإجراءات التصحيحية بنجاح ✓`, 'success');
}

function openNewCAPAModal() {
  const modal = document.getElementById('newCAPAModal');
  if (!modal) return;
  const currentUserObj = (window.KSUAuth && typeof window.KSUAuth.getUser === 'function' ? window.KSUAuth.getUser() : null) || state.currentUser;
  const repInp = document.getElementById('inp-capa-reported-by');
  if (repInp) repInp.value = (currentUserObj && currentUserObj.name) || 'مفتش السلامة المناوب';

  const bldSelect = document.getElementById('inp-capa-building');
  if (bldSelect && state.buildings) {
    bldSelect.innerHTML = state.buildings.map(b => `<option value="${b.name}">[${b.code}] ${b.name}</option>`).join('');
  }
  modal.classList.remove('hidden');
  modal.classList.add('flex');
}

function closeNewCAPAModal() {
  const modal = document.getElementById('newCAPAModal');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
}

function saveFieldCAPA() {
  const title = document.getElementById('inp-capa-title')?.value || '';
  const building = document.getElementById('inp-capa-building')?.value || 'المستشفى';
  const floor = document.getElementById('inp-capa-floor')?.value || 'الدور الأرضي';
  const severity = document.getElementById('inp-capa-severity')?.value || 'medium';
  const assignedTo = document.getElementById('inp-capa-assigned')?.value || 'قسم الصيانة والسلامة الميدانية';
  const desc = document.getElementById('inp-capa-desc')?.value || '';
  const currentUserObj = (window.KSUAuth && typeof window.KSUAuth.getUser === 'function' ? window.KSUAuth.getUser() : null) || state.currentUser;
  const reportedBy = document.getElementById('inp-capa-reported-by')?.value || (currentUserObj && currentUserObj.name) || 'مفتش السلامة';

  if (!title.trim()) {
    showToast('يرجى كتابة عنوان الإجراء أو الملاحظة.', 'error');
    return;
  }

  const nowIso = new Date().toISOString();
  const capaTicket = {
    id: 'capa-' + Date.now(),
    code: 'CAPA-' + Date.now().toString().slice(-6),
    source: 'manual',
    hospital: 'مستشفى الملك خالد الجامعي',
    building: building,
    floor: floor,
    category: 'إجراء تصحيحي ووقائي',
    title: title.trim(),
    description: desc.trim() || title.trim(),
    severity: severity,
    status: 'open',
    assignedTo: assignedTo,
    reportedBy: reportedBy,
    reportedByBadge: (currentUserObj && (currentUserObj.empId || currentUserObj.username)) || 'KSU-SAF',
    createdAt: nowIso,
    targetDate: new Date(Date.now() + 3*24*60*60*1000).toISOString().split('T')[0],
    resolutionNotes: '',
    closedAt: null
  };

  if (!state.capa) state.capa = [];
  state.capa.unshift(capaTicket);
  saveCAPA(capaTicket);
  closeNewCAPAModal();
  showToast(`تم فتح الإجراء التصحيحي (${capaTicket.code}) ومزامنته فورياً بنجاح ✓`, 'success');
}

// =============================================================
// DOOR OPEN REQUEST MODULE (Official Document 3 Replica)
// =============================================================
function setDoorsTimeFilter(period) {
  state.doorsTimeFilter = period;
  document.querySelectorAll('.door-time-btn').forEach(btn => {
    btn.className = 'door-time-btn px-3 py-1.5 rounded-lg bg-surface-container hover:bg-surface-container-high text-on-surface font-semibold text-xs transition-all';
  });
  const activeBtn = document.getElementById(`btn-door-filter-${period}`);
  if (activeBtn) {
    activeBtn.className = 'door-time-btn px-3 py-1.5 rounded-lg bg-teal-800 text-white font-bold text-xs shadow-xs transition-all';
  }
  filterDoorsList();
}

function renderDoorsList() {
  const allDoors = state.doors || [];
  const elTotal = document.getElementById('door-kpi-total');
  const elToday = document.getElementById('door-kpi-today');
  const elWeek = document.getElementById('door-kpi-week');
  if (elTotal) elTotal.textContent = allDoors.length;
  if (elToday) elToday.textContent = allDoors.filter(d => isDateInPeriod(d.date, 'day')).length;
  if (elWeek) elWeek.textContent = allDoors.filter(d => isDateInPeriod(d.date, 'week')).length;

  filterDoorsList();
}

function filterDoorsList() {
  const container = document.getElementById('doors-list-container');
  if (!container) return;

  const q = (document.getElementById('inp-search-doors')?.value || '').trim().toLowerCase();
  const period = state.doorsTimeFilter || 'all';

  let list = state.doors || [];

  // Filter by timeline
  list = list.filter(d => isDateInPeriod(d.date, period));

  // Filter by search text
  if (q) {
    list = list.filter(d =>
      (d.id && d.id.toLowerCase().includes(q)) ||
      (d.doorName && d.doorName.toLowerCase().includes(q)) ||
      (d.requesterName && d.requesterName.toLowerCase().includes(q)) ||
      (d.employeeId && d.employeeId.toLowerCase().includes(q)) ||
      (d.department && d.department.toLowerCase().includes(q)) ||
      (d.building && d.building.toLowerCase().includes(q)) ||
      (d.reason && d.reason.toLowerCase().includes(q))
    );
  }

  // Update badge
  const badgeEl = document.getElementById('doors-filter-count-badge');
  if (badgeEl) {
    badgeEl.textContent = `${list.length} من إجمالي ${state.doors.length} طلب`;
  }

  if (list.length === 0) {
    container.innerHTML = `
      <div class="p-8 text-center bg-surface-container-lowest rounded-2xl border border-outline-variant/30 text-on-surface-variant">
        <span class="material-symbols-outlined text-4xl text-on-surface-variant/40 mb-2">sensor_door</span>
        <p class="font-bold text-sm">لا توجد طلبات فتح أبواب مطابقة للفترة المحددة أو البحث</p>
      </div>
    `;
    return;
  }

  container.innerHTML = list.map(d => `
    <div class="p-space-md rounded-2xl bg-surface-container-lowest border border-outline-variant/30 shadow-sm flex flex-col md:flex-row items-start md:items-center justify-between gap-space-md transition-all hover:border-teal-400/50">
      <div class="flex items-start gap-space-md">
        <div class="w-12 h-12 rounded-xl bg-teal-100 text-teal-800 flex items-center justify-center shrink-0 shadow-xs">
          <span class="material-symbols-outlined text-headline-sm">sensor_door</span>
        </div>
        <div class="flex flex-col">
          <div class="flex items-center gap-space-xs flex-wrap">
            <span class="font-title-md text-primary font-bold">${d.doorName}</span>
            <span class="px-2 py-0.5 rounded-full bg-surface-container text-on-surface-variant text-[11px] font-mono font-bold">${d.id}</span>
            <span class="px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800 text-[11px] font-bold">${d.status || 'تم التنفيذ'}</span>
            ${d.date ? `<span class="px-2 py-0.5 rounded-full bg-teal-50 text-teal-900 border border-teal-200 text-[11px] font-mono font-semibold">${d.date}</span>` : ''}
            ${d.requesterSignature ? '<span class="px-2 py-0.5 rounded-full bg-teal-100 text-teal-900 text-[10px] font-bold flex items-center gap-0.5"><span class="material-symbols-outlined text-xs">draw</span> توقيع الطالب موثق</span>' : ''}
          </div>
          <span class="font-body-sm text-on-surface mt-1">
            <strong class="text-primary">مقدم الطلب:</strong> ${d.requesterName} 
            (${d.jobTitle ? d.jobTitle + ' - ' : ''}الرقم الوظيفي: ${d.employeeId}) 
            | <strong class="text-primary">القسم:</strong> ${d.department}
            ${d.ext ? `(تحويلة: ${d.ext})` : ''}
          </span>
          <span class="font-label-sm text-on-surface-variant mt-1">
            الموقع: ${d.building || ''} - ${d.floor || ''} ${d.room ? '- ' + d.room : ''} 
            | السبب: ${d.reason} 
            | المفتش: ${d.inspectorName || d.approver || 'أ. علي سليمان الصقري'} (${d.time || ''})
          </span>
        </div>
      </div>
      <div class="flex items-center gap-2 self-end md:self-center shrink-0">
        <button onclick="printDoorOpenRequest('${d.id}')" class="flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-teal-50 hover:bg-teal-100 text-teal-900 border border-teal-200 font-bold text-xs shadow-xs transition-colors">
          <span class="material-symbols-outlined text-sm text-teal-700">print</span>
          <span>طباعة الطلب (PDF)</span>
        </button>
        <button onclick="deleteDoorRequest('${d.id}')" title="حذف الطلب" class="w-8 h-8 rounded-lg text-error hover:bg-error/10 flex items-center justify-center transition-colors">
          <span class="material-symbols-outlined text-base">delete</span>
        </button>
      </div>
    </div>
  `).join('');
}

let doorIdCardPhotoCache = null;

function handleDoorIdCardPhoto(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(e) {
    const rawDataUrl = e.target.result;
    const img = new Image();
    img.onload = function() {
      const maxDim = 1200;
      let w = img.width;
      let h = img.height;
      if (w > maxDim || h > maxDim) {
        if (w > h) {
          h = Math.round((h * maxDim) / w);
          w = maxDim;
        } else {
          w = Math.round((w * maxDim) / h);
          h = maxDim;
        }
      }
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);
      doorIdCardPhotoCache = canvas.toDataURL('image/jpeg', 0.85);

      const previewBox = document.getElementById('door-id-preview-box');
      const previewImg = document.getElementById('img-door-id-preview');
      if (previewImg) previewImg.src = doorIdCardPhotoCache;
      if (previewBox) {
        previewBox.classList.remove('hidden');
        previewBox.classList.add('flex');
      }
      showToast('تم التقاط وحفظ صورة بطاقة طالب فتح الباب بنجاح ✓', 'success');
    };
    img.src = rawDataUrl;
  };
  reader.readAsDataURL(file);
}
window.handleDoorIdCardPhoto = handleDoorIdCardPhoto;

function removeDoorIdCardPhoto() {
  doorIdCardPhotoCache = null;
  const previewBox = document.getElementById('door-id-preview-box');
  const previewImg = document.getElementById('img-door-id-preview');
  const inpCam = document.getElementById('inp-door-id-camera');
  const inpGal = document.getElementById('inp-door-id-gallery');
  if (previewImg) previewImg.src = '';
  if (previewBox) {
    previewBox.classList.add('hidden');
    previewBox.classList.remove('flex');
  }
  if (inpCam) inpCam.value = '';
  if (inpGal) inpGal.value = '';
}
window.removeDoorIdCardPhoto = removeDoorIdCardPhoto;

function openNewDoorModal() {
  removeDoorIdCardPhoto();
  const modal = document.getElementById('newDoorModal');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    initModalSignaturePads(['canvas-door-requester', 'canvas-door-inspector', 'canvas-door-witness']);
  }
}

function closeNewDoorModal() {
  removeDoorIdCardPhoto();
  const modal = document.getElementById('newDoorModal');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
}

function saveNewDoorRequest() {
  const requester = document.getElementById('inp-door-requester')?.value || '';
  const empId = document.getElementById('inp-door-empid')?.value || '';
  const jobTitle = document.getElementById('inp-door-job-title')?.value || '';
  const dept = document.getElementById('inp-door-dept')?.value || '';
  const ext = document.getElementById('inp-door-ext')?.value || '';
  const door = document.getElementById('inp-door-name')?.value || '';
  const reason = document.getElementById('inp-door-reason')?.value || '';
  const building = document.getElementById('inp-door-building')?.value || 'المستشفى';
  const floor = document.getElementById('inp-door-floor')?.value || 'الدور الأرضي';
  const room = document.getElementById('inp-door-room')?.value || '';
  const inspectorName = document.getElementById('inp-door-inspector-name')?.value || state.currentUser?.name || 'أ. علي سليمان الصقري';
  const witnessName = document.getElementById('inp-door-witness-name')?.value || '';

  const requesterSignature = getSignatureData('canvas-door-requester');
  const inspectorSignature = getSignatureData('canvas-door-inspector');
  const witnessSignature = getSignatureData('canvas-door-witness');
  const currentShiftLabel = state.currentUser?.shift || (typeof getShiftLabel === 'function' ? getShiftLabel(getCurrentActiveShiftKey()) : 'الوردية 1 (صباحي)');

  const newDoor = {
    id: 'DOR-' + String(state.doors.length + 106).padStart(3, '0') + '-' + Date.now().toString().slice(-3),
    requesterName: requester || 'منسوب المدينة الطبية',
    employeeId: empId || 'KSU-MED',
    jobTitle: jobTitle || 'موظف',
    department: dept || 'الخدمات الطبية',
    ext: ext,
    doorName: door || 'مكتب / مستودع',
    reason: reason || 'مهمة عمل رسمية',
    building: building,
    floor: floor,
    room: room,
    inspectorName: inspectorName,
    shift: currentShiftLabel,
    witnessName: witnessName,
    requesterSignature: requesterSignature,
    inspectorSignature: inspectorSignature,
    witnessSignature: witnessSignature,
    idCardPhoto: doorIdCardPhotoCache || '',
    time: new Date().toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' }),
    date: new Date().toISOString().substring(0, 10),
    approver: inspectorName,
    status: 'بانتظار مراجعة الجودة (Q1)',
    qualityStatus: 'pending_quality',
    routedTo: 'Q1',
    routedToTitle: 'قسم الجودة وتقييم الأداء (Q1)',
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    updatedAtMs: Date.now()
  };

  state.doors.unshift(newDoor);
  saveDoors();
  if (window.ksuFirebaseSync && typeof window.ksuFirebaseSync.syncDoor === 'function') {
    window.ksuFirebaseSync.syncDoor(newDoor);
  }
  removeDoorIdCardPhoto();
  closeNewDoorModal();
  showToast('تم توثيق طلب فتح الباب وحفظ صورة البطاقة وإرساله لحظياً لقسم الجودة وتقييم الأداء (Q1).', 'success');
}

function deleteDoorRequest(id) {
  if (!confirm('هل أنت متأكد من حذف طلب فتح الباب؟')) return;
  state.doors = state.doors.filter(d => d.id !== id);
  if (window.KSUOracleSync && typeof window.KSUOracleSync.deleteDoor === 'function') {
    window.KSUOracleSync.deleteDoor(id);
  }
  saveDoors();
  showToast('تم حذف الطلب بنجاح.', 'info');
}

