// =============================================================
// DAILY EXECUTIVE REPORT & EMAIL DISPATCH ENGINE
// إعداد وتصدير التقرير اليومي التنفيذي وإرساله لـ aalsaqri@ksu.edu.sa
// =============================================================

function generateDailyExecutiveReportData() {
  const now = new Date();
  const arabicDays = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
  const dayName = arabicDays[now.getDay()];
  const dateStr = now.toISOString().substring(0, 10);
  const timeStr = now.toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' });

  const incidents = state.shiftIncidents || [];
  const alarms = incidents.filter(i => i.type === 'alarm_bell');
  const elevators = incidents.filter(i => i.type === 'elevator_trapped');
  const smoking = incidents.filter(i => i.type === 'smoking_viol');

  const coverage = getBuildingFloorInspectionCoverage();
  const completeFloors = coverage.filter(c => c.status === 'complete').length;
  const partialFloors = coverage.filter(c => c.status === 'partial');
  const missingFloors = coverage.filter(c => c.status === 'missing');
  const totalFloors = coverage.length;
  const coveragePct = Math.round((completeFloors / totalFloors) * 100);

  return {
    dayName,
    dateStr,
    timeStr,
    supervisor: 'أ. عبدالرحمن محمد الاحمري',
    shiftName: 'الوردية الأولى (صباحي - 07:00 ص إلى 03:00 م)',
    recipientEmail: 'aalsaqri@ksu.edu.sa',
    complianceRate: '98.4%',
    coveragePct,
    totalFloors,
    completeFloors,
    partialFloors,
    missingFloors,
    incidents,
    alarms,
    elevators,
    smoking,
    activePermitsCount: (state.permits || []).filter(p => p.status === 'ساري').length,
    activeDoorsCount: (state.doors || []).length
  };
}

function generateDailyExecutiveReportText() {
  const d = generateDailyExecutiveReportData();

  let text = `=================================================================\n`;
  text += `التقرير التنفيذي اليومي لعمليات وتفتيش السلامة والأمن\n`;
  text += `المدينة الطبية بجامعة الملك سعود (KSUMC) - مشروع RSD-ALSAQRI\n`;
  text += `=================================================================\n\n`;
  text += `المستلم: سعادة المشرف العام (aalsaqri@ksu.edu.sa)\n`;
  text += `اليوم والتاريخ: ${d.dayName} ${d.dateStr} | الوقت: ${d.timeStr}\n`;
  text += `الوردية الميدانية: ${d.shiftName}\n`;
  text += `مشرف الوردية المناوب: ${d.supervisor}\n\n`;

  text += `-----------------------------------------------------------------\n`;
  text += `١. مؤشرات التغطية الميدانية ونسبة الامتثال العام:\n`;
  text += `-----------------------------------------------------------------\n`;
  text += `- معدل الامتثال العام لمعايير السلامة: ${d.complianceRate}\n`;
  text += `- نسبة تغطية تفتيش أدوار المباني الـ 11: ${d.coveragePct}%\n`;
  text += `- إجمالي الأدوار المفحوصة والمستوفاة: ${d.completeFloors} من أصل ${d.totalFloors} دوراً\n\n`;

  text += `-----------------------------------------------------------------\n`;
  text += `٢. كشف الأدوار والمباني التي بها نقص تفتيش (للمتابعة العاجلة):\n`;
  text += `-----------------------------------------------------------------\n`;
  if (d.partialFloors.length === 0 && d.missingFloors.length === 0) {
    text += `كافة مباني وأدوار المدينة الطبية مستوفاة بالكامل بنسبة 100% دون أي نقص.\n\n`;
  } else {
    d.partialFloors.forEach(p => {
      text += `* [نقص جزئي] ${p.building} - ${p.floor}: النماذج غير المنجزة (${p.missingForms.map(f => f.name).join('، ')})\n`;
    });
    d.missingFloors.forEach(m => {
      text += `* [لم يبدأ] ${m.building} - ${m.floor}: يتطلب استكمال كافة نماذج التفتيش.\n`;
    });
    text += `\n`;
  }

  text += `-----------------------------------------------------------------\n`;
  text += `٣. البلاغات والحوادث الميدانية المسجلة خلال الوردية:\n`;
  text += `-----------------------------------------------------------------\n`;
  text += `- بلاغات أجراس الإنذار: ${d.alarms.length} بلاغات (متوسط زمن الاستجابة: 1.5 دقيقة)\n`;
  d.alarms.forEach((a, idx) => {
    text += `  ${idx + 1}. موقع الإنذار: ${a.location} | نوع الكاشف: ${a.alarmType || '-'} | الإجراء: ${a.actionTaken}\n`;
  });

  text += `- حوادث احتجاز المصاعد: ${d.elevators.length} حوادث (متوسط زمن الإخراج: 4.0 دقائق - خلو تام من الإصابات)\n`;
  d.elevators.forEach((e, idx) => {
    text += `  ${idx + 1}. موقع المصعد: ${e.location} | المحتجزين: ${e.trappedPersons || 1} أشخاص | الحالة: ${e.passengerCondition || 'سليمة'}\n`;
  });

  text += `- مخالفات التدخين: ${d.smoking.length} مخالفات موثقة بتعهدات خطية\n`;
  d.smoking.forEach((s, idx) => {
    text += `  ${idx + 1}. الموقع: ${s.location} | المخالف: ${s.violatorName || '-'} | الإجراء: ${s.actionTaken}\n`;
  });
  text += `\n`;

  text += `-----------------------------------------------------------------\n`;
  text += `٤. تصاريح العمل الساخن وتأمين الأبواب:\n`;
  text += `-----------------------------------------------------------------\n`;
  text += `- تصاريح العمل الساخن السارية ومراقبو الحريق المعتمدون: ${d.activePermitsCount} تصريح\n`;
  text += `- طلبات فتح الأبواب وغرف الخدمات المعتمدة: ${d.activeDoorsCount} طلبات\n\n`;

  text += `-----------------------------------------------------------------\n`;
  text += `٥. ملاحظات وتوجيهات تسليم الوردية:\n`;
  text += `-----------------------------------------------------------------\n`;
  text += `- تم تسليم الأجهزة اللاسلكية مشحونة (8 أجهزة) مع القناة 4 ومفاتيح الطوارئ الماستر كاملة.\n`;
  text += `- التوجيه بمتابعة موقع العمل الساخن بسطح المبنى والتأكد التام من التبريد.\n\n`;

  text += `=================================================================\n`;
  text += `صدر آلياً عبر محرك التقارير التنفيذية لمنصة RSD-ALSAQRI\n`;
  text += `الإدارة العامة للأمن والسلامة - قسم السلامة - جامعة الملك سعود\n`;

  return text;
}

function openDailyExecutiveReportModal() {
  const modal = document.getElementById('dailyExecutiveReportModal');
  if (!modal) return;

  const d = generateDailyExecutiveReportData();

  const elDate = document.getElementById('exec-rep-date-indicator');
  if (elDate) elDate.textContent = `${d.dayName} ${d.dateStr} - الوردية الأولى (صباحي)`;

  const elCoveragePct = document.getElementById('exec-rep-coverage-pct');
  if (elCoveragePct) elCoveragePct.textContent = `${d.coveragePct}%`;

  const elAlarmsCount = document.getElementById('exec-rep-alarms-count');
  if (elAlarmsCount) elAlarmsCount.textContent = d.alarms.length;

  const elElevatorsCount = document.getElementById('exec-rep-elevators-count');
  if (elElevatorsCount) elElevatorsCount.textContent = d.elevators.length;

  const elSmokingCount = document.getElementById('exec-rep-smoking-count');
  if (elSmokingCount) elSmokingCount.textContent = d.smoking.length;

  const previewEl = document.getElementById('exec-rep-text-preview');
  if (previewEl) {
    previewEl.value = generateDailyExecutiveReportText();
  }

  modal.classList.remove('hidden');
  modal.classList.add('flex');
}

function closeDailyExecutiveReportModal() {
  const modal = document.getElementById('dailyExecutiveReportModal');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
}

function sendDailyReportEmail() {
  const d = generateDailyExecutiveReportData();
  const subject = `التقرير التنفيذي لسلامة المدينة الطبية KSUMC - ${d.dateStr} - الوردية الأولى`;
  const body = generateDailyExecutiveReportText();

  // Copy to clipboard first
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(body).catch(e => console.warn(e));
  }

  // Open default mail client directed to aalsaqri@ksu.edu.sa
  const mailtoUrl = `mailto:${d.recipientEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  window.location.href = mailtoUrl;

  showToast(`تم فتح البريد المعتمد لإرسال التقرير إلى ${d.recipientEmail} ونسخ النص للحافظة بنجاح!`, 'success');
}

function copyDailyExecutiveReportText() {
  const text = generateDailyExecutiveReportText();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      showToast('تم نسخ نص التقرير التنفيذي للحافظة بنجاح (جاهز للواتساب أو الإيميل).', 'success');
    }).catch(() => {
      showToast('يرجى نسخ النص من الصندوق يدوياً.', 'info');
    });
  }
}

function printDailyExecutiveReport() {
  window.print();
}

function saveHandoverLog() {
  const user = (window.KSUAuth && typeof window.KSUAuth.getUser === 'function') ? window.KSUAuth.getUser() : (state.currentUser || null);
  const giver = document.getElementById('inp-handover-giver')?.value || (user ? `${user.name} (${user.role || 'ميداني'})` : 'المسؤول الميداني');
  const shift = document.getElementById('inp-handover-shift')?.value || (user ? user.shift : 'الوردية الحالية');
  const nextSup = document.getElementById('inp-handover-nextsup')?.value || '';
  const radios = document.getElementById('inp-handover-radios')?.value || '';
  const keys = document.getElementById('inp-handover-keys')?.value || '';
  const notes = document.getElementById('inp-handover-notes')?.value || '';

  const handoverRecord = {
    id: 'HND-' + Date.now().toString().slice(-6),
    giver,
    shift,
    receiver: nextSup,
    radios,
    keys,
    notes,
    timestamp: new Date().toISOString(),
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' })
  };

  const handovers = JSON.parse(localStorage.getItem('ksu_shift_handovers') || '[]');
  handovers.unshift(handoverRecord);
  const serialized = JSON.stringify(handovers);
  localStorage.setItem('ksu_shift_handovers', serialized);
  localStorage.setItem('ksu_handover_logs_v1', serialized);
  localStorage.setItem('ksumc_handovers', serialized);

  if (window.KSUOracleSync && typeof window.KSUOracleSync.saveHandover === 'function') {
    window.KSUOracleSync.saveHandover(handoverRecord);
  }

  const bridge = window.KSUMC_DataBridge || window.KSUDataBridge;
  if (bridge && typeof bridge.saveNotification === 'function') {
    bridge.saveNotification({
      id: 'NOTIF-HND-' + handoverRecord.id,
      title: `🔄 اعتماد تسليم الوردية الميدانية (${shift})`,
      message: `تم اعتماد وتوقيع محضر تسليم الوردية رسمياً بواسطة [${giver}] إلى [${nextSup}]. العهد: ${radios} | ${keys}.`,
      senderName: giver,
      senderRole: user ? (user.roleCategory || 'field_inspector') : 'field_inspector',
      targetShift: 'all',
      priority: 'high',
      category: 'shift_handover'
    });
  }

  showToast(`✓ تم اعتماد وتوقيع محضر تسليم الوردية بنجاح وتوثيق العهدة باسم: ${giver}`, 'success');
}
window.saveHandoverLog = saveHandoverLog;

// -------------------------------------------------------------
// SAFETY DEPARTMENT REPORT MODULE (تقرير قسم السلامة الرسمي)
// -------------------------------------------------------------
function initSafetyDeptReportForm() {
  const daySelect = document.getElementById('inp-safety-rep-day');
  const dateInput = document.getElementById('inp-safety-rep-date');
  const timeInput = document.getElementById('inp-safety-rep-time');
  const bldSelect = document.getElementById('inp-safety-rep-building');
  const inspectorInput = document.getElementById('inp-safety-rep-inspector');
  const sigInput = document.getElementById('inp-safety-rep-signature');

  const now = new Date();
  const arabicDays = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
  const currentDay = arabicDays[now.getDay()];
  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  const todayStr = `${yyyy}-${mm}-${dd}`;
  const hh = String(now.getHours()).padStart(2, '0');
  const min = String(now.getMinutes()).padStart(2, '0');
  const currentTimeStr = `${hh}:${min}`;

  const docIdEl = document.getElementById('safety-rep-doc-id');
  const isEditingExisting = docIdEl && docIdEl.textContent && docIdEl.textContent.startsWith('REP-SAF-') && !docIdEl.textContent.includes('جديد');

  // رصد اليوم والتاريخ والوقت تلقائياً بحسب وقت تسجيل التقرير (مع إمكانية تعديل الوقت)
  if (daySelect) {
    if (!isEditingExisting || !daySelect.value) daySelect.value = currentDay;
  }
  if (dateInput) {
    if (!isEditingExisting || !dateInput.value) dateInput.value = todayStr;
  }
  if (timeInput) {
    if (!isEditingExisting || !timeInput.value) timeInput.value = currentTimeStr;
  }

  // تحديث خانة التاريخ في صندوق التحكم العلوي
  const docDateEl = document.getElementById('safety-rep-doc-date');
  if (docDateEl) {
    docDateEl.textContent = (dateInput && dateInput.value) ? dateInput.value : todayStr;
  }

  // Populate building dropdown with 11 approved buildings
  if (bldSelect) {
    const currentVal = bldSelect.value;
    bldSelect.innerHTML = (state.buildings || []).map(b => `<option value="${b.name}">[${b.code}] ${b.name}</option>`).join('');
    if (currentVal && Array.from(bldSelect.options).some(o => o.value === currentVal)) {
      bldSelect.value = currentVal;
    } else if (state.buildings && state.buildings.length > 0) {
      bldSelect.value = state.buildings[0].name;
    }
  }

  // Update floor options
  const selectedBuilding = bldSelect ? bldSelect.value : (state.buildings && state.buildings.length > 0 ? state.buildings[0].name : 'المستشفى');
  onSafetyReportBuildingChange(selectedBuilding);

  // Inspector and Signature defaults: تعبئة اسم محرر التقرير تلقائياً من حساب الموظف المسجل
  const currentUser = state.currentUser || (window.KSUAuth ? window.KSUAuth.getUser() : null);
  const currentUserName = currentUser?.name || 'أ. علي سليمان الصقري';

  if (inspectorInput) {
    if (!isEditingExisting || !inspectorInput.value) {
      inspectorInput.value = currentUserName;
    }
    inspectorInput.readOnly = true;
  }
  const authorDisplay = document.getElementById('safety-rep-author-display');
  if (authorDisplay) {
    authorDisplay.textContent = (inspectorInput && inspectorInput.value) ? inspectorInput.value : currentUserName;
  }

  // التحديد الآلي لفترة الوردية الحالية حسب توقيت النظام
  const shiftSelect = document.getElementById('inp-safety-rep-shift');
  const currentHour = now.getHours();
  let autoShift = 'الاولى';
  let shiftLabel = 'الوردية الأولى (07:00 ص - 03:00 م)';
  if (currentHour >= 7 && currentHour < 15) {
    autoShift = 'الاولى';
    shiftLabel = 'الوردية الأولى (07:00 ص - 03:00 م)';
  } else if (currentHour >= 15 && currentHour < 23) {
    autoShift = 'الثانية';
    shiftLabel = 'الوردية الثانية (03:00 م - 11:00 م)';
  } else {
    autoShift = 'الثالثة';
    shiftLabel = 'الوردية الثالثة (11:00 م - 07:00 ص)';
  }

  if (shiftSelect && (!isEditingExisting || !shiftSelect.value)) {
    shiftSelect.value = autoShift;
  }
  const shiftDisplay = document.getElementById('safety-rep-shift-display');
  if (shiftDisplay) {
    const val = (shiftSelect && shiftSelect.value) ? shiftSelect.value : autoShift;
    const shiftNames = {
      'الاولى': 'الوردية الأولى (07:00 ص - 03:00 م)',
      'الثانية': 'الوردية الثانية (03:00 م - 11:00 م)',
      'الثالثة': 'الوردية الثالثة (11:00 م - 07:00 ص)'
    };
    shiftDisplay.textContent = shiftNames[val] || `الوردية ${val}`;
  }

  if (sigInput && (!isEditingExisting || !sigInput.value)) {
    sigInput.value = `معتمد إلكترونياً - ${currentUserName}`;
  }

  // تثبيت أسماء المشرف المسؤول ورئيس القسم مع القفل الإلزامي
  const supNameInput = document.getElementById('inp-safety-rep-sup-name');
  if (supNameInput) {
    supNameInput.value = 'أ. حسن إبراهيم دعاك';
    supNameInput.readOnly = true;
    supNameInput.setAttribute('readonly', 'readonly');
  }

  const headNameInput = document.getElementById('inp-safety-rep-head-name');
  if (headNameInput) {
    headNameInput.value = 'أ. مصعب عبدالله آل حماد';
    headNameInput.readOnly = true;
    headNameInput.setAttribute('readonly', 'readonly');
  }

  // التحقق الدقيق من هوية وصلاحيات المستخدم الحالي
  const normUserName = (currentUser?.name || '').replace(/[أإآ]/g, 'ا').replace(/ة/g, 'ه').toLowerCase();
  const roleCat = (currentUser?.roleCategory || currentUser?.role || '').toLowerCase();
  const wfRole = (currentUser?.workflowRole || '').toLowerCase();
  const empCode = (currentUser?.empId || currentUser?.username || '').toUpperCase();
  const isDev = roleCat.includes('developer') || currentUser?.id === 'USR-01' || currentUser?.empId === '95972';

  // 1. صلاحية توجيه المشرف العام (H1 - أ. حسن إبراهيم دعاك)
  const isHasanDaak = empCode === 'H1' || wfRole === 'h1' || currentUser?.id === 'USR-7453' || (normUserName.includes('حسن') && (normUserName.includes('دعاك') || normUserName.includes('ابراهيم')));
  const canEditSupDirective = isHasanDaak || isDev;

  // 2. صلاحية توجيه رئيس قسم السلامة (H2 - أ. مصعب عبدالله آل حماد)
  const isHeadOfDept = empCode === 'H2' || wfRole === 'dept_head' || currentUser?.id === 'USR-HEAD-02' || (normUserName.includes('مصعب') || normUserName.includes('حماد')) || isDev;

  const supControls = document.getElementById('safety-rep-sup-controls');
  const supNotesInput = document.getElementById('inp-safety-rep-sup-notes');
  const supRadios = document.querySelectorAll('input[name="safety-rep-sup-routing"]');
  const supLockBadge = document.getElementById('safety-rep-sup-lock-badge');

  const headControls = document.getElementById('safety-rep-head-controls');
  const headNotesInput = document.getElementById('inp-safety-rep-head-notes');
  const headRadios = document.querySelectorAll('input[name="safety-rep-head-routing"]');
  const headLockBadge = document.getElementById('safety-rep-head-lock-badge');

  if (!canEditSupDirective) {
    supRadios.forEach(r => { r.disabled = true; r.style.pointerEvents = 'none'; });
    if (supNotesInput) {
      supNotesInput.disabled = true;
      supNotesInput.readOnly = true;
      if (!supNotesInput.value) {
        supNotesInput.placeholder = '🔒 خاص بتوجيه المشرف المسؤول (أ. حسن إبراهيم دعاك)';
      }
      supNotesInput.classList.add('cursor-not-allowed', 'opacity-60');
    }
    if (supControls) supControls.classList.add('opacity-75');
    if (supLockBadge) supLockBadge.classList.remove('hidden');
  } else {
    supRadios.forEach(r => { r.disabled = false; r.style.pointerEvents = 'auto'; });
    if (supNotesInput) {
      supNotesInput.disabled = false;
      supNotesInput.readOnly = false;
      supNotesInput.placeholder = 'ملاحظات توجيه المشرف...';
      supNotesInput.classList.remove('cursor-not-allowed', 'opacity-60');
    }
    if (supControls) supControls.classList.remove('opacity-75');
  }

  if (!isHeadOfDept) {
    headRadios.forEach(r => { r.disabled = true; r.style.pointerEvents = 'none'; });
    if (headNotesInput) {
      headNotesInput.disabled = true;
      headNotesInput.readOnly = true;
      if (!headNotesInput.value) {
        headNotesInput.placeholder = '🔒 خاص بتوجيه سعادة رئيس قسم السلامة (أ. مصعب عبدالله آل حماد)';
      }
      headNotesInput.classList.add('cursor-not-allowed', 'opacity-60');
    }
    if (headControls) headControls.classList.add('opacity-75');
    if (headLockBadge) headLockBadge.classList.remove('hidden');
  } else {
    headRadios.forEach(r => { r.disabled = false; r.style.pointerEvents = 'auto'; });
    if (headNotesInput) {
      headNotesInput.disabled = false;
      headNotesInput.readOnly = false;
      headNotesInput.placeholder = 'ملاحظات رئيس القسم...';
      headNotesInput.classList.remove('cursor-not-allowed', 'opacity-60');
    }
    if (headControls) headControls.classList.remove('opacity-75');
  }
}

function onSafetyReportBuildingChange(buildingName) {
  const floorSelect = document.getElementById('inp-safety-rep-floor');
  if (!floorSelect) return;
  const floors = BUILDING_FLOOR_MAP[buildingName] || ['القبو (B)', 'الدور الأرضي (G)', 'الدور الأول (1)', 'الدور الثاني (2)', 'الدور الثالث (3)'];
  const currentFloor = floorSelect.value;
  floorSelect.innerHTML = floors.map(f => `<option value="${f}">${f}</option>`).join('');
  if (floors.includes(currentFloor)) {
    floorSelect.value = currentFloor;
  } else {
    floorSelect.value = floors[0];
  }
  const blockInput = document.getElementById('inp-safety-rep-block');
  if (blockInput) {
    if (resolveCanonicalBuildingCode(buildingName) === 'C2') {
      blockInput.value = 'بلك 40 (BLOCK-40)';
    } else if (blockInput.value === 'بلك 40 (BLOCK-40)') {
      blockInput.value = '';
    }
  }
}

function switchSafetyReportView(viewMode) {
  const formView = document.getElementById('safety-dept-report-form-view');
  const archiveView = document.getElementById('safety-dept-report-archive-view');
  const btnForm = document.getElementById('btn-safety-rep-view-form');
  const btnArchive = document.getElementById('btn-safety-rep-view-archive');

  if (viewMode === 'form') {
    if (formView) formView.classList.remove('hidden');
    if (archiveView) archiveView.classList.add('hidden');
    if (btnForm) {
      btnForm.className = 'px-3.5 py-2 rounded-xl bg-primary text-white font-bold text-xs shadow-xs transition-all flex items-center gap-1.5';
    }
    if (btnArchive) {
      btnArchive.className = 'px-3.5 py-2 rounded-xl bg-surface-container hover:bg-surface-container-high text-primary font-bold text-xs transition-all flex items-center gap-1.5';
    }
  } else {
    if (formView) formView.classList.add('hidden');
    if (archiveView) archiveView.classList.remove('hidden');
    if (btnArchive) {
      btnArchive.className = 'px-3.5 py-2 rounded-xl bg-primary text-white font-bold text-xs shadow-xs transition-all flex items-center gap-1.5';
    }
    if (btnForm) {
      btnForm.className = 'px-3.5 py-2 rounded-xl bg-surface-container hover:bg-surface-container-high text-primary font-bold text-xs transition-all flex items-center gap-1.5';
    }
    renderSafetyDeptReportsTable();
  }
}

