// Toast
function showToast(message, type = 'info') {
  const toast = document.createElement('div');
  let bg = 'bg-primary text-on-primary';
  let icon = 'info';
  if (type === 'success') {
    bg = 'bg-emerald-700 text-white';
    icon = 'check_circle';
  } else if (type === 'error') {
    bg = 'bg-error text-on-error';
    icon = 'warning';
  }

  toast.className = `fixed bottom-6 left-6 z-50 flex items-center gap-2 px-4 py-3 rounded-xl shadow-xl ${bg} font-body-md transition-all duration-300 transform translate-y-4 opacity-0`;
  toast.innerHTML = `
    <span class="material-symbols-outlined">${icon}</span>
    <span>${message}</span>
  `;

  document.body.appendChild(toast);
  requestAnimationFrame(() => {
    toast.classList.remove('translate-y-4', 'opacity-0');
  });

  setTimeout(() => {
    toast.classList.add('translate-y-4', 'opacity-0');
    setTimeout(() => toast.remove(), 300);
  }, 4000);
}

// Live TV
function toggleSmartOperationsTV() {
  const tv = document.getElementById('smart-tv-screen-modal');
  if (tv) {
    if (tv.classList.contains('hidden')) {
      tv.classList.remove('hidden');
      tv.classList.add('flex');
    } else {
      tv.classList.add('hidden');
      tv.classList.remove('flex');
    }
  }
}

function startLiveClocks() {
  setInterval(() => {
    const now = new Date();
    const timeStr = now.toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const dateStr = now.toLocaleDateString('ar-SA', { weekday: 'short', month: 'short', day: 'numeric' });
    
    const tvClock = document.getElementById('tv-live-clock');
    if (tvClock) tvClock.textContent = timeStr + ' | ' + dateStr;
    updateTabDashboardClock();
  }, 1000);
}


