function renderQualityDirectives() {
  const container = document.getElementById('quality-directives-feed');
  if (!container) return;

  if (state.qualityDirectives.length === 0) {
    container.innerHTML = `
      <div class="p-4 text-center text-on-surface-variant text-xs font-semibold">
        لا توجد ملاحظات أو توجيهات مسجلة من إدارة الجودة حالياً.
      </div>
    `;
    return;
  }

  container.innerHTML = state.qualityDirectives.map(d => `
    <div class="p-3 rounded-xl bg-surface-container-low border border-outline-variant/40 flex flex-col gap-1.5 shadow-sm">
      <div class="flex items-center justify-between flex-wrap gap-1">
        <span class="text-xs font-bold text-primary flex items-center gap-1">
          <span class="material-symbols-outlined text-sm text-secondary">verified_user</span>
          ${d.subject}
        </span>
        <span class="text-[10px] text-on-surface-variant font-mono">${d.date}</span>
      </div>
      <p class="text-xs text-on-surface leading-relaxed">${d.message}</p>
      <div class="flex items-center justify-between pt-1 border-t border-outline-variant/30 text-[11px]">
        <span class="text-on-surface-variant font-medium">مرسل التوجيه: <strong class="text-primary">${d.sender.split(' ')[0]} ${d.sender.split(' ')[1]} (SAQRI)</strong></span>
        ${
          d.status === 'تم الاطلاع والالتزام' ?
          `<span class="px-2 py-0.5 rounded bg-emerald-100 text-emerald-800 font-bold text-[10px]">✓ ${d.status}</span>` :
          `<button onclick="acknowledgeDirective('${d.id}')" class="px-2.5 py-1 rounded-lg bg-primary hover:bg-primary-container text-white font-bold text-[10px] transition-all">
             تأكيد الاطلاع والالتزام
           </button>`
        }
      </div>
    </div>
  `).join('');
}

function openNewDirectiveModal() {
  document.getElementById('inp-dir-subject').value = 'متابعة خطة التفتيش اليومية';
  document.getElementById('inp-dir-message').value = '';

  const modal = document.getElementById('modal-quality-directive');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }
}

function closeNewDirectiveModal() {
  const modal = document.getElementById('modal-quality-directive');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
}

function saveQualityDirective() {
  const subject = document.getElementById('inp-dir-subject').value.trim();
  const message = document.getElementById('inp-dir-message').value.trim();

  if (!subject || !message) {
    alert('يرجى تعبئة عنوان التوجيه ومحتوى الملاحظة.');
    return;
  }

  const now = new Date();
  const timeStr = now.toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' });
  const dateStr = now.toISOString().split('T')[0];

  const newDir = {
    id: 'DIR-0' + (state.qualityDirectives.length + 1),
    date: `${dateStr} ${timeStr}`,
    sender: 'أ. علي سليمان الصقري (مسؤول الجودة وتقييم الأداء SAQRI)',
    recipient: 'أ. عبدالرحمن محمد الاحمري (مشرف وردية السلامة)',
    subject,
    message,
    status: 'بانتظار تأكيد المشرف',
    acknowledgedBy: null
  };

  state.qualityDirectives.unshift(newDir);
  saveQualityDirectives();
  if (window.KSUDataBridge && typeof window.KSUDataBridge.saveNotification === 'function') {
    window.KSUDataBridge.saveNotification({
      id: newDir.id + '-' + Date.now().toString().slice(-4),
      title: `توجيه جودة وتقييم أداء: ${subject}`,
      message: message,
      sender: 'قسم الجودة وتقييم الأداء (Q1)',
      targetShift: 'all',
      priority: 'high',
      type: 'executive_directive'
    });
  }
  closeNewDirectiveModal();
  showToast('تم إرسال توجيه وملاحظة الجودة لمشرف الوردية والمفتشين بنجاح.', 'success');
}

function acknowledgeDirective(dirId) {
  const d = state.qualityDirectives.find(item => item.id === dirId);
  if (!d) return;

  d.status = 'تم الاطلاع والالتزام';
  d.acknowledgedBy = 'أ. عبدالرحمن محمد الاحمري (مشرف الوردية)';
  saveQualityDirectives();
  showToast('تم تأكيد اطلاع مشرف الوردية والالتزام بتوجيه الجودة.', 'info');
}

