function quickLoginAsUser(userId, portalKey) {
  const pool = [...(state.users || []), ...INITIAL_USERS];
  const targetUser = pool.find(u => u.id === userId);
  if (!targetUser) return;

  const chosenPortal = portalKey || state.selectedLoginPortal || detectUserPortal(targetUser);

  state.currentUser = targetUser;
  state.activePortal = chosenPortal;
  state.selectedLoginPortal = chosenPortal;
  localStorage.setItem('ksu_active_portal', chosenPortal);
  localStorage.removeItem('ksu_user_logged_out');
  document.documentElement.classList.remove('ksu-require-login');

  localStorage.setItem('ksu_active_user', JSON.stringify({
    id: targetUser.id,
    name: targetUser.name,
    username: targetUser.email,
    employeeId: targetUser.employeeId,
    role: targetUser.role,
    department: targetUser.department,
    shift: targetUser.shift,
    permissions: targetUser.permissions || {}
  }));

  if (typeof ksuSyncEngine !== 'undefined' && ksuSyncEngine) {
    ksuSyncEngine.currentUser = {
      name: targetUser.name,
      username: targetUser.email,
      tenantId: 'ksu.edu.sa'
    };
    ksuSyncEngine.updateUI();
  }

  closeLoginModal();
  updateHeaderUserProfile();
  updateActivePortalUI();

  const defaultTab = getDefaultTabForUser(targetUser, chosenPortal);
  switchTab(defaultTab);

  showToast(`تم الدخول بنجاح: مرحباً ${targetUser.name} (${targetUser.role}) ✓ - ${KSU_PORTALS[chosenPortal].name}`, 'success');
}

function testSwitchRole(presetKey) {
  let targetEmp = 'M1';
  let targetPortal = 'field';

  if (presetKey === 'inspector') {
    targetEmp = 'M1'; // مفتش الوردية (M1)
    targetPortal = 'field';
  } else if (presetKey === 'supervisor') {
    targetEmp = 'S1'; // مشرف الوردية (S1)
    targetPortal = 'field';
  } else if (presetKey === 'quality') {
    targetEmp = 'Q1'; // قسم الجودة وتقييم الأداء (Q1)
    targetPortal = 'quality';
  } else if (presetKey === 'executive') {
    targetEmp = 'H1'; // مشرف عام الملك خالد (H1)
    targetPortal = 'head';
  } else if (presetKey === 'admin') {
    targetEmp = 'alsaqri'; // مطور ومسؤول التقنية
    targetPortal = 'developer';
  }

  const pool = [...(state.users || []), ...INITIAL_USERS, ...(window.KSUAuth?.getUsers?.() || [])];
  const user = pool.find(u => u.username === targetEmp || u.empId === targetEmp || u.employeeId === targetEmp || u.id === targetEmp);
  if (!user) return;

  state.currentUser = user;
  state.activePortal = targetPortal;
  state.selectedLoginPortal = targetPortal;
  localStorage.setItem('ksu_active_portal', targetPortal);
  localStorage.removeItem('ksu_user_logged_out');
  document.documentElement.classList.remove('ksu-require-login');

  localStorage.setItem('ksu_active_user', JSON.stringify({
    id: user.id,
    name: user.name,
    username: user.email,
    employeeId: user.employeeId,
    role: user.role,
    department: user.department,
    shift: user.shift,
    permissions: user.permissions || {}
  }));

  if (typeof ksuSyncEngine !== 'undefined' && ksuSyncEngine) {
    ksuSyncEngine.currentUser = {
      name: user.name,
      username: user.email,
      tenantId: 'ksu.edu.sa'
    };
    ksuSyncEngine.updateUI();
  }

  updateHeaderUserProfile();
  updateActivePortalUI();

  const defaultTab = getDefaultTabForUser(user, targetPortal);
  switchTab(defaultTab);

  let roleDesc = '';
  if (presetKey === 'inspector') {
    roleDesc = 'وضع [مفتش سلامة ميداني]: العناصر المتاحة هي نماذج التفتيش الـ 14، مسح الأصول بالـ QR، ورصد المخالفات، وتُحجب لوحة المشرف وسجل التسليم والاعتماد.';
  } else if (presetKey === 'supervisor') {
    roleDesc = 'وضع [مشرف وردية ميداني]: تظهر لك لوحة تحكم المشرف، سجل تسليم الوردية، إسناد المهام، واعتماد التقارير والتصاريح.';
  } else if (presetKey === 'quality') {
    roleDesc = 'وضع [أخصائي جودة وسباهي]: يظهر لك جدول التفتيش الشهري 24/7، تقارير الامتثال والـ CAPA ومؤشرات الأصول.';
  } else if (presetKey === 'executive') {
    roleDesc = 'وضع [رئيس قسم السلامة / قيادة]: تظهر لك لوحة التحليلات DASH والخريطة التفاعلية والتقارير التنفيذية.';
  } else if (presetKey === 'admin') {
    roleDesc = 'وضع [مسؤول ومطور النظام]: تظهر لك كافة التبويبات بالكامل مع لوحة مسؤول النظام وإدارة الصلاحيات.';
  }

  showToast(`تم تفعيل دور: ${user.name} (${user.role}) ✓`, 'success');
  setTimeout(() => {
    showToast(roleDesc, 'info');
  }, 1200);
}

function selectPortal(portalKey) {
  const p = KSU_PORTALS[portalKey];
  if (!p) return;
  state.selectedLoginPortal = portalKey;

  const selView = document.getElementById('portal-selection-view');
  const authView = document.getElementById('portal-auth-view');
  if (selView) selView.classList.add('hidden');
  if (authView) {
    authView.classList.remove('hidden');
    authView.classList.add('flex');
  }

  // Update banner inside Auth view
  const titleEl = document.getElementById('auth-portal-title');
  const subEl = document.getElementById('auth-portal-subtitle');
  const iconEl = document.getElementById('auth-portal-icon');
  const iconContainer = document.getElementById('auth-portal-icon-container');

  if (titleEl) titleEl.textContent = p.name;
  if (subEl) subEl.textContent = p.subtitle;
  if (iconEl) iconEl.textContent = p.icon;
  if (iconContainer) {
    iconContainer.className = `w-8 h-8 rounded-lg bg-gradient-to-br ${p.gradient} text-white flex items-center justify-center shadow-xs`;
  }

  renderQuickLoginPanel(portalKey);
  switchLoginTab('sso');
  showLoginFeedback(`مرحباً بك في ${p.name}. يرجى تسجيل الدخول بحسابك الجامعي أو اختيار اسمك من الدخول السريع.`, 'info');
}

