function switchActivePortal(portalKey) {
  if (!state.currentUser) {
    if (typeof showToast === 'function') {
      showToast('يرجى تسجيل الدخول أولاً.', 'error');
    }
    return;
  }

  // البوابات الحساسة محمية لمسؤول النظام والمطور فقط
  const restrictedPortals = ['admin', 'system-admin-panel'];
  const isDev = (typeof isSystemDeveloper === 'function') ? isSystemDeveloper(state.currentUser) : (state.currentUser.role === 'admin' || state.currentUser.id === 'USR-01');
  const roleCat = (typeof getUserRoleCategory === 'function') ? getUserRoleCategory(state.currentUser) : 'field_inspector';

  if (restrictedPortals.includes(portalKey) && !isDev && roleCat !== 'shift_supervisor' && roleCat !== 'executive') {
    if (typeof showToast === 'function') {
      showToast('هذه البوابة مخصصة للإدارة فقط.', 'warning');
    }
    return;
  }

  const p = KSU_PORTALS[portalKey];
  if (!p) return;

  state.activePortal = portalKey;
  localStorage.setItem('ksu_active_portal', portalKey);
  updateActivePortalUI();
  closeSwitchPortalModal();

  const defaultTab = getDefaultTabForUser(state.currentUser, portalKey);
  switchTab(defaultTab);
  showToast(`تم الانتقال إلى: ${p.name} ✓`, 'success');
}

function updateActivePortalUI() {
  const currentKey = state.activePortal || localStorage.getItem('ksu_active_portal') || 'field';
  const p = KSU_PORTALS[currentKey] || KSU_PORTALS.field;

  const badgeEl = document.getElementById('header-active-portal-badge');
  const iconEl = document.getElementById('header-portal-icon');
  const nameEl = document.getElementById('header-portal-name');

  if (badgeEl && state.currentUser) {
    badgeEl.classList.remove('hidden');
    badgeEl.classList.add('flex');
  } else if (badgeEl) {
    badgeEl.classList.add('hidden');
    badgeEl.classList.remove('flex');
  }

  if (iconEl) iconEl.textContent = p.icon;
  if (nameEl) nameEl.textContent = p.shortName;

  // Filter Sidebar Navigation Links based on Current User & Portal
  const allowedTabs = getAllowedTabsForUser(state.currentUser, currentKey);

  document.querySelectorAll('aside nav a[data-path], .mobile-bottom-nav button[data-path]').forEach(link => {
    const path = link.getAttribute('data-path');
    if (!path) return;
    
    if (allowedTabs.includes(path)) {
      link.classList.remove('hidden');
      link.classList.add('flex');
    } else {
      link.classList.add('hidden');
      link.classList.remove('flex');
    }
  });

  // Highlight active role pill in the tester bar if present
  const roleCat = getUserRoleCategory(state.currentUser);
  const pillMapping = {
    field_inspector: 'inspector',
    shift_supervisor: 'supervisor',
    quality: 'quality',
    executive: 'executive',
    admin: 'admin'
  };
  const pillKey = pillMapping[roleCat];
  if (pillKey) {
    document.querySelectorAll('.rbac-role-pill').forEach(btn => {
      btn.classList.remove('ring-2', 'ring-amber-300', 'bg-emerald-600', 'bg-amber-600', 'bg-cyan-600', 'bg-sky-600', 'bg-purple-600');
      btn.classList.add('bg-white/10');
    });
    const activeBtn = document.getElementById(`rbac-btn-${pillKey}`);
    if (activeBtn) {
      activeBtn.classList.remove('bg-white/10');
      activeBtn.classList.add('ring-2', 'ring-amber-300', 'shadow-sm', 'text-white');
      if (pillKey === 'inspector') activeBtn.classList.add('bg-emerald-600');
      if (pillKey === 'supervisor') activeBtn.classList.add('bg-amber-600');
      if (pillKey === 'quality') activeBtn.classList.add('bg-cyan-600');
      if (pillKey === 'executive') activeBtn.classList.add('bg-sky-600');
      if (pillKey === 'admin') activeBtn.classList.add('bg-purple-600');
    }
  }

  // Update role badge inside Sidebar
  const sidebarShiftBadge = document.querySelector('aside .bg-surface-container-lowest .text-primary');
  if (state.currentUser && sidebarShiftBadge) {
    if (roleCat === 'field_inspector') {
      sidebarShiftBadge.textContent = `${state.currentUser.shift || 'الوردية الأولى'} - مفتش سلامة`;
    } else if (roleCat === 'shift_supervisor') {
      sidebarShiftBadge.textContent = `${state.currentUser.shift || 'الوردية الأولى'} - مشرف الوردية`;
    } else if (roleCat === 'quality') {
      sidebarShiftBadge.textContent = 'إدارة الجودة وتقييم الأداء';
    } else if (roleCat === 'executive') {
      sidebarShiftBadge.textContent = 'الإدارة العامة والقيادة';
    } else if (roleCat === 'admin') {
      sidebarShiftBadge.textContent = 'مسؤول ومطور النظام';
    }
  }

  // Toggle body portal scoping classes
  if (document.body) {
    document.body.classList.toggle('portal-field', currentKey === 'field');
    document.body.classList.toggle('portal-admin', currentKey === 'admin');
    document.body.classList.toggle('portal-quality', currentKey === 'quality');
    document.body.classList.toggle('portal-executive', currentKey === 'executive');
  }
}

