let nafathInterval = null;

function openLoginModal() {
  const modal = document.getElementById('ksu-login-modal');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }

  const sessionBanner = document.getElementById('ksu-login-current-session');
  const sessionName = document.getElementById('ksu-current-session-name');
  const sessionRole = document.getElementById('ksu-current-session-role');

  // Reset to portal selection view if no user active
  const isLoggedOut = localStorage.getItem('ksu_user_logged_out') === 'true';
  const savedActive = localStorage.getItem('ksu_active_user');
  let activeUser = null;
  if (savedActive && !isLoggedOut) {
    try { activeUser = JSON.parse(savedActive); } catch (e) {}
  }

  // Strict Portal Isolation: Directly lock to active portal
  const urlParams = new URLSearchParams(window.location.search);
  const qPortal = urlParams.get('portal') || state.activePortal || localStorage.getItem('ksu_active_portal') || 'field';
  state.activePortal = qPortal;
  state.selectedLoginPortal = qPortal;
  selectPortal(qPortal);

  if (activeUser && sessionBanner) {
    sessionBanner.classList.remove('hidden');
    if (sessionName) sessionName.textContent = activeUser.name || 'منسوب معتمد';
    if (sessionRole) sessionRole.textContent = activeUser.role || 'مسؤول السلامة';
  } else if (sessionBanner) {
    sessionBanner.classList.add('hidden');
  }

  const closeBtn = document.getElementById('btn-close-login-modal');
  if (closeBtn) {
    if (activeUser && !isLoggedOut) {
      closeBtn.classList.remove('hidden');
    } else {
      closeBtn.classList.add('hidden');
    }
  }

  // Pre-render quick login users
  renderQuickLoginPanel(state.selectedLoginPortal || state.activePortal || 'field');

  // Reset Nafath to step 1
  const nStep1 = document.getElementById('nafath-step-1');
  const nStep2 = document.getElementById('nafath-step-2');
  if (nStep1) nStep1.classList.remove('hidden');
  if (nStep2) nStep2.classList.add('hidden');
  if (nafathInterval) {
    clearInterval(nafathInterval);
    nafathInterval = null;
  }
}

function closeLoginModal() {
  const isLoggedOut = localStorage.getItem('ksu_user_logged_out') === 'true';
  const savedActive = localStorage.getItem('ksu_active_user');
  
  if (!savedActive || isLoggedOut || !state.currentUser) {
    showLoginFeedback('يرجى تسجيل الدخول أولاً للوصول إلى بيانات النظام.', 'warning');
    return;
  }

  document.documentElement.classList.remove('ksu-require-login');
  const modal = document.getElementById('ksu-login-modal');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
  if (nafathInterval) {
    clearInterval(nafathInterval);
    nafathInterval = null;
  }
}

function showLoginFeedback(msg, type = 'info') {
  const box = document.getElementById('ksu-login-feedback-box');
  if (!box) return;
  box.classList.remove('hidden', 'bg-emerald-50', 'text-emerald-900', 'border-emerald-300',
    'bg-rose-50', 'text-rose-900', 'border-rose-300',
    'bg-amber-50', 'text-amber-900', 'border-amber-300',
    'bg-sky-50', 'text-sky-900', 'border-sky-300');

  let icon = 'info';
  if (type === 'success') {
    box.classList.add('bg-emerald-50', 'text-emerald-900', 'border-emerald-300');
    icon = 'check_circle';
  } else if (type === 'error') {
    box.classList.add('bg-rose-50', 'text-rose-900', 'border-rose-300');
    icon = 'error';
  } else if (type === 'warning') {
    box.classList.add('bg-amber-50', 'text-amber-900', 'border-amber-300');
    icon = 'warning';
  } else {
    box.classList.add('bg-sky-50', 'text-sky-900', 'border-sky-300');
    icon = 'info';
  }

  box.innerHTML = `
    <span class="material-symbols-outlined text-lg flex-shrink-0">${icon}</span>
    <span class="flex-1 leading-snug">${msg}</span>
  `;
}

function switchLoginTab(tabKey) {
  const panels = {
    sso: document.getElementById('login-panel-sso'),
    nafath: document.getElementById('login-panel-nafath'),
    quick: document.getElementById('login-panel-quick')
  };
  const btns = {
    sso: document.getElementById('tab-btn-sso'),
    nafath: document.getElementById('tab-btn-nafath'),
    quick: document.getElementById('tab-btn-quick')
  };

  Object.keys(panels).forEach(k => {
    if (panels[k]) {
      if (k === tabKey) {
        panels[k].classList.remove('hidden');
      } else {
        panels[k].classList.add('hidden');
      }
    }
    if (btns[k]) {
      if (k === tabKey) {
        btns[k].classList.add('border-primary', 'text-primary');
        btns[k].classList.remove('border-transparent', 'text-on-surface-variant');
      } else {
        btns[k].classList.remove('border-primary', 'text-primary');
        btns[k].classList.add('border-transparent', 'text-on-surface-variant');
      }
    }
  });

  if (tabKey === 'quick') {
    renderQuickLoginPanel(state.selectedLoginPortal || state.activePortal || 'field');
  }

  const feedbackBox = document.getElementById('ksu-login-feedback-box');
  if (feedbackBox) feedbackBox.classList.add('hidden');
}

