function normalizeArabicText(text) {
  if (!text) return '';
  return text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/^(أ\.|م\.|د\.|فني\.)\s*/, '')
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/عبد\s+/g, 'عبد')
    .replace(/[\u064B-\u065F]/g, '')
    .replace(/[\s\-_]+/g, ' ');
}

function selectLoginQuickUser(userId) {
  const targetUser = (state.users && state.users.find(u => u.id === userId)) || INITIAL_USERS.find(u => u.id === userId);
  if (!targetUser) return;

  switchLoginTab('sso');
  const emailInput = document.getElementById('ksu-login-email');
  const passInput = document.getElementById('ksu-login-password');
  if (emailInput) {
    emailInput.value = targetUser.email || targetUser.employeeId;
  }
  if (passInput) {
    const defaultPass = targetUser.password || (targetUser.id === 'USR-01' ? 'admin123' : 'ksu123');
    passInput.value = defaultPass;
  }
  showLoginFeedback(`تم اختيار: ${targetUser.name} (${targetUser.role}). يمكنك النقر على "دخول النظام" للمتابعة مباشرة.`, 'success');
}

function handleKsuLoginFormSubmit(e) {
  if (e) e.preventDefault();
  const inputVal = (document.getElementById('ksu-login-email')?.value || '').trim();
  const passVal = (document.getElementById('ksu-login-password')?.value || '').trim();
  const shiftSelect = document.getElementById('ksu-login-shift-select');

  if (!inputVal) {
    showLoginFeedback('يرجى إدخال البريد الجامعي الرسمي أو اسم الموظف أو الرمز الوظيفي.', 'warning');
    document.getElementById('ksu-login-email')?.focus();
    return;
  }
  if (!passVal) {
    showLoginFeedback('يرجى إدخال كلمة المرور (الافتراضية للمفتشين: ksu123 أو الرقم الوظيفي).', 'warning');
    document.getElementById('ksu-login-password')?.focus();
    return;
  }

  const raw = inputVal.toLowerCase().trim();
  const normQuery = normalizeArabicText(raw);
  const alphanum = raw.replace(/[^a-z0-9]/g, '');
  const words = normQuery.split(' ').filter(Boolean);

  const pool = [...(state.users || []), ...INITIAL_USERS];

  // 1. Match by exact email or username portion
  let foundUser = pool.find(u => {
    const em = (u.email || '').toLowerCase().trim();
    return em === raw || em.split('@')[0] === raw;
  });

  // 2. Match by exact or partial Employee ID or User ID (e.g. KSU-SH1-201, sh1-201, 201, USR-05)
  if (!foundUser) {
    foundUser = pool.find(u => {
      const emp = (u.employeeId || '').toLowerCase().trim();
      const empAlpha = emp.replace(/[^a-z0-9]/g, '');
      const uid = (u.id || '').toLowerCase().trim();
      const uidAlpha = uid.replace(/[^a-z0-9]/g, '');
      if (emp === raw || uid === raw) return true;
      if (alphanum && (empAlpha === alphanum || uidAlpha === alphanum)) return true;
      if (alphanum && alphanum.length >= 3 && empAlpha.includes(alphanum)) return true;
      return false;
    });
  }

  // 3. Match by name (exact, normalized, or all query words present in user name)
  if (!foundUser) {
    foundUser = pool.find(u => {
      const uNorm = normalizeArabicText(u.name);
      if (uNorm === normQuery || uNorm.includes(normQuery) || normQuery.includes(uNorm)) return true;
      if (words.length > 0 && words.every(w => uNorm.includes(w))) return true;
      return false;
    });
  }

  // 4. Match by phone number
  if (!foundUser && alphanum && alphanum.length >= 4) {
    foundUser = pool.find(u => {
      const ph = (u.phone || '').replace(/[^0-9]/g, '');
      return ph.includes(alphanum);
    });
  }

  if (!foundUser) {
    showLoginFeedback('لم يتم العثور على حساب مطابق لـ "' + inputVal + '". يمكنك اختيار اسمك مباشرة من تبويب "الدخول السريع للورديات".', 'error');
    return;
  }

  // Password verification: flexible to support customized password, staff defaults, employee ID, and master key
  const enteredPass = passVal.toLowerCase().trim();
  const userPass = (foundUser.password || (foundUser.id === 'USR-01' ? 'admin123' : 'ksu123')).toLowerCase().trim();
  const empIdClean = (foundUser.employeeId || '').toLowerCase().trim();
  const empIdAlpha = empIdClean.replace(/[^a-z0-9]/g, '');

  const validPasswords = [
    userPass,
    'ksu123',
    'admin123',
    '123456',
    '1234',
    empIdClean,
    empIdAlpha,
    'ksu2026safety'
  ];
  if (foundUser.phone) {
    validPasswords.push(foundUser.phone.trim());
    validPasswords.push(foundUser.phone.slice(-4));
  }

  if (!validPasswords.includes(enteredPass)) {
    showLoginFeedback(`كلمة المرور غير صحيحة لحساب (${foundUser.name}). يرجى استخدام كلمة المرور ksu123 أو الرقم الوظيفي.`, 'error');
    const passEl = document.getElementById('ksu-login-password');
    if (passEl) {
      passEl.value = '';
      passEl.focus();
    }
    return;
  }

  // Update chosen shift if provided
  if (shiftSelect && shiftSelect.value) {
    const shiftText = shiftSelect.value;
    const shiftBadge = document.querySelector('aside .bg-surface-container-lowest .text-primary');
    if (shiftBadge) shiftBadge.textContent = shiftText;
  }

  state.currentUser = foundUser;
  document.documentElement.classList.remove('ksu-require-login');
  localStorage.removeItem('ksu_user_logged_out');
  localStorage.setItem('ksu_active_user', JSON.stringify({
    id: foundUser.id,
    name: foundUser.name,
    username: foundUser.email,
    employeeId: foundUser.employeeId,
    role: foundUser.role,
    department: foundUser.department,
    permissions: foundUser.permissions || {}
  }));

  if (typeof ksuSyncEngine !== 'undefined' && ksuSyncEngine) {
    ksuSyncEngine.currentUser = {
      name: foundUser.name,
      username: foundUser.email,
      tenantId: 'ksu.edu.sa'
    };
    ksuSyncEngine.updateUI();
  }

  // Determine active portal
  const chosenPortal = state.selectedLoginPortal || detectUserPortal(foundUser);
  state.activePortal = chosenPortal;
  localStorage.setItem('ksu_active_portal', chosenPortal);
  updateActivePortalUI();

  showLoginFeedback(`تم التحقق بنجاح: مرحباً ${foundUser.name} (${foundUser.role}) ✓ - ${KSU_PORTALS[chosenPortal].name}`, 'success');
  updateHeaderUserProfile();

  setTimeout(() => {
    closeLoginModal();
    const portalCfg = KSU_PORTALS[chosenPortal] || KSU_PORTALS.field;
    const defaultTab = getDefaultTabForUser(foundUser, chosenPortal);
    switchTab(defaultTab);
    showToast(`مرحباً بك في ${portalCfg.name}: ${foundUser.name} (${foundUser.role}) ✓`, 'success');
  }, 400);
}

function handleMicrosoftSSOLogin() {
  showLoginFeedback('جاري الاتصال بنظام مايكروسوفت 365 ومصادقة النفاذ الموحد...', 'info');

  // If sync engine has MSAL and not in file mode, attempt real SSO
  if (typeof ksuSyncEngine !== 'undefined' && ksuSyncEngine && !ksuSyncEngine.isFileMode && ksuSyncEngine.msalInstance) {
    ksuSyncEngine.login().then(() => {
      if (ksuSyncEngine.currentUser) {
        showLoginFeedback(`تم تسجيل الدخول عبر مايكروسوفت: ${ksuSyncEngine.currentUser.name} ✓`, 'success');
        localStorage.removeItem('ksu_user_logged_out');
        const chosenPortal = state.selectedLoginPortal || 'field';
        state.activePortal = chosenPortal;
        localStorage.setItem('ksu_active_portal', chosenPortal);
        updateActivePortalUI();
        updateHeaderUserProfile();
        setTimeout(() => {
          closeLoginModal();
          const defaultTab = getDefaultTabForUser(ksuSyncEngine.currentUser, chosenPortal);
          switchTab(defaultTab);
        }, 600);
      }
    }).catch(err => {
      showLoginFeedback('حدث خطأ في نافذة مايكروسوفت: ' + (err.message || err), 'warning');
    });
    return;
  }

  // Smooth fallback for offline/local environment
  setTimeout(() => {
    const targetUser = INITIAL_USERS[0]; // أ. علي سليمان الصقري
    state.currentUser = targetUser;
    document.documentElement.classList.remove('ksu-require-login');
    localStorage.removeItem('ksu_user_logged_out');
    localStorage.setItem('ksu_active_user', JSON.stringify({
      id: targetUser.id,
      name: targetUser.name,
      username: targetUser.email,
      employeeId: targetUser.employeeId,
      role: targetUser.role,
      department: targetUser.department
    }));

    if (typeof ksuSyncEngine !== 'undefined' && ksuSyncEngine) {
      ksuSyncEngine.currentUser = {
        name: targetUser.name,
        username: targetUser.email,
        tenantId: 'ksu.edu.sa'
      };
      ksuSyncEngine.updateUI();
    }

    const chosenPortal = state.selectedLoginPortal || detectUserPortal(targetUser);
    state.activePortal = chosenPortal;
    localStorage.setItem('ksu_active_portal', chosenPortal);
    updateActivePortalUI();

    showLoginFeedback(`تمت المصادقة السحابية بنجاح عبر حساب جامعة الملك سعود: ${targetUser.name} ✓`, 'success');
    updateHeaderUserProfile();

    setTimeout(() => {
      closeLoginModal();
      const defaultTab = getDefaultTabForUser(targetUser, chosenPortal);
      switchTab(defaultTab);
      showToast(`تم الدخول الموحد بنجاح: ${targetUser.name}`, 'success');
    }, 600);
  }, 600);
}

function handleNafathSubmit() {
  const nidInput = document.getElementById('nafath-national-id');
  const nid = (nidInput ? nidInput.value : '').trim();

  if (!nid || nid.length !== 10 || (!nid.startsWith('1') && !nid.startsWith('2'))) {
    showLoginFeedback('يرجى إدخال رقم هوية وطنية أو إقامة ساري المفعول (10 أرقام تبدأ بـ 1 أو 2)', 'warning');
    return;
  }

  // Generate random 2-digit challenge code
  const code = Math.floor(10 + Math.random() * 89);
  const codeEl = document.getElementById('nafath-challenge-code');
  if (codeEl) codeEl.textContent = code;

  const nStep1 = document.getElementById('nafath-step-1');
  const nStep2 = document.getElementById('nafath-step-2');
  if (nStep1) nStep1.classList.add('hidden');
  if (nStep2) nStep2.classList.remove('hidden');

  showLoginFeedback(`تم إرسال طلب المصادقة الوطنية إلى تطبيق نفاذ. يرجى اختيار الرقم (${code}) في التطبيق.`, 'info');

  // Countdown timer
  let timeLeft = 60;
  const timerEl = document.getElementById('nafath-timer');
  if (nafathInterval) clearInterval(nafathInterval);
  nafathInterval = setInterval(() => {
    timeLeft--;
    if (timerEl) timerEl.textContent = timeLeft;
    if (timeLeft <= 0) {
      clearInterval(nafathInterval);
      nafathInterval = null;
      showLoginFeedback('انتهت مهلة طلب نفاذ، يرجى إعادة المحاولة.', 'error');
      if (nStep1) nStep1.classList.remove('hidden');
      if (nStep2) nStep2.classList.add('hidden');
    }
  }, 1000);
}

function confirmNafathVerification() {
  if (nafathInterval) {
    clearInterval(nafathInterval);
    nafathInterval = null;
  }

  const linkedSelect = document.getElementById('nafath-linked-user');
  const userId = linkedSelect ? linkedSelect.value : '';
  if (!userId) {
    showLoginFeedback('يرجى اختيار الحساب الوظيفي المرتبط بك لإتمام التحقق.', 'warning');
    return;
  }
  const targetUser = (state.users && state.users.find(u => u.id === userId)) || INITIAL_USERS.find(u => u.id === userId);
  if (!targetUser) {
    showLoginFeedback('الحساب الوظيفي المحدد غير موجود في سجلات الموظفين.', 'error');
    return;
  }

  state.currentUser = targetUser;
  document.documentElement.classList.remove('ksu-require-login');
  localStorage.removeItem('ksu_user_logged_out');
  localStorage.setItem('ksu_active_user', JSON.stringify({
    id: targetUser.id,
    name: targetUser.name,
    username: targetUser.email,
    employeeId: targetUser.employeeId,
    role: targetUser.role,
    department: targetUser.department,
    permissions: targetUser.permissions || {}
  }));

  if (typeof ksuSyncEngine !== 'undefined' && ksuSyncEngine) {
    ksuSyncEngine.currentUser = {
      name: targetUser.name,
      username: targetUser.email,
      tenantId: 'ksu.edu.sa'
    };
    ksuSyncEngine.updateUI();
  }

  // Determine active portal
  const chosenPortal = state.selectedLoginPortal || detectUserPortal(targetUser);
  state.activePortal = chosenPortal;
  localStorage.setItem('ksu_active_portal', chosenPortal);
  updateActivePortalUI();

  showLoginFeedback(`تم تأكيد الهوية الوطنية عبر نفاذ بنجاح: مرحباً ${targetUser.name} ✓ - ${KSU_PORTALS[chosenPortal].name}`, 'success');
  updateHeaderUserProfile();

  setTimeout(() => {
    closeLoginModal();
    const portalCfg = KSU_PORTALS[chosenPortal] || KSU_PORTALS.field;
    const defaultTab = getDefaultTabForUser(targetUser, chosenPortal);
    switchTab(defaultTab);
    showToast(`تم الدخول الموحد بنجاح عبر نفاذ (${portalCfg.name}): ${targetUser.name}`, 'success');
  }, 600);
}

function hasPermission(permKey) {
  if (!state.currentUser) return false;
  if (!state.currentUser.permissions) return false;
  return !!state.currentUser.permissions[permKey];
}

function updateHeaderUserProfile() {
  let user = null;
  const isLoggedOut = localStorage.getItem('ksu_user_logged_out') === 'true';
  const savedActive = localStorage.getItem('ksu_active_user');

  if (savedActive && !isLoggedOut) {
    try { 
      const parsed = JSON.parse(savedActive);
      const full = (state.users && state.users.find(u => u.employeeId === parsed.employeeId || u.email === (parsed.username || parsed.email) || u.name === parsed.name)) || parsed;
      user = { ...full, ...parsed, permissions: (full && full.permissions) ? full.permissions : (parsed.permissions || {}) };
    } catch(e) {}
  }
  // When there is no saved session (such as in Incognito mode), user stays null until login
  state.currentUser = user;

  const nameEl = document.getElementById('header-user-name');
  const roleEl = document.getElementById('header-user-role');
  const avatarEl = document.getElementById('header-user-avatar');
  const dropdownNameEl = document.getElementById('dropdown-user-name');
  const dropdownRoleEl = document.getElementById('dropdown-user-role');
  const dropdownEmailEl = document.getElementById('dropdown-user-email');
  const dropdownAvatarEl = document.getElementById('dropdown-user-avatar');

  const headerAdminBtn = document.getElementById('btn-header-admin-panel');
  const sidebarAdminLink = document.getElementById('link-sidebar-admin-panel');

  if (isLoggedOut || !user) {
    if (nameEl) nameEl.textContent = 'تسجيل الدخول الموحد';
    if (roleEl) roleEl.textContent = 'انقر للدخول بالحساب الجامعي';
    if (avatarEl) avatarEl.textContent = '?';
    if (dropdownNameEl) dropdownNameEl.textContent = 'غير مسجل الدخول';
    if (dropdownRoleEl) dropdownRoleEl.textContent = 'يرجى تسجيل الدخول للنظام';
    if (dropdownEmailEl) dropdownEmailEl.textContent = 'غير متصل';
    if (dropdownAvatarEl) dropdownAvatarEl.textContent = '?';
    if (headerAdminBtn) {
      headerAdminBtn.classList.remove('flex');
      headerAdminBtn.classList.add('hidden');
    }
    if (sidebarAdminLink) {
      sidebarAdminLink.classList.remove('flex');
      sidebarAdminLink.classList.add('hidden');
    }
    return;
  }

  const isAdmin = !!(user && (user.role === 'admin' || user.id === 'USR-01' || (user.permissions && user.permissions.canManageUsers)));
  if (headerAdminBtn) {
    if (isAdmin) {
      headerAdminBtn.classList.remove('hidden');
      headerAdminBtn.classList.add('flex');
    } else {
      headerAdminBtn.classList.remove('flex');
      headerAdminBtn.classList.add('hidden');
    }
  }
  if (sidebarAdminLink) {
    if (isAdmin) {
      sidebarAdminLink.classList.remove('hidden');
      sidebarAdminLink.classList.add('flex');
    } else {
      sidebarAdminLink.classList.remove('flex');
      sidebarAdminLink.classList.add('hidden');
    }
  }

  const displayName = user.name || 'منسوب معتمد';
  const displayRole = user.role || 'قسم السلامة';
  const displayEmail = user.username || user.email || '';

  const words = displayName.replace(/^(أ\.|م\.|د\.|فني\.)\s*/, '').trim().split(' ');
  const initial = words[0] ? words[0].charAt(0) : 'م';

  if (nameEl) nameEl.textContent = displayName;
  if (roleEl) roleEl.textContent = displayRole;
  if (avatarEl) avatarEl.textContent = initial;
  if (dropdownNameEl) dropdownNameEl.textContent = displayName;
  if (dropdownRoleEl) dropdownRoleEl.textContent = displayRole;
  if (dropdownEmailEl) dropdownEmailEl.textContent = displayEmail;
  if (dropdownAvatarEl) dropdownAvatarEl.textContent = initial;

  const inspSelect = document.getElementById('inp-round-inspector');
  if (inspSelect && displayName) {
    inspSelect.value = displayName;
  }

  updateActivePortalUI();
}

function logoutCurrentUser() {
  document.documentElement.classList.add('ksu-require-login');
  localStorage.setItem('ksu_user_logged_out', 'true');
  localStorage.removeItem('ksu_active_user');
  state.currentUser = null;
  state.selectedLoginPortal = null;
  if (typeof ksuSyncEngine !== 'undefined' && ksuSyncEngine) {
    ksuSyncEngine.currentUser = null;
    ksuSyncEngine.updateUI();
  }
  const dd = document.getElementById('header-user-dropdown');
  if (dd) dd.classList.add('hidden');
  updateHeaderUserProfile();
  backToPortalSelection();
  showToast('تم تسجيل الخروج من نظام جامعة الملك سعود بنجاح.', 'info');
  openLoginModal();
}

// Close dropdown on clicking outside
document.addEventListener('click', (e) => {
  const profileBadge = document.getElementById('header-user-profile-badge');
  const dd = document.getElementById('header-user-dropdown');
  if (dd && profileBadge && !profileBadge.contains(e.target) && !dd.contains(e.target)) {
    dd.classList.add('hidden');
  }
});

