function zoomCampusMap(delta) {
  campusMapState.zoom = Math.min(campusMapState.maxZoom, Math.max(campusMapState.minZoom, campusMapState.zoom + delta));
  applyCampusMapTransform();
}

function resetCampusMapZoom() {
  campusMapState.zoom = 1.0;
  campusMapState.panX = 0;
  campusMapState.panY = 0;
  applyCampusMapTransform();
}

function applyCampusMapTransform() {
  const canvas = document.getElementById('ksumc-map-canvas');
  const label = document.getElementById('map-zoom-level-label');

  if (canvas) {
    canvas.style.transform = `translate(${campusMapState.panX}px, ${campusMapState.panY}px) scale(${campusMapState.zoom})`;
  }
  if (label) {
    label.textContent = Math.round(campusMapState.zoom * 100) + '%';
  }
}

function filterCampusMap(type, btnEl) {
  campusMapState.filter = type;

  // Update button styles
  const group = document.getElementById('campus-map-filter-group');
  if (group) {
    group.querySelectorAll('.map-filter-btn').forEach(btn => {
      btn.classList.remove('bg-primary', 'text-white', 'shadow-xs');
      btn.classList.add('bg-surface-container', 'text-on-surface-variant');
    });
  }
  if (btnEl) {
    btnEl.classList.add('bg-primary', 'text-white', 'shadow-xs');
    btnEl.classList.remove('bg-surface-container', 'text-on-surface-variant');
  }

  renderInteractiveCampusMap();
}

function toggleCampusMapFullscreen() {
  const wrapper = document.getElementById('ksumc-map-main-wrapper');
  if (!wrapper) return;

  campusMapState.isFullscreen = !campusMapState.isFullscreen;
  if (campusMapState.isFullscreen) {
    wrapper.classList.add('ksumc-map-fullscreen');
  } else {
    wrapper.classList.remove('ksumc-map-fullscreen');
  }
}

function setupCampusMapPanZoom() {
  if (campusMapState.initialized) return;
  campusMapState.initialized = true;

  const viewport = document.getElementById('ksumc-map-viewport');
  if (!viewport) return;

  // Mouse pan handlers
  viewport.addEventListener('mousedown', (e) => {
    // Ignore if clicked directly on a hotspot
    if (e.target.closest('.ksumc-building-hotspot')) return;

    campusMapState.isPanning = true;
    campusMapState.startX = e.clientX - campusMapState.panX;
    campusMapState.startY = e.clientY - campusMapState.panY;
    viewport.classList.add('is-panning');
  });

  window.addEventListener('mousemove', (e) => {
    if (!campusMapState.isPanning) return;
    campusMapState.panX = e.clientX - campusMapState.startX;
    campusMapState.panY = e.clientY - campusMapState.startY;
    applyCampusMapTransform();
  });

  window.addEventListener('mouseup', () => {
    if (campusMapState.isPanning) {
      campusMapState.isPanning = false;
      viewport.classList.remove('is-panning');
    }
  });

  // Mouse wheel zoom
  viewport.addEventListener('wheel', (e) => {
    e.preventDefault();
    const delta = e.deltaY < 0 ? 0.15 : -0.15;
    zoomCampusMap(delta);
  }, { passive: false });

  // Touch pan support for mobile/tablets
  viewport.addEventListener('touchstart', (e) => {
    if (e.touches.length === 1 && !e.target.closest('.ksumc-building-hotspot')) {
      campusMapState.isPanning = true;
      campusMapState.startX = e.touches[0].clientX - campusMapState.panX;
      campusMapState.startY = e.touches[0].clientY - campusMapState.panY;
    }
  }, { passive: true });

  viewport.addEventListener('touchmove', (e) => {
    if (campusMapState.isPanning && e.touches.length === 1) {
      campusMapState.panX = e.touches[0].clientX - campusMapState.startX;
      campusMapState.panY = e.touches[0].clientY - campusMapState.startY;
      applyCampusMapTransform();
    }
  }, { passive: true });

  viewport.addEventListener('touchend', () => {
    campusMapState.isPanning = false;
  });
}

function openNewRoundModalForBuilding(bldName) {
  openNewRoundModal('all', bldName);
}

function openAssetRegistryForBuilding(bldName) {
  switchTab('assets-qr-registry');
  const searchInput = document.getElementById('search-assets-input');
  if (searchInput) {
    searchInput.value = bldName;
    if (typeof renderAssetsList === 'function') {
      renderAssetsList();
    }
  }
  showToast(`تم فتح سجل الأصول لمبنى: ${bldName}`, 'info');
}

function openScheduleForBuilding(bldName) {
  switchTab('monthly-quality-schedule');
  showToast(`جدول أعمال التفتيش لشهر سبتمبر: ${bldName}`, 'info');
}

// ============================================================================
// OFFICIAL SEQUENTIAL WORKFLOW ENGINE (نظام سير العمل المعتمد بالتسلسل)
// المفتش ⬅️ قسم الجودة وتقييم الأداء (اعتماد في سجل سباهي / توجيه لرئيس القسم / رد للمفتش للملاحظات أو نقص أو خطأ) ⬅️ رئيس القسم (اعتماد رسمي)
// ============================================================================

const STORAGE_KEY_COMPLIANCE_REGISTRY = 'ksumc_compliance_registry';
let qualityWorkflowActiveFilter = 'all';

function getWorkflowStatusBadgeHtml(status, customLabel) {
  const st = status || 'pending_quality';
  if (st === 'returned_by_quality' || st === 'returned_by_head') {
    return `
      <span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-black bg-rose-100 text-rose-900 border border-rose-300 shadow-2xs whitespace-nowrap">
        <span class="material-symbols-outlined text-xs text-rose-700">assignment_return</span>
        <span>${customLabel || 'معاد للمفتش للملاحظات / النقص / الخطأ'}</span>
      </span>
    `;
  }
  if (st === 'approved_cbahi') {
    return `
      <span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-900 border border-emerald-300 shadow-2xs whitespace-nowrap">
        <span class="material-symbols-outlined text-xs text-emerald-700">verified</span>
        <span>${customLabel || 'معتمد ومحفوظ في سجل سباهي (CBAHI)'}</span>
      </span>
    `;
  }
  if (st === 'forwarded_to_head') {
    return `
      <span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-black bg-indigo-100 text-indigo-900 border border-indigo-300 shadow-2xs whitespace-nowrap">
        <span class="material-symbols-outlined text-xs text-indigo-700">forward_to_inbox</span>
        <span>${customLabel || 'محال لرئيس القسم للاعتماد الرسمي'}</span>
      </span>
    `;
  }
  if (st === 'approved_by_head') {
    return `
      <span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-black bg-amber-100 text-amber-950 border border-amber-400 shadow-2xs whitespace-nowrap">
        <span class="material-symbols-outlined text-xs text-amber-700">workspace_premium</span>
        <span>${customLabel || 'معتمد رسمياً من رئيس القسم وسجل سباهي'}</span>
      </span>
    `;
  }
  return `
    <span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-black bg-amber-50 text-amber-900 border border-amber-300 shadow-2xs whitespace-nowrap">
      <span class="material-symbols-outlined text-xs text-amber-600">pending_actions</span>
      <span>${customLabel || 'بانتظار اعتماد قسم الجودة وتقييم الأداء'}</span>
    </span>
  `;
}

function getComplianceRegistryRecords() {
  let stored = [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY_COMPLIANCE_REGISTRY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) stored = parsed;
    }
  } catch (e) {
    console.warn('Failed to parse compliance registry:', e);
  }

  const map = new Map();
  stored.forEach(item => {
    if (item && item.id) map.set(String(item.id), item);
  });

  // Also include any round or safety report that has been approved for CBAHI or approved by Head
  const allItems = getUnifiedWorkflowItems();
  allItems.forEach(item => {
    if (item.workflowStatus === 'approved_cbahi' || item.workflowStatus === 'approved_by_head' || item.workflowStatus === 'forwarded_to_head') {
      const compId = 'CBAHI-' + item.id;
      if (!map.has(compId)) {
        map.set(compId, {
          id: compId,
          sourceId: item.id,
          sourceType: item.sourceType,
          title: item.title,
          building: item.building,
          floor: item.floor,
          inspector: item.inspector,
          shiftName: item.shiftName,
          date: item.date,
          time: item.time,
          complianceRate: item.complianceRate,
          accreditationBodies: item.accreditationBodies || 'CBAHI FMS / NFPA 101 / الدفاع المدني',
          approvedByQuality: item.approvedByQuality || 'قسم الجودة وتقييم الأداء',
          approvedByHead: item.approvedByHead || (item.workflowStatus === 'approved_by_head' ? 'م. خالد الدوسري (رئيس القسم)' : ''),
          workflowStatus: item.workflowStatus,
          workflowStatusLabel: item.workflowStatusLabel,
          qualityNotes: item.qualityNotes || 'مستوفي لمعايير السلامة والامتثال المعتمدة',
          headNotes: item.headNotes || '',
          approvedAt: item.updatedAt || new Date().toISOString()
        });
      }
    }
  });

  return Array.from(map.values()).sort((a, b) => {
    return new Date(b.approvedAt || 0).getTime() - new Date(a.approvedAt || 0).getTime();
  });
}

function saveComplianceRegistryRecord(record) {
  let list = [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY_COMPLIANCE_REGISTRY);
    if (raw) list = JSON.parse(raw) || [];
  } catch (e) {
    list = [];
  }
  const idx = list.findIndex(r => r.id === record.id || (record.sourceId && r.sourceId === record.sourceId));
  if (idx !== -1) {
    list[idx] = Object.assign({}, list[idx], record);
  } else {
    list.unshift(record);
  }
  localStorage.setItem(STORAGE_KEY_COMPLIANCE_REGISTRY, JSON.stringify(list));
  if (window.state) window.state.complianceRegistry = list;
  if (!window._ksumcApplyingRemoteSync && window.KSUOracleSync && typeof window.KSUOracleSync.saveComplianceRecord === 'function') {
    window.KSUOracleSync.saveComplianceRecord(record);
  }
  if (window.ksuFirebaseSync && typeof window.ksuFirebaseSync.syncComplianceRecord === 'function') {
    window.ksuFirebaseSync.syncComplianceRecord(record);
  }
}

function getUnifiedWorkflowItems() {
  // Always ensure rounds & safety reports are synced with shift inspection logs
  let rounds = Array.isArray(state.rounds) ? state.rounds : [];
  if (rounds.length === 0) {
    try {
      const rRaw = localStorage.getItem(STORAGE_KEY_ROUNDS);
      if (rRaw) {
        rounds = JSON.parse(rRaw) || [];
        state.rounds = rounds;
      }
    } catch (e) {}
  }

  let deptReports = Array.isArray(state.safetyDeptReports) ? state.safetyDeptReports : [];
  if (deptReports.length === 0) {
    try {
      const dRaw = localStorage.getItem(STORAGE_KEY_SAFETY_DEPT_REPORTS);
      if (dRaw) {
        deptReports = JSON.parse(dRaw) || [];
        state.safetyDeptReports = deptReports;
      }
    } catch (e) {}
  }

  const unifiedMap = new Map();

  rounds.forEach(r => {
    if (!r || !r.id) return;
    const shiftKey = (typeof getNormalizedShiftKey === 'function')
      ? getNormalizedShiftKey(r.shift || r.shiftName)
      : ((r.shift === 'shift1' || r.shift === 'shift2' || r.shift === 'shift3') ? r.shift : getCurrentActiveShiftKey({ shift: r.shift }));
    unifiedMap.set(String(r.id), {
      id: String(r.id),
      sourceType: 'round',
      formType: r.formType || 'all',
      title: r.formTitle || 'جولة تفتيش سلامة',
      hospital: r.hospital || 'المدينة الطبية بجامعة الملك سعود',
      building: r.building || 'المستشفى',
      floor: r.floor || 'الدور الأرضي (G)',
      inspector: r.inspector || 'مفتش السلامة',
      inspectorUsername: r.inspectorUsername || '',
      badge: r.badge || 'KSU-SAF',
      shift: shiftKey,
      shiftName: r.shiftName || getShiftLabel(shiftKey),
      date: r.date || new Date().toISOString().split('T')[0],
      time: r.time || '',
      complianceRate: typeof r.score === 'number' ? r.score : 100,
      compliantCount: r.compliantCount || 0,
      observationCount: r.observationCount || 0,
      violationCount: r.violationCount || 0,
      notes: r.notes || '',
      workflowStatus: r.workflowStatus || 'pending_quality',
      workflowStatusLabel: r.workflowStatusLabel || 'بانتظار اعتماد قسم الجودة وتقييم الأداء',
      qualityReturnReason: r.qualityReturnReason || '',
      qualityReturnNotes: r.qualityReturnNotes || '',
      qualityNotes: r.qualityNotes || '',
      headNotes: r.headNotes || '',
      accreditationBodies: r.accreditationBodies || 'CBAHI FMS / NFPA 101',
      approvedByQuality: r.approvedByQuality || '',
      approvedByHead: r.approvedByHead || '',
      workflowHistory: r.workflowHistory || [],
      updatedAt: r.updatedAt || r.submittedAt || r.date || new Date().toISOString(),
      updatedAtMs: r.updatedAtMs || Date.now(),
      rawRef: r
    });
  });

  deptReports.forEach(rep => {
    if (!rep || !rep.id) return;
    const shiftKey = rep.shiftKey || getCurrentActiveShiftKey({ shift: rep.shift });
    unifiedMap.set(String(rep.id), {
      id: String(rep.id),
      sourceType: 'safety_report',
      formType: 'safety_report',
      title: `تقرير سلامة ميداني: ${rep.subject || 'تقرير'}`,
      hospital: 'المدينة الطبية بجامعة الملك سعود',
      building: rep.building || 'المستشفى',
      floor: `${rep.floor || 'الدور الأرضي (G)'}${rep.room && rep.room !== '-' ? ' - غرفة ' + rep.room : ''}`,
      inspector: rep.inspector || 'مفتش السلامة',
      inspectorUsername: '',
      badge: 'KSU-SAF-REP',
      shift: shiftKey,
      shiftName: getShiftLabel(shiftKey),
      date: rep.date || new Date().toISOString().split('T')[0],
      time: rep.time || '',
      complianceRate: 95,
      compliantCount: 1,
      observationCount: 0,
      violationCount: 0,
      notes: `${rep.details || ''}${rep.action ? ' | الإجراء: ' + rep.action : ''}`,
      workflowStatus: rep.workflowStatus || 'pending_quality',
      workflowStatusLabel: rep.workflowStatusLabel || 'بانتظار اعتماد قسم الجودة وتقييم الأداء',
      qualityReturnReason: rep.qualityReturnReason || '',
      qualityReturnNotes: rep.qualityReturnNotes || '',
      qualityNotes: rep.qualityNotes || '',
      headNotes: rep.headNotes || '',
      accreditationBodies: rep.accreditationBodies || 'CBAHI FMS / KSUMC Safety',
      approvedByQuality: rep.approvedByQuality || '',
      approvedByHead: rep.approvedByHead || '',
      workflowHistory: rep.workflowHistory || [],
      updatedAt: rep.updatedAt || rep.createdAt || new Date().toISOString(),
      updatedAtMs: rep.updatedAtMs || Date.now(),
      rawRef: rep
    });
  });

  // Also include any standalone records added directly to shift_inspection_logs
  try {
    const shiftRaw = localStorage.getItem(STORAGE_KEY_SHIFT_INSPECTION_LOGS);
    if (shiftRaw) {
      const shiftArr = JSON.parse(shiftRaw) || [];
      shiftArr.forEach(sr => {
        if (!sr || !sr.id) return;
        const key = String(sr.roundId || sr.id);
        if (!unifiedMap.has(key)) {
          unifiedMap.set(key, {
            id: key,
            sourceType: sr.sourceType || 'shift_log',
            formType: sr.modelId || 'all',
            title: sr.modelName || 'تفتيش ميداني للوردية',
            hospital: sr.hospital || 'المدينة الطبية بجامعة الملك سعود',
            building: sr.building || 'المستشفى',
            floor: sr.floor || 'الدور الأرضي (G)',
            inspector: sr.inspector || 'مفتش السلامة',
            badge: sr.employeeId || 'KSU-SAF',
            shift: sr.shift || 'shift1',
            shiftName: sr.shiftName || getShiftLabel(sr.shift || 'shift1'),
            date: sr.date || new Date().toISOString().split('T')[0],
            time: sr.time || '',
            complianceRate: typeof sr.complianceRate === 'number' ? sr.complianceRate : 100,
            compliantCount: 1,
            observationCount: sr.resultBadge === 'warning' ? 1 : 0,
            violationCount: sr.resultBadge === 'error' ? 1 : 0,
            notes: sr.deficiencyDescription || '',
            workflowStatus: sr.workflowStatus || 'pending_quality',
            workflowStatusLabel: sr.workflowStatusLabel || 'بانتظار اعتماد قسم الجودة وتقييم الأداء',
            qualityReturnReason: sr.qualityReturnReason || '',
            qualityReturnNotes: sr.qualityReturnNotes || '',
            qualityNotes: sr.qualityNotes || '',
            headNotes: sr.headNotes || '',
            accreditationBodies: sr.accreditationBodies || 'CBAHI FMS',
            approvedByQuality: sr.approvedByQuality || '',
            approvedByHead: sr.approvedByHead || '',
            workflowHistory: sr.workflowHistory || [],
            updatedAt: sr.updatedAt || new Date().toISOString(),
            updatedAtMs: sr.updatedAtMs || Date.now(),
            rawRef: sr
          });
        }
      });
    }
  } catch (e) {}

  return Array.from(unifiedMap.values()).sort((a, b) => {
    return (Number(b.updatedAtMs) || 0) - (Number(a.updatedAtMs) || 0);
  });
}

function filterQualityWorkflowInbox(filterKey) {
  qualityWorkflowActiveFilter = filterKey || 'all';
  document.querySelectorAll('.qwf-filter-btn').forEach(btn => {
    btn.className = 'qwf-filter-btn px-3 py-1.5 rounded-xl bg-surface-container hover:bg-surface-container-high text-on-surface font-bold text-xs transition-all';
  });
  const activeBtn = document.getElementById(`btn-qwf-${qualityWorkflowActiveFilter}`);
  if (activeBtn) {
    activeBtn.className = 'qwf-filter-btn px-3 py-1.5 rounded-xl bg-primary text-white font-black text-xs shadow-xs transition-all';
  }
  renderQualityWorkflowInbox();
}

function renderQualityWorkflowInbox() {
  const items = getUnifiedWorkflowItems();
  const pendingCount = items.filter(i => !i.workflowStatus || i.workflowStatus === 'pending_quality').length;
  const returnedCount = items.filter(i => i.workflowStatus === 'returned_by_quality' || i.workflowStatus === 'returned_by_head').length;
  const cbahiCount = items.filter(i => i.workflowStatus === 'approved_cbahi' || i.workflowStatus === 'approved_by_head').length;
  const headCount = items.filter(i => i.workflowStatus === 'forwarded_to_head').length;

  const elPending = document.getElementById('qwf-count-pending');
  const elReturned = document.getElementById('qwf-count-returned');
  const elCbahi = document.getElementById('qwf-count-cbahi');
  const elHead = document.getElementById('qwf-count-head');
  const elTotalBadge = document.getElementById('qwf-total-badge');

  if (elPending) elPending.textContent = pendingCount;
  if (elReturned) elReturned.textContent = returnedCount;
  if (elCbahi) elCbahi.textContent = cbahiCount;
  if (elHead) elHead.textContent = headCount;
  if (elTotalBadge) elTotalBadge.textContent = `${pendingCount} بانتظار الاعتماد`;

  const container = document.getElementById('quality-workflow-inbox-container');
  if (!container) return;

  let filtered = items;
  if (qualityWorkflowActiveFilter === 'pending_quality') {
    filtered = items.filter(i => !i.workflowStatus || i.workflowStatus === 'pending_quality');
  } else if (qualityWorkflowActiveFilter === 'returned_by_quality') {
    filtered = items.filter(i => i.workflowStatus === 'returned_by_quality' || i.workflowStatus === 'returned_by_head');
  } else if (qualityWorkflowActiveFilter === 'approved_cbahi') {
    filtered = items.filter(i => i.workflowStatus === 'approved_cbahi' || i.workflowStatus === 'approved_by_head');
  } else if (qualityWorkflowActiveFilter === 'forwarded_to_head') {
    filtered = items.filter(i => i.workflowStatus === 'forwarded_to_head');
  }

  if (filtered.length === 0) {
    container.innerHTML = `
      <div class="p-8 text-center bg-surface-container-low/50 rounded-2xl border border-dashed border-outline-variant">
        <span class="material-symbols-outlined text-4xl text-outline-variant mb-2">inbox</span>
        <p class="font-black text-sm text-primary">لا توجد تقارير أو جولات تفتيشية في هذا المسار حالياً (0)</p>
        <p class="text-xs text-on-surface-variant mt-1">عندما يقوم المفتش بحفظ التفتيش وإرساله لقسم الجودة وتقييم الأداء سيظهر هنا تلقائياً ولحظياً.</p>
      </div>
    `;
    return;
  }

  container.innerHTML = filtered.map(item => {
    const wfBadge = getWorkflowStatusBadgeHtml(item.workflowStatus, item.workflowStatusLabel);
    const isPending = !item.workflowStatus || item.workflowStatus === 'pending_quality';

    return `
      <div class="p-4 rounded-2xl bg-white border ${isPending ? 'border-amber-300 bg-amber-50/10' : 'border-outline-variant/40'} shadow-xs hover:shadow-md transition-all flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <div class="space-y-1.5">
          <div class="flex items-center gap-2 flex-wrap">
            <span class="font-mono text-xs font-black px-2 py-0.5 rounded bg-primary/10 text-primary">${item.id}</span>
            <h4 class="font-black text-sm text-primary">${item.title}</h4>
            ${wfBadge}
            <span class="px-2 py-0.5 rounded-full bg-surface-container text-on-surface-variant text-[10px] font-bold">${item.shiftName}</span>
          </div>
          <p class="text-xs text-on-surface-variant font-medium">
            المبنى: <strong class="text-on-surface">${item.building}</strong> (${item.floor}) •
            المفتش الرافع: <strong class="text-primary">${item.inspector}</strong> •
            التاريخ والوقت: <span class="font-mono">${item.date} ${item.time}</span> •
            نسبة المطابقة: <strong class="${item.complianceRate >= 90 ? 'text-emerald-700' : 'text-amber-700'}">${item.complianceRate}%</strong>
          </p>
          ${item.notes ? `<p class="text-xs text-gray-600 bg-surface-container-low px-3 py-1.5 rounded-lg border border-outline-variant/20">📋 البيان والملاحظات: ${item.notes}</p>` : ''}
          ${item.qualityReturnNotes ? `
            <p class="text-xs text-rose-900 bg-rose-50 px-3 py-1.5 rounded-lg border border-rose-200 font-bold">
              ↩️ سبب الرد للمفتش (${item.qualityReturnReason || 'ملاحظات ونواقص'}): ${item.qualityReturnNotes}
            </p>
          ` : ''}
          ${item.qualityNotes && item.workflowStatus !== 'returned_by_quality' ? `
            <p class="text-xs text-emerald-900 bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-200 font-bold">
              ✅ قرار وملاحظات الجودة (${item.approvedByQuality || 'قسم الجودة'}): ${item.qualityNotes}
            </p>
          ` : ''}
          ${item.headNotes ? `
            <p class="text-xs text-indigo-950 bg-indigo-50 px-3 py-1.5 rounded-lg border border-indigo-200 font-bold">
              🏅 اعتماد وتوجيه رئيس القسم (${item.approvedByHead || 'رئيس القسم'}): ${item.headNotes}
            </p>
          ` : ''}
        </div>

        <div class="flex items-center gap-2 flex-wrap shrink-0">
          <button type="button" onclick="openQualityWorkflowReviewModal('${item.id}')" class="px-3.5 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-black text-xs shadow-sm transition-all flex items-center gap-1.5">
            <span class="material-symbols-outlined text-sm">fact_check</span>
            <span>اتخاذ قرار الجودة (اعتماد سباهي / إحالة لرئيس القسم / رد للمفتش)</span>
          </button>
          <button type="button" onclick="${item.sourceType === 'safety_report' ? `previewSafetyDeptReport('${item.id}')` : `viewRoundDetails('${item.id}')`}" class="px-3 py-2 rounded-xl bg-surface-container hover:bg-surface-container-high text-primary font-bold text-xs transition-all flex items-center gap-1">
            <span class="material-symbols-outlined text-sm">visibility</span>
            <span>التفاصيل</span>
          </button>
        </div>
      </div>
    `;
  }).join('');
}

